import{$ as e,Ft as t,bt as n,gt as r,jt as i,pt as a,vt as o,yt as s}from"./chunks/framework.CbVAkGq1.js";var c=JSON.parse(`{"title":"第六章：联邦公报法令与行政依据编年史","titleTemplate":"管制物质：化学与法律指南 · 亚历山大·舒尔金","description":"","frontmatter":{"title":"第六章：联邦公报法令与行政依据编年史","titleTemplate":"管制物质：化学与法律指南 · 亚历山大·舒尔金"},"headers":[],"relativePath":"en/controlled-substances/chapter-6.md","filePath":"en/controlled-substances/chapter-6.md"}`),l={name:`en/controlled-substances/chapter-6.md`};function u(e,c,l,u,d,f){let p=t(`NolebasePageProperties`),m=t(`NolebaseGitContributors`),h=t(`NolebaseGitChangelog`);return i(),r(`div`,null,[c[0]||=a(`h1`,{id:`第六章-联邦公报法令与行政依据编年史-federal-register-citations`,tabindex:`-1`},[s(`第六章：联邦公报法令与行政依据编年史 (Federal Register Citations) `),a(`a`,{class:`header-anchor`,href:`#第六章-联邦公报法令与行政依据编年史-federal-register-citations`,"aria-label":`Permalink to “第六章：联邦公报法令与行政依据编年史 (Federal Register Citations)”`},`​`),s(),a(`a`,{class:`header-anchor`,href:`#第六章-联邦公报法令与行政依据编年史-federal-register-citations`,"aria-label":`Permalink to “第六章：联邦公报法令与行政依据编年史 (Federal Register Citations)”`},`​`)],-1),n(p),c[1]||=o(`<blockquote><p><strong>著者</strong>：Alexander T. Shulgin, Ph.D.（亚历山大·T·舒尔金 博士）<br><strong>出处</strong>：<em>Controlled Substances: A Chemical and Legal Guide to the Federal Drug Laws (2nd Edition, 1992)</em>, Chapter 6, pp. 351–378.<br><strong>学术翻译规范</strong>：本章遵照美国行政法学与毒理学标准，对原书第 337 至 364 页所收录自 1966 年至 1991 年 4 月 1 日共计 <strong>345 项《联邦公报》正式法令、听证报告与行政命令</strong>展开<strong>逐卷、逐页、逐日期的完整中文翻译</strong>。</p></blockquote><hr><h2 id="本章导读-亚历山大·t·舒尔金-著" tabindex="-1">本章导读（亚历山大·T·舒尔金 著） <a class="header-anchor" href="#本章导读-亚历山大·t·舒尔金-著" aria-label="Permalink to “本章导读（亚历山大·T·舒尔金 著）”">​</a> <a class="header-anchor" href="#本章导读-亚历山大·t·舒尔金-著" aria-label="Permalink to “本章导读（亚历山大·T·舒尔金 著）”">​</a></h2><p>本章完整收录了美国《联邦公报》（<em>Federal Register</em>，简称 <strong>FR</strong>）中所有直接适用于授权或变更《受管制物质法》（CSA）药物管制地位的全部法定条目。</p><p>任何法律及其修正案，都必须委托给具体的行政执法机构予以执行。在实际执行过程中，偶尔需要对立法者起草法律时的真实意图进行行政释法，并且极为频繁地需要确立执法实践所需的操作指南与行政规章。所有此类针对法律管辖范围的增补、移出、重排或豁免，<strong>依法必须向全社会公开公开发布</strong>，而其法定的国家级发布载体，正是《联邦公报》。</p><p>以现行联邦药物法为例，向现有法律框架中增补一种新药必须严格履行法定的行政程序：当某种药物因出现前所未有的滥用危机或突发公共危害，需要改变其执法管制状态时，获授权的高级官员（如美国司法部长 Attorney General 或其授权的 DEA 局长）会在《联邦公报》上公开发布一项拟定规则制定通告（Notice of Proposed Rulemaking）。法令强制规定预留 <strong>60 天</strong> 的法定公众评议期，在此期间公众与利益相关方可提交书面抗辩或正式申请召开听证会（Hearings）。若在评议期内无任何异议，则随后公报将发布包含法定条文变更的最终裁决命令（Final Order），该药物即正式被纳入管制附表。</p><p>在 1960 年代末期，联邦政府曾投入巨大的行政力量，试图将一批在当时的医学界极受欢迎、但社会滥用隐患日益凸显的精神类处方药物纳入严格限制管控。例如<strong>甲丙氨酯（Meprobamate / Miltown）</strong>，以及苯二氮䓬类镇静剂<strong>利眠宁（Chlordiazepoxide / Librium）</strong>与<strong>安定（Diazepam / Valium）</strong>——这些药物在临床上广泛处方，但滥用案例呈爆发性增长。制药工业界与联邦政府之间长达数年的拉锯、博弈与剧烈冲突，在《联邦公报》的数十次你来我往的公报条目中展现得淋漓尽致。必须牢记的是，制药巨头与联邦监管机构之间的长久共生关系，要求药企始终保持一种精妙的警惕与清醒：<strong>那只看似要限制你、如同敌人般的管制之手，正是日后批准你新药合法上市时不可或缺的盟友之手。</strong></p><p>本章所有引证均严格按《联邦公报》的<strong>卷号、页码及正式出版日期</strong>（Volume, Page, Date）编排，内容完整收录截至 <strong>1991 年 4 月 1 日</strong>。</p><hr><h2 id="_1966-—-1969-年-早期药物滥用控制修正案与管制定案" tabindex="-1">1966 — 1969 年：早期药物滥用控制修正案与管制定案 <a class="header-anchor" href="#_1966-—-1969-年-早期药物滥用控制修正案与管制定案" aria-label="Permalink to “1966 — 1969 年：早期药物滥用控制修正案与管制定案”">​</a> <a class="header-anchor" href="#_1966-—-1969-年-早期药物滥用控制修正案与管制定案" aria-label="Permalink to “1966 — 1969 年：早期药物滥用控制修正案与管制定案”">​</a></h2><h3 id="_31-fr5434-april-6-1966" tabindex="-1">31 FR5434 (April 6, 1966) <a class="header-anchor" href="#_31-fr5434-april-6-1966" aria-label="Permalink to “31 FR5434 (April 6, 1966)”">​</a> <a class="header-anchor" href="#_31-fr5434-april-6-1966" aria-label="Permalink to “31 FR5434 (April 6, 1966)”">​</a></h3><p>财政部此前将 Piritramide 归类为阿片类药物（Opiate）的行政决定（参见 29 FR 19241）被正式撤销；依据世界卫生组织（WHO）的最新国际权威决议，现对该物质重新进行法律归类。</p><h3 id="_31-fr7174-may-17-1966" tabindex="-1">31 FR7174 (May 17, 1966) <a class="header-anchor" href="#_31-fr7174-may-17-1966" aria-label="Permalink to “31 FR7174 (May 17, 1966)”">​</a> <a class="header-anchor" href="#_31-fr7174-may-17-1966" aria-label="Permalink to “31 FR7174 (May 17, 1966)”">​</a></h3><p>针对此前修订法律分类架构的行政命令（参见 31 FR 4679）收到了正式异议。官方将举行公开行政听证会以听取关于 Chlordiazepoxide, Diazepam, and Meprobamate 的答辩抗辩意见。关于前两种药物的听证会最终报告参见 34 FR 7963；关于 Meprobamate 的听证会报告参见 32 FR 5933 and 32 FR 17473，关于后者的预备协调听证会通知参见 31 FR 7573。此外，关于将 LSD 纳入管制目录的一项单独听证会申请已被正式驳回。</p><h3 id="_31fr7245-may-18-1966" tabindex="-1">31FR7245 (May 18, 1966) <a class="header-anchor" href="#_31fr7245-may-18-1966" aria-label="Permalink to “31FR7245 (May 18, 1966)”">​</a> <a class="header-anchor" href="#_31fr7245-may-18-1966" aria-label="Permalink to “31FR7245 (May 18, 1966)”">​</a></h3><p>这是拟将 Lysergic Acid and Lysergic Acid Amide 纳入受管制药物目录的初步拟定规则提案。列管法定依据如下：(1) 其被作为地下非法秘密合成 LSD 的起始原料；(2) 涉及从合法医药商业渠道大量流失非法黑市，并被用于制造 LSD 以供非法走私与分销；(3) 尽管尚无充分确凿证据证实其自身具有致幻性，但其对中枢神经系统具有明显的抑制作用，且一旦转化为 LSD 即可产生极其强烈的致幻效应。最终行政决定参见 31 FR 9492。</p><h3 id="_31fr7573-may-21-1966" tabindex="-1">31FR7573 (May 21, 1966) <a class="header-anchor" href="#_31fr7573-may-21-1966" aria-label="Permalink to “31FR7573 (May 21, 1966)”">​</a> <a class="header-anchor" href="#_31fr7573-may-21-1966" aria-label="Permalink to “31FR7573 (May 21, 1966)”">​</a></h3><p>就拟将 Meprobamate 正式列为受管制药物所涉及的法律争议，发布召开追加预备听证协调会议的正式官方通知。</p><h3 id="_31-fr9492-july-13-1966" tabindex="-1">31 FR9492 (July 13, 1966) <a class="header-anchor" href="#_31-fr9492-july-13-1966" aria-label="Permalink to “31 FR9492 (July 13, 1966)”">​</a> <a class="header-anchor" href="#_31-fr9492-july-13-1966" aria-label="Permalink to “31 FR9492 (July 13, 1966)”">​</a></h3><p>关于将 Lysergic Acid and Lysergic Acid Amide 正式纳入政府法律管制目录的最终行政裁决生效命令。初步拟定提案参见 31 FR 7245。</p><h3 id="_31-fr9540-july-14-1966" tabindex="-1">31 FR9540 (July 14, 1966) <a class="header-anchor" href="#_31-fr9540-july-14-1966" aria-label="Permalink to “31 FR9540 (July 14, 1966)”">​</a> <a class="header-anchor" href="#_31-fr9540-july-14-1966" aria-label="Permalink to “31 FR9540 (July 14, 1966)”">​</a></h3><p>将 DMT and LSD 两种药物正式增补列入致幻剂专属管制清单；未经联邦官方事先书面审查批准，严禁将其用于任何人体临床试验、动物实验或体外离体（in vitro）科研。相关审批程序架构详见 33 FR 2384。</p><h3 id="_31-fr9752-july-19-1966" tabindex="-1">31 FR9752 (July 19, 1966) <a class="header-anchor" href="#_31-fr9752-july-19-1966" aria-label="Permalink to “31 FR9752 (July 19, 1966)”">​</a> <a class="header-anchor" href="#_31-fr9752-july-19-1966" aria-label="Permalink to “31 FR9752 (July 19, 1966)”">​</a></h3><p>关于重新调整审理将 Chlordiazepoxide and Diazepam 纳入管制药物听证会议程时间的正式公告。前序程序参见 31 FR 7174。</p><h3 id="_31-fr-10039-july-23-1966" tabindex="-1">31 FR 10039 (July 23, 1966) <a class="header-anchor" href="#_31-fr-10039-july-23-1966" aria-label="Permalink to “31 FR 10039 (July 23, 1966)”">​</a> <a class="header-anchor" href="#_31-fr-10039-july-23-1966" aria-label="Permalink to “31 FR 10039 (July 23, 1966)”">​</a></h3><p>这是拟将 six depressant drugs 纳入受管制药物目录的初步提议通告。涉及的具体化学品为：Chloral Betaine, Chlorhexadol, Petrichloral, Sulfondiethylmethane, Sulfonethylmethane and Sulfonmethane。最终裁决命令参见 FR 12435。</p><h3 id="_31-fr-12435-september-20-1966" tabindex="-1">31 FR 12435 (September 20, 1966) <a class="header-anchor" href="#_31-fr-12435-september-20-1966" aria-label="Permalink to “31 FR 12435 (September 20, 1966)”">​</a> <a class="header-anchor" href="#_31-fr-12435-september-20-1966" aria-label="Permalink to “31 FR 12435 (September 20, 1966)”">​</a></h3><p>关于将 six depressant drugs（初步提案参见 31 FR 10039）正式纳入受管制药物目录的最终行政裁决通告。法定正式声明刊发于 31 FR 14830。</p><h3 id="_31-fr-14830-november-23-1966" tabindex="-1">31 FR 14830 (November 23, 1966) <a class="header-anchor" href="#_31-fr-14830-november-23-1966" aria-label="Permalink to “31 FR 14830 (November 23, 1966)”">​</a> <a class="header-anchor" href="#_31-fr-14830-november-23-1966" aria-label="Permalink to “31 FR 14830 (November 23, 1966)”">​</a></h3><p>正式将 six depressants 依法打入受管制药物名录生效公告。参见 31 FR 12435 与 31 FR 10039。 | 32 FR 5933 = (April 13, 1967) Thisisa statement of the findings of fact related to the proposal that Meprobamate be listed as a controlled drug. For the original proposal, see 31 FR 565 and for the initial order recommending control, see 31 FR 4879. For further arguments, see 32 FR 17473.</p><h3 id="_32-fr-10308-july-13-1967" tabindex="-1">32 FR 10308 (July 13, 1967) <a class="header-anchor" href="#_32-fr-10308-july-13-1967" aria-label="Permalink to “32 FR 10308 (July 13, 1967)”">​</a> <a class="header-anchor" href="#_32-fr-10308-july-13-1967" aria-label="Permalink to “32 FR 10308 (July 13, 1967)”">​</a></h3><p>This is the 初步拟定规则提案 for placing Bufotenine, DET, and Ibogaine into 附表一 (Schedule I) as controlled drugs. See 32 FR 13407 for 最终行政裁决命令, which became official in 32 FR 15340. No documentation for the 致幻性 action of any of these drugs is made available.</p><h3 id="_32-fr-13407-september-23-1967" tabindex="-1">32 FR 13407 (September 23, 1967) <a class="header-anchor" href="#_32-fr-13407-september-23-1967" aria-label="Permalink to “32 FR 13407 (September 23, 1967)”">​</a> <a class="header-anchor" href="#_32-fr-13407-september-23-1967" aria-label="Permalink to “32 FR 13407 (September 23, 1967)”">​</a></h3><p>The listing of three drugs as hallucinogens (see 32 FR 10308) has been made final, with 60 days within which to register objections. See 32 FR 15340 for the official 最终行政裁决命令.</p><h3 id="_32-fr-15340-november-3-1967" tabindex="-1">32 FR 15340 (November 3, 1967) <a class="header-anchor" href="#_32-fr-15340-november-3-1967" aria-label="Permalink to “32 FR 15340 (November 3, 1967)”">​</a> <a class="header-anchor" href="#_32-fr-15340-november-3-1967" aria-label="Permalink to “32 FR 15340 (November 3, 1967)”">​</a></h3><p>Official, final word on the listing of Bufotenine, DET, and Ibogaine as hallucinogens and their placement on the controlled drug list. See 32 FR 10308 for the 初步拟定规则提案.</p><h3 id="_32-fr-16048-november-22-1967" tabindex="-1">32 FR 16048 (November 22, 1967) <a class="header-anchor" href="#_32-fr-16048-november-22-1967" aria-label="Permalink to “32 FR 16048 (November 22, 1967)”">​</a> <a class="header-anchor" href="#_32-fr-16048-november-22-1967" aria-label="Permalink to “32 FR 16048 (November 22, 1967)”">​</a></h3><p>This is the 初步拟定规则提案 for the placement of DOM on the controlled drug list. See 33 FR 2511 and 33 FR 4734 for notice of 最终行政裁决命令.</p><h3 id="_32-fr-17473-december-6-1967" tabindex="-1">32 FR 17473 (December 6, 1967) <a class="header-anchor" href="#_32-fr-17473-december-6-1967" aria-label="Permalink to “32 FR 17473 (December 6, 1967)”">​</a> <a class="header-anchor" href="#_32-fr-17473-december-6-1967" aria-label="Permalink to “32 FR 17473 (December 6, 1967)”">​</a></h3><p>This is an extensive further finding of fact, and arguments, concerning the proposal to place Meprobamate under control. See 33 FR 3635 for a stay of this order.</p><h3 id="_33-fr-2384-january-31-1968" tabindex="-1">33 FR 2384 (January 31, 1968) <a class="header-anchor" href="#_33-fr-2384-january-31-1968" aria-label="Permalink to “33 FR 2384 (January 31, 1968)”">​</a> <a class="header-anchor" href="#_33-fr-2384-january-31-1968" aria-label="Permalink to “33 FR 2384 (January 31, 1968)”">​</a></h3><p>This is a statement of conditions that must be met, before certain 致幻性 drugs (named) may be investigated in research. For in vitro studies, or for research animal studies, advanced approval from the Commissioner of Food and Drugs must be obtained. For clinical studies in man this approval must be based on a Notice of Claimed Investigational Exemption from the FDA.</p><h3 id="_33-fr2511-february-2-1968" tabindex="-1">33 FR2511 (February 2, 1968) <a class="header-anchor" href="#_33-fr2511-february-2-1968" aria-label="Permalink to “33 FR2511 (February 2, 1968)”">​</a> <a class="header-anchor" href="#_33-fr2511-february-2-1968" aria-label="Permalink to “33 FR2511 (February 2, 1968)”">​</a></h3><p>This is the 最终行政裁决命令 for the listing of DOM as a drug subject tocontrol. See 32 FR 16048 for the 初步拟定规则提案. See 33 FR 4734 for the official 最终行政裁决命令.</p><h3 id="_33-fr-3635-march-1-1968" tabindex="-1">33 FR 3635 (March 1, 1968) <a class="header-anchor" href="#_33-fr-3635-march-1-1968" aria-label="Permalink to “33 FR 3635 (March 1, 1968)”">​</a> <a class="header-anchor" href="#_33-fr-3635-march-1-1968" aria-label="Permalink to “33 FR 3635 (March 1, 1968)”">​</a></h3><p>This is a staying of the 最终命令 to bring Meprobamate under control. See 32 FR 17473 for the initial order, and 35 FR 10857 for the withdrawal of this stay.</p><h3 id="_33-fr-4734-march-20-1968" tabindex="-1">33 FR 4734 (March 20, 1968) <a class="header-anchor" href="#_33-fr-4734-march-20-1968" aria-label="Permalink to “33 FR 4734 (March 20, 1968)”">​</a> <a class="header-anchor" href="#_33-fr-4734-march-20-1968" aria-label="Permalink to “33 FR 4734 (March 20, 1968)”">​</a></h3><p>The official 最终行政裁决命令 for the placing of DOM under control. See 33 FR 2511 for the actual order.</p><h3 id="_33-fr-5580-april-10-1968" tabindex="-1">33 FR 5580 (April 10, 1968) <a class="header-anchor" href="#_33-fr-5580-april-10-1968" aria-label="Permalink to “33 FR 5580 (April 10, 1968)”">​</a> <a class="header-anchor" href="#_33-fr-5580-april-10-1968" aria-label="Permalink to “33 FR 5580 (April 10, 1968)”">​</a></h3><p>. The delegation of authority to the Justice Department to form and accept the BNDD as a consequence of the Reorganization Plan No. 1 of 1968 (see 33 FR 5611).</p><h3 id="_33-fr5611-april-11-1968" tabindex="-1">33 FR5611 (April 11, 1968) <a class="header-anchor" href="#_33-fr5611-april-11-1968" aria-label="Permalink to “33 FR5611 (April 11, 1968)”">​</a> <a class="header-anchor" href="#_33-fr5611-april-11-1968" aria-label="Permalink to “33 FR5611 (April 11, 1968)”">​</a></h3><p>This is the statement of President Johnson’s Reorganization Plan No. 1 of 1968 (transmitted to Congress on February 6, 1968) for the merging of the Bureau of Narcotics (BN, Dept. of Treasury) and the functions of the HEW under the Drug Abuse Control Amendments (BDAC, Dept. of HEW) into the 麻醉品与危险药物管理局 (BNDD) (BNDD, Dept. of Justice).</p><h3 id="_33-fr-8666-june-13-1968" tabindex="-1">33 FR 8666 (June 13, 1968) <a class="header-anchor" href="#_33-fr-8666-june-13-1968" aria-label="Permalink to “33 FR 8666 (June 13, 1968)”">​</a> <a class="header-anchor" href="#_33-fr-8666-june-13-1968" aria-label="Permalink to “33 FR 8666 (June 13, 1968)”">​</a></h3><p>The controlled drug DOM is added to the list of hallucinogens requiring approval for research (see 33 FR 2384).</p><h3 id="_33-fr-9833-july-9-1968" tabindex="-1">33 FR 9833 (July 9, 1968) <a class="header-anchor" href="#_33-fr-9833-july-9-1968" aria-label="Permalink to “33 FR 9833 (July 9, 1968)”">​</a> <a class="header-anchor" href="#_33-fr-9833-july-9-1968" aria-label="Permalink to “33 FR 9833 (July 9, 1968)”">​</a></h3><p>The BNDD recommends the inclusion of the “synthesized Tetrahydrocannibinols” as subject to control. The delta-1 and delta-6 isomers are named as cis or trans and their optical isomers are noted. The delta-3,4 is listed only with optical isomers. In the initial publication of the 受控物质法案 (CSA), this all was subsumed under the single term, Tetrahydrocannabinol, but in the 1972 printing a “cis or trans isomer” term became attached to the delta-3,4.</p><h3 id="_33-fr-11814-august-21-1968" tabindex="-1">33 FR 11814 (August 21, 1968) <a class="header-anchor" href="#_33-fr-11814-august-21-1968" aria-label="Permalink to “33 FR 11814 (August 21, 1968)”">​</a> <a class="header-anchor" href="#_33-fr-11814-august-21-1968" aria-label="Permalink to “33 FR 11814 (August 21, 1968)”">​</a></h3><p>This is a 最终行政裁决命令 adding the names of synthetic compounds similar to the Tetrahydrocannabinol of Marihuana, as being subject to control. See 33 FR 14888 and 34 FR 15295 for 最终行政裁决命令.</p><h3 id="_33-fr-14818-october-3-1968" tabindex="-1">33 FR 14818 (October 3, 1968) <a class="header-anchor" href="#_33-fr-14818-october-3-1968" aria-label="Permalink to “33 FR 14818 (October 3, 1968)”">​</a> <a class="header-anchor" href="#_33-fr-14818-october-3-1968" aria-label="Permalink to “33 FR 14818 (October 3, 1968)”">​</a></h3><p>. The complete listing of all enforcement regulations and changes required in the laws to effectively merge the Bureau of Narcotics and the Bureau of Drug Abuse Control into the 麻醉品与危险药物管理局 (BNDD), under the Department of Justice. This large document (36 pages) contains much information, including acomplete listing of all drugs listed as under control at the time of the administrative reorganization. These drugs may well have been those that Congress intended to be incorporated into law, when the Controlled Substance Act was enacted some two years later.</p><h3 id="_33-fr-14880-october-4-1968" tabindex="-1">33 FR 14880 (October 4, 1968) <a class="header-anchor" href="#_33-fr-14880-october-4-1968" aria-label="Permalink to “33 FR 14880 (October 4, 1968)”">​</a> <a class="header-anchor" href="#_33-fr-14880-october-4-1968" aria-label="Permalink to “33 FR 14880 (October 4, 1968)”">​</a></h3><p>The final official order for the placing of the synthetic analogs of Tetrahydrocannabinol under control. See 33 FR 11814 for the proposed 最终行政裁决命令. See, also, 34 FR 15295. The 初步拟定规则提案 is at 33 FR 9833.</p><h3 id="_34-fr-496-january-14-1969" tabindex="-1">34 FR 496 (January 14, 1969) <a class="header-anchor" href="#_34-fr-496-january-14-1969" aria-label="Permalink to “34 FR 496 (January 14, 1969)”">​</a> <a class="header-anchor" href="#_34-fr-496-january-14-1969" aria-label="Permalink to “34 FR 496 (January 14, 1969)”">​</a></h3><p>The classification of Bezitramide as an Opiate, to stay in concordance with the World Health Organization.</p><h3 id="_34fr1168-january-24-1969" tabindex="-1">34FR1168 (January 24, 1969) <a class="header-anchor" href="#_34fr1168-january-24-1969" aria-label="Permalink to “34FR1168 (January 24, 1969)”">​</a> <a class="header-anchor" href="#_34fr1168-january-24-1969" aria-label="Permalink to “34FR1168 (January 24, 1969)”">​</a></h3><p>This is the 初步拟定规则提案 to list Methylphenidate as subject to control as a 中枢兴奋剂 drug. See 34 FR 4888 for 最终行政裁决命令.</p><h3 id="_34-fr1400-january-29-1969" tabindex="-1">34 FR1400 (January 29, 1969) <a class="header-anchor" href="#_34-fr1400-january-29-1969" aria-label="Permalink to “34 FR1400 (January 29, 1969)”">​</a> <a class="header-anchor" href="#_34-fr1400-january-29-1969" aria-label="Permalink to “34 FR1400 (January 29, 1969)”">​</a></h3><p>This is the 初步拟定规则提案 for the listing of Phencyclidine as being subject to control as a 中枢抑制剂.</p><h3 id="_34-fr-4888-march-6-1969" tabindex="-1">34 FR 4888 (March 6, 1969) <a class="header-anchor" href="#_34-fr-4888-march-6-1969" aria-label="Permalink to “34 FR 4888 (March 6, 1969)”">​</a> <a class="header-anchor" href="#_34-fr-4888-march-6-1969" aria-label="Permalink to “34 FR 4888 (March 6, 1969)”">​</a></h3><p>This is the 最终行政裁决命令 on the listing of Methylphenidate as a 中枢兴奋剂 subject to control. See 34 FR 1168 for the 初步拟定规则提案. This order became effective on April 7, 1969, see 34 FR 6685. 34 FR6685_ (April 19, 1969) This is the effective order listing Methylphenidate and Phencyclidine as drugs subject to control. See 34 FR 1400 for the 初步拟定规则提案 for Phencyclidine, and 34 FR 4888 for the initial listing for Methylphenidate.</p><h3 id="_34-fr7963-may-21-1969" tabindex="-1">34 FR7963 (May 21, 1969) <a class="header-anchor" href="#_34-fr7963-may-21-1969" aria-label="Permalink to “34 FR7963 (May 21, 1969)”">​</a> <a class="header-anchor" href="#_34-fr7963-may-21-1969" aria-label="Permalink to “34 FR7963 (May 21, 1969)”">​</a></h3><p>A proposal of findings of fact that argue for the bringing of Chlordiazepoxide and Diazepam under the control and authority of the Drug Abuse Control Amendments. See 35 FR 5695 for the 行政听证会s record, and 35 FR 17998 for the findings of fact that followed from the 行政听证会s. There is a tentative order placing these drugs under control. See 31 FR 565 for the earliest efforts in this matter. See 34 FR 9717 for an extension of the time period allowed, and 34 FR 17390 for approval of oral arguments.</p><h3 id="_34-fr9717-june-21-1969" tabindex="-1">34 FR9717 (June 21, 1969) <a class="header-anchor" href="#_34-fr9717-june-21-1969" aria-label="Permalink to “34 FR9717 (June 21, 1969)”">​</a> <a class="header-anchor" href="#_34-fr9717-june-21-1969" aria-label="Permalink to “34 FR9717 (June 21, 1969)”">​</a></h3><p>An extension of time is allowed for comments regarding the tentative controls placed on Chlordiazepoxide and Diazepam. See 34 FR 7963.</p><h3 id="_34-fr-9871-june-26-1969" tabindex="-1">34 FR 9871 (June 26, 1969) <a class="header-anchor" href="#_34-fr-9871-june-26-1969" aria-label="Permalink to “34 FR 9871 (June 26, 1969)”">​</a> <a class="header-anchor" href="#_34-fr-9871-june-26-1969" aria-label="Permalink to “34 FR 9871 (June 26, 1969)”">​</a></h3><p>Anotice of the receipt of a 行政请愿申请 requesting exemption of the controls on Peyote for use in the Church - of the Awakening. See 35 FR 2874 and 35 FR 14789 for extensive records of these 行政听证会s (the request was 被依法驳回).</p><h3 id="_34-fr-15295-october-1-1969" tabindex="-1">34 FR 15295 (October 1, 1969) <a class="header-anchor" href="#_34-fr-15295-october-1-1969" aria-label="Permalink to “34 FR 15295 (October 1, 1969)”">​</a> <a class="header-anchor" href="#_34-fr-15295-october-1-1969" aria-label="Permalink to “34 FR 15295 (October 1, 1969)”">​</a></h3><p>Thisis a final notice listing (by name) the analogs of Tetrahydrocannibinol (THC) which are considered as the synthetic equivalents (similar in chemistry and pharmacology) to the natural THC in the Cannabis plant. The original order is found at 33 FR 11814.</p><h3 id="_34-fr-17390-october-28-1969" tabindex="-1">34 FR 17390 (October 28, 1969) <a class="header-anchor" href="#_34-fr-17390-october-28-1969" aria-label="Permalink to “34 FR 17390 (October 28, 1969)”">​</a> <a class="header-anchor" href="#_34-fr-17390-october-28-1969" aria-label="Permalink to “34 FR 17390 (October 28, 1969)”">​</a></h3><p>This is a request (获得正式批准) for oral arguments to be made in the matter of the placing of Chlordiazepoxide and Diazepam under control. See 34 FR 7963.</p><h3 id="_34-fr-19660-december-13-1969" tabindex="-1">34 FR 19660 (December 13, 1969) <a class="header-anchor" href="#_34-fr-19660-december-13-1969" aria-label="Permalink to “34 FR 19660 (December 13, 1969)”">​</a> <a class="header-anchor" href="#_34-fr-19660-december-13-1969" aria-label="Permalink to “34 FR 19660 (December 13, 1969)”">​</a></h3><p>This is a proposal to add Tetrahydrocannabinol and its similar synthetic equivalents to the list of 致幻性 drugs that may not be tested in man, or used for in vitro studies or research animal testing without advance approval. See 33 FR 2384 for the details of this needed approval. See 35 FR 2411 for additions and extensions.</p><h2 id="_1970-—-1974-年-csa-确立五级附表体系与安非他命类升格" tabindex="-1">1970 — 1974 年：CSA 确立五级附表体系与安非他命类升格 <a class="header-anchor" href="#_1970-—-1974-年-csa-确立五级附表体系与安非他命类升格" aria-label="Permalink to “1970 — 1974 年：CSA 确立五级附表体系与安非他命类升格”">​</a> <a class="header-anchor" href="#_1970-—-1974-年-csa-确立五级附表体系与安非他命类升格" aria-label="Permalink to “1970 — 1974 年：CSA 确立五级附表体系与安非他命类升格”">​</a></h2><h3 id="_35-fr-2411-february-3-1970" tabindex="-1">35 FR 2411 (February 3, 1970) <a class="header-anchor" href="#_35-fr-2411-february-3-1970" aria-label="Permalink to “35 FR 2411 (February 3, 1970)”">​</a> <a class="header-anchor" href="#_35-fr-2411-february-3-1970" aria-label="Permalink to “35 FR 2411 (February 3, 1970)”">​</a></h3><p>The suggested addition of tetrahydrocannabinols to the proposal published in 34 FR 19660. Also, an extension of time for comments is allowed.</p><h3 id="_35-fr-2874-february-12-1970" tabindex="-1">35 FR 2874 (February 12, 1970) <a class="header-anchor" href="#_35-fr-2874-february-12-1970" aria-label="Permalink to “35 FR 2874 (February 12, 1970)”">​</a> <a class="header-anchor" href="#_35-fr-2874-february-12-1970" aria-label="Permalink to “35 FR 2874 (February 12, 1970)”">​</a></h3><p>A lengthy transcript of the 行政听证会s held (see 34 FR 9871 for the initial request) to evaluate the 行政请愿申请 from the Church of the Awakening for the use of Peyote in their religious rites (as is allowed for the Native American Church). The 行政请愿申请 is 被依法驳回. See 35 FR 14789 for an extensive statement of fact-finding on the part of the Government.</p><h3 id="_35-fr-4305-march-10-1970" tabindex="-1">35 FR 4305 (March 10, 1970) <a class="header-anchor" href="#_35-fr-4305-march-10-1970" aria-label="Permalink to “35 FR 4305 (March 10, 1970)”">​</a> <a class="header-anchor" href="#_35-fr-4305-march-10-1970" aria-label="Permalink to “35 FR 4305 (March 10, 1970)”">​</a></h3><p>A proposal is made for the listing of MDA, MMDA, TMA, JB-318 and JB-336 and their salts and isomers as subject to control. In this proposal, every positional isomer of each of these is explicitly named, by position number. Also, the term “optical” is given as an example of isomer for the first three, but ignored for the two JB compounds which can, of course, also possess optical isomers. See 35 FR 7069 for 最终行政裁决命令. 35 FR 5695_—— (April 8, 1970) The proposal to bring Chlordiazepoxide and Diazepam subject to control under the Drug Abuse Control Amendments (see 34 FR 7963) requires additional 行政听证会s; these are scheduled. See 35 FR 17998 for a record of the finds of fact in this matter.</p><h3 id="_35-fr-7069-may-5-1970" tabindex="-1">35 FR 7069 (May 5, 1970) <a class="header-anchor" href="#_35-fr-7069-may-5-1970" aria-label="Permalink to “35 FR 7069 (May 5, 1970)”">​</a> <a class="header-anchor" href="#_35-fr-7069-may-5-1970" aria-label="Permalink to “35 FR 7069 (May 5, 1970)”">​</a></h3><p>This is the 最终行政裁决命令 on the proposed listing of several drugs and their isomers as being controlled under the Drug Abuse Control Amendments (1965) of the Federal Food, Drug and Cosmetic Act of 1938. MDA, MMDA and TMA were listed (with optical and positional isomers) in the form used with their 初步拟定规则提案. The two N-alkyl piperidyl benzilates (and their explicit positional isomers) were also listed, but their quaternary salts were officially designated as not being salts, and were excluded from control. This 最终命令 was confirmed, see 35 FR 12461.</p><h3 id="_35-fr-10857-july-3-1970" tabindex="-1">35 FR 10857 (July 3, 1970) <a class="header-anchor" href="#_35-fr-10857-july-3-1970" aria-label="Permalink to “35 FR 10857 (July 3, 1970)”">​</a> <a class="header-anchor" href="#_35-fr-10857-july-3-1970" aria-label="Permalink to “35 FR 10857 (July 3, 1970)”">​</a></h3><p>The ending of the stay on the listing of Meprobamate as a drug subject to control (see 32 FR 17473 for the 最终命令 that had been stayed). A typographical error in this notice is corrected in 35 FR Ad125:</p><h3 id="_35-fr-11125-july-10-1970" tabindex="-1">35 FR 11125 (July 10, 1970) <a class="header-anchor" href="#_35-fr-11125-july-10-1970" aria-label="Permalink to “35 FR 11125 (July 10, 1970)”">​</a> <a class="header-anchor" href="#_35-fr-11125-july-10-1970" aria-label="Permalink to “35 FR 11125 (July 10, 1970)”">​</a></h3><p>A minor typographical correction to 35 FR 10857.</p><h3 id="_35-fr-12461-august-5-1970" tabindex="-1">35 FR 12461 (August 5, 1970) <a class="header-anchor" href="#_35-fr-12461-august-5-1970" aria-label="Permalink to “35 FR 12461 (August 5, 1970)”">​</a> <a class="header-anchor" href="#_35-fr-12461-august-5-1970" aria-label="Permalink to “35 FR 12461 (August 5, 1970)”">​</a></h3><p>Aconfirmation of the order of 35 FR 7069, listing several hallucinogens as being subject to control.</p><h3 id="_35-fr-12652-august-8-1970" tabindex="-1">35 FR 12652 (August 8, 1970) <a class="header-anchor" href="#_35-fr-12652-august-8-1970" aria-label="Permalink to “35 FR 12652 (August 8, 1970)”">​</a> <a class="header-anchor" href="#_35-fr-12652-august-8-1970" aria-label="Permalink to “35 FR 12652 (August 8, 1970)”">​</a></h3><p>A statement of policy concerning the human use of Amphetamine (both the Dextro- and the Levo- isomers). A finding is made that the Levamphetamine preparations (currently being sold for the treatment of obesity) are neither effective nor safe, and should be treated as new drugs.</p><h3 id="_35-fr-14789-september-23-1970" tabindex="-1">35 FR 14789 (September 23, 1970) <a class="header-anchor" href="#_35-fr-14789-september-23-1970" aria-label="Permalink to “35 FR 14789 (September 23, 1970)”">​</a> <a class="header-anchor" href="#_35-fr-14789-september-23-1970" aria-label="Permalink to “35 FR 14789 (September 23, 1970)”">​</a></h3><p>This is an involved extension of the original denial of the 行政请愿申请 requesting that Peyote be allowed as a sacrament in the Church of the Awakening. A considerable effort has been expended here to define a religion, to show how the public interests would be hurt by such an allowance, and to convince how harmful Peyote really is, etc. Of legal importance is the finding of fact that Peyote is the cactus body, and not necessarily the parts of it or the extracts of it. This has led to a more exacting definition of Peyote. Refer to 40 FR 18126 and 40 FR 18426, in which there has been added much text to the legal entry, namely, the legal fact that the term Peyote shall explicitly include all parts of the plant growing or not, its seeds, and extracts of and materials found within the plant. See 35 FR 17363 for a final comment.</p><h3 id="_35-fr-17363-november-11-1970" tabindex="-1">35 FR 17363 (November 11, 1970) <a class="header-anchor" href="#_35-fr-17363-november-11-1970" aria-label="Permalink to “35 FR 17363 (November 11, 1970)”">​</a> <a class="header-anchor" href="#_35-fr-17363-november-11-1970" aria-label="Permalink to “35 FR 17363 (November 11, 1970)”">​</a></h3><p>A final period for legal appeal is allowed in the Peyote question, see 35 FR 14789.</p><h3 id="_35-fr-17998-november-24-1970" tabindex="-1">35 FR 17998 (November 24, 1970) <a class="header-anchor" href="#_35-fr-17998-november-24-1970" aria-label="Permalink to “35 FR 17998 (November 24, 1970)”">​</a> <a class="header-anchor" href="#_35-fr-17998-november-24-1970" aria-label="Permalink to “35 FR 17998 (November 24, 1970)”">​</a></h3><p>This is an extensive findings of fact in the 行政听证会s associated with the proposal for the listing of Chlordiazepoxide and Diazepam.</p><h3 id="_36-fr-4928-march-13-1971" tabindex="-1">36 FR 4928 (March 13, 1971) <a class="header-anchor" href="#_36-fr-4928-march-13-1971" aria-label="Permalink to “36 FR 4928 (March 13, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-4928-march-13-1971" aria-label="Permalink to “36 FR 4928 (March 13, 1971)”">​</a></h3><p>Thisis a large contribution from the BNDD (pages 4928 to 4966) which is essentially rule-making. This is a proposal of what will be interpreted as law, and a request for any and all objections that might be made, to be made. This is a companion piece to 36 FR7776 where all submitted comments were spun into the final form of the published drug law as it will be enforced. 36 FR7776_ (April 24, 1971) This is the extensive conclusion (pages 7776 to 7826) of the proposed rule-making published in 36 FR 4928. The many comments and suggestions that followed the 初步拟定规则提案 have been considered and in many cases changes have been made. But there is at least one example of an administrative change that effectively introduced new drugs to the scheduled lists, the extension of the definition of the term “isomer” to include the positional and geometric forms when applied to the 致幻性 drugs. This particular is discussed in some detail under the definition of isomer, in the chapter on definitions, q.v.</p><h3 id="_36-fr-9563-may-26-1971" tabindex="-1">36 FR 9563 (May 26, 1971) <a class="header-anchor" href="#_36-fr-9563-may-26-1971" aria-label="Permalink to “36 FR 9563 (May 26, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-9563-may-26-1971" aria-label="Permalink to “36 FR 9563 (May 26, 1971)”">​</a></h3><p>This is an internal proposal that Amphetamine and Methamphetamine, with certain exceptions, be 从...移出 附表一 (Schedule I)II to 附表一 (Schedule I)I.</p><h3 id="_36-fr-11793-june-19-1971" tabindex="-1">36 FR 11793 (June 19, 1971) <a class="header-anchor" href="#_36-fr-11793-june-19-1971" aria-label="Permalink to “36 FR 11793 (June 19, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-11793-june-19-1971" aria-label="Permalink to “36 FR 11793 (June 19, 1971)”">​</a></h3><p>An Executive Order has been issued (President Nixon) establishing a Special Action Office for Drug Abuse Prevention (SAODAP). 36 FR 12734 (July7, 1971) Thisis the listing of the final announcement that Amphetamine and Methamphetamine are to be relocated from Schedule Hil to 附表一 (Schedule I)I. For the 初步拟定规则提案, see 36 FR 9563. Hearings were requested for four combination products, vis., Eskatrol, Fetamin, Biphetamine and Biphetamine-T. On August 11, 1971, John Finlator, acting director of the BNDD, sent a letter to all pharmacists listing for them the trade names of the drugs involved in this rescheduling, and reminding them of the increased security requirements. The list contains 393 trade names, and represents 204 manufacturers.</p><h3 id="_36-fr-13390-july-21-1971" tabindex="-1">36 FR 13390 (July 21, 1971) <a class="header-anchor" href="#_36-fr-13390-july-21-1971" aria-label="Permalink to “36 FR 13390 (July 21, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-13390-july-21-1971" aria-label="Permalink to “36 FR 13390 (July 21, 1971)”">​</a></h3><p>This is the publication that proposes some 64 amendments of regulation that are to be used in the enforcement of the 受控物质法案 (CSA). Comments are solicited. See 36 FR 18727 for the 最终行政裁决命令.</p><h3 id="_36-fr-13686-july-23-1971" tabindex="-1">36 FR 13686 (July 23, 1971) <a class="header-anchor" href="#_36-fr-13686-july-23-1971" aria-label="Permalink to “36 FR 13686 (July 23, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-13686-july-23-1971" aria-label="Permalink to “36 FR 13686 (July 23, 1971)”">​</a></h3><p>This is the 正式生效日期 for the placing of Biphetamine and Biphetamine-T into 附表一 (Schedule I)I, and for the rescheduling of Fetamine to 附表一 (Schedule I)I. This order deals with the registration of manufacturers, distributors, and dispensers of these materials.</p><h3 id="_36-fr-13689-july-23-1971" tabindex="-1">36 FR 13689 (July 23, 1971) <a class="header-anchor" href="#_36-fr-13689-july-23-1971" aria-label="Permalink to “36 FR 13689 (July 23, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-13689-july-23-1971" aria-label="Permalink to “36 FR 13689 (July 23, 1971)”">​</a></h3><p>The last of the amphetamine combinations, Eskatrol, was Officially proposed for transfer into 附表一 (Schedule I)I.</p><h3 id="_36-fr-15744-august-18-1971" tabindex="-1">36 FR 15744 (August 18, 1971) <a class="header-anchor" href="#_36-fr-15744-august-18-1971" aria-label="Permalink to “36 FR 15744 (August 18, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-15744-august-18-1971" aria-label="Permalink to “36 FR 15744 (August 18, 1971)”">​</a></h3><p>The transfer of Eskatrol into 附表一 (Schedule I)I is final.</p><h3 id="_36-fr-16119-august-19-1971" tabindex="-1">36 FR 16119 (August 19, 1971) <a class="header-anchor" href="#_36-fr-16119-august-19-1971" aria-label="Permalink to “36 FR 16119 (August 19, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-16119-august-19-1971" aria-label="Permalink to “36 FR 16119 (August 19, 1971)”">​</a></h3><p>A proposal is made to remove Naloxone Hydrochloride from 附表一 (Schedule I)I, where it had been assumed to have been assigned, since it is an Opium derivative. See 36 FR 19116 for 最终行政裁决命令.</p><h3 id="_36-fr-18582-september-17-1971" tabindex="-1">36 FR 18582 (September 17, 1971) <a class="header-anchor" href="#_36-fr-18582-september-17-1971" aria-label="Permalink to “36 FR 18582 (September 17, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-18582-september-17-1971" aria-label="Permalink to “36 FR 18582 (September 17, 1971)”">​</a></h3><p>This is the presentation of the proposal notice for the relocation of Methylphenidate and Phenmetrazine from 附表一 (Schedule I)II 调整转移至附表 | II. This action is being made in anticipation of an 滥用潜能 for these 中枢兴奋剂s, which might reasonably follow the unavailablility of Amphetamine and Methamphetmine (their having just been relocated from 附表一 (Schedule I)II to 附表一 (Schedule I)I.).</p><h3 id="_36-fr-18727-september-21-1971" tabindex="-1">36 FR 18727 (September 21, 1971) <a class="header-anchor" href="#_36-fr-18727-september-21-1971" aria-label="Permalink to “36 FR 18727 (September 21, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-18727-september-21-1971" aria-label="Permalink to “36 FR 18727 (September 21, 1971)”">​</a></h3><p>This is the amended body of regulations that is the response to comments received from the 初步拟定规则提案 published in 36 FR 13390.</p><h3 id="_36-fr-18749-september-21-1971" tabindex="-1">36 FR 18749 (September 21, 1971) <a class="header-anchor" href="#_36-fr-18749-september-21-1971" aria-label="Permalink to “36 FR 18749 (September 21, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-18749-september-21-1971" aria-label="Permalink to “36 FR 18749 (September 21, 1971)”">​</a></h3><p>A proposal is made to remove all heretofore exempt mixtures that contain Amphetamine or Methamphetamine from 附表一 (Schedule I)I.</p><h3 id="_36-fr-19116-september-29-1971" tabindex="-1">36 FR 19116 (September 29, 1971) <a class="header-anchor" href="#_36-fr-19116-september-29-1971" aria-label="Permalink to “36 FR 19116 (September 29, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-19116-september-29-1971" aria-label="Permalink to “36 FR 19116 (September 29, 1971)”">​</a></h3><p>This the the 最终行政裁决命令 and 正式生效日期 for the 取消管制/去列管 of Naloxone Hydrochloride. See 36 FR 16119 for the 初步拟定规则提案. See 39 FR 44392 for the removal of the free base from 附表一 (Schedule I)I.</p><h3 id="_36-fr-20686-october-28-1971" tabindex="-1">36 FR 20686 (October 28, 1971) <a class="header-anchor" href="#_36-fr-20686-october-28-1971" aria-label="Permalink to “36 FR 20686 (October 28, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-20686-october-28-1971" aria-label="Permalink to “36 FR 20686 (October 28, 1971)”">​</a></h3><p>This is the final notice and 正式生效日期 for the relocation of Methylphenidate and of Phenmetrazine into 附表一 (Schedule I)I from 附表一 (Schedule I)II. See 36 FR 18582 for the 初步拟定规则提案. See 36 FR 22135 for minor corrections.</p><h3 id="_36-fr-21336-november-6-1971" tabindex="-1">36 FR 21336 (November 6, 1971) <a class="header-anchor" href="#_36-fr-21336-november-6-1971" aria-label="Permalink to “36 FR 21336 (November 6, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-21336-november-6-1971" aria-label="Permalink to “36 FR 21336 (November 6, 1971)”">​</a></h3><p>This is the final decision for the removal of mixtures containing Amphetamine and Methamphetamine from exemption to 附表一 (Schedule I)I listing. See 36 FR 17849 for the 初步拟定规则提案. See 36 FR 22153 for minor corrections, and 36 FR 22830 for additional deletions.</p><h3 id="_36-fr-21527-november-10-1971" tabindex="-1">36 FR 21527 (November 10, 1971) <a class="header-anchor" href="#_36-fr-21527-november-10-1971" aria-label="Permalink to “36 FR 21527 (November 10, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-21527-november-10-1971" aria-label="Permalink to “36 FR 21527 (November 10, 1971)”">​</a></h3><p>The notice of the receipt of a 行政请愿申请 for the transfer to 附表一 (Schedule I)II (from 附表一 (Schedule I)V) the drug Pentazocine when in a solution form suitable for injection. There appears to have been no further action on this request.</p><h3 id="_36-fr-22135-november-20-1971" tabindex="-1">36 FR 22135 (November 20, 1971) <a class="header-anchor" href="#_36-fr-22135-november-20-1971" aria-label="Permalink to “36 FR 22135 (November 20, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-22135-november-20-1971" aria-label="Permalink to “36 FR 22135 (November 20, 1971)”">​</a></h3><p>Several minor typographical corrections and regulatory additions to 36 FR 20686 and 36 FR 21336.</p><h3 id="_36-fr-22830-december-1-1971" tabindex="-1">36 FR 22830 (December 1, 1971) <a class="header-anchor" href="#_36-fr-22830-december-1-1971" aria-label="Permalink to “36 FR 22830 (December 1, 1971)”">​</a> <a class="header-anchor" href="#_36-fr-22830-december-1-1971" aria-label="Permalink to “36 FR 22830 (December 1, 1971)”">​</a></h3><p>A listing of additional deletions from exemption as a consequence of 36 FR 21336.</p><h3 id="_37-fr-1468-january-29-1972" tabindex="-1">37 FR 1468 (January 29, 1972) <a class="header-anchor" href="#_37-fr-1468-january-29-1972" aria-label="Permalink to “37 FR 1468 (January 29, 1972)”">​</a> <a class="header-anchor" href="#_37-fr-1468-january-29-1972" aria-label="Permalink to “37 FR 1468 (January 29, 1972)”">​</a></h3><p>The announcement for the placement of Propiram into 附表一 (Schedule I). The Commission on Narcotic Drugs of the United Nations recommended that this drug be 正式列入 Schedule!I, and as there was no accepted 医疗用途 for it currently in the United States, the 司法部长 deemed that 附表一 (Schedule I) was an appropriate Schedule for domestic control.</p><h3 id="_37-fr-2421-february-1-1972" tabindex="-1">37 FR 2421 (February 1, 1972) <a class="header-anchor" href="#_37-fr-2421-february-1-1972" aria-label="Permalink to “37 FR 2421 (February 1, 1972)”">​</a> <a class="header-anchor" href="#_37-fr-2421-february-1-1972" aria-label="Permalink to “37 FR 2421 (February 1, 1972)”">​</a></h3><p>An executive order (President Nixon) creating the Office for Drug Abuse Law Enforcement (ODALE). See 37 FR 3180 for its having being put into effect. 37 FR 3180 entry, 37 FR 2421. (February 12, 1972) See</p><h3 id="_37-fr9500-may-11-1972" tabindex="-1">37 FR9500 (May 11, 1972) <a class="header-anchor" href="#_37-fr9500-may-11-1972" aria-label="Permalink to “37 FR9500 (May 11, 1972)”">​</a> <a class="header-anchor" href="#_37-fr9500-may-11-1972" aria-label="Permalink to “37 FR9500 (May 11, 1972)”">​</a></h3><p>A 行政请愿申请 is considered requesting the transfer of Amobarbital, Secobarbital, Pentobarbital and Glutethimide (currently 附表一 (Schedule I)II drugs) to 附表一 (Schedule I)I and for the inclusion of Methaqualone (at this time unscheduled) into 附表一 (Schedule I)I. The three barbiturate derivatives were properly included with six others for reassignment from 附表一 (Schedule I)II to II (see 38 FR 14288). The Methaqualone scheduling was offered for comment in 38 FR 9170.</p><h3 id="_37-fr-13352-july-7-1972" tabindex="-1">37 FR 13352 (July 7, 1972) <a class="header-anchor" href="#_37-fr-13352-july-7-1972" aria-label="Permalink to “37 FR 13352 (July 7, 1972)”">​</a> <a class="header-anchor" href="#_37-fr-13352-july-7-1972" aria-label="Permalink to “37 FR 13352 (July 7, 1972)”">​</a></h3><p>A行政请愿申请 was accepted from the Hexagon Laboratories (a primary producer) for the 取消管制/去列管 of the levo-isomer of Methamphetamine. A second 行政请愿申请 was received from Richardson-Merrell (a primary user of the drug) for 取消管制/去列管 of the same drug. See 38 FR 9036 for the withdrawal of this 行政请愿申请.</p><h3 id="_37-fr-13486-july-8-1972" tabindex="-1">37 FR 13486 (July 8, 1972) <a class="header-anchor" href="#_37-fr-13486-july-8-1972" aria-label="Permalink to “37 FR 13486 (July 8, 1972)”">​</a> <a class="header-anchor" href="#_37-fr-13486-july-8-1972" aria-label="Permalink to “37 FR 13486 (July 8, 1972)”">​</a></h3><p>Thisisa frivolous 行政请愿申请 submitted requesting the inclusion of Tobacco under the Drug Abuse Prevention and Control Act. It was 被依法驳回 for several incontestable reasons. 37 FR 9545 == (May 12, 1972) This isa semi-annually required publication of the Schedules of the Controlled Substances.</p><h3 id="_37-fr-18097-september-7-1972" tabindex="-1">37 FR 18097 (September 7, 1972) <a class="header-anchor" href="#_37-fr-18097-september-7-1972" aria-label="Permalink to “37 FR 18097 (September 7, 1972)”">​</a> <a class="header-anchor" href="#_37-fr-18097-september-7-1972" aria-label="Permalink to “37 FR 18097 (September 7, 1972)”">​</a></h3><p>This is a 行政请愿申请 to either remove Marihuana from the Scheduled Substances List, or to transfer it from 附表一 (Schedule I) to 附表五 (Schedule V). It was declined, with much responsibility being placed on the Single Convention on Narcotic Drugs of 1961.</p><h3 id="_37-fr-18525-september-13-1972" tabindex="-1">37 FR 18525 (September 13, 1972) <a class="header-anchor" href="#_37-fr-18525-september-13-1972" aria-label="Permalink to “37 FR 18525 (September 13, 1972)”">​</a> <a class="header-anchor" href="#_37-fr-18525-september-13-1972" aria-label="Permalink to “37 FR 18525 (September 13, 1972)”">​</a></h3><p>This is a statement of policy and interpretation of the BNDD concerning the investigational use of THC (from Marihuana) in research.</p><h3 id="_38-fr-953-january-8-1973" tabindex="-1">38 FR 953 (January 8, 1973) <a class="header-anchor" href="#_38-fr-953-january-8-1973" aria-label="Permalink to “38 FR 953 (January 8, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-953-january-8-1973" aria-label="Permalink to “38 FR 953 (January 8, 1973)”">​</a></h3><p>The semi-annual republishing of the schedules of controlled substances. Certain portions were not published, and to disarm comments that the excluded portions had been repealed, they have been published separately, at 38 FR8254.</p><h3 id="_38-fr-8254-march-30-1973" tabindex="-1">38 FR 8254 (March 30, 1973) <a class="header-anchor" href="#_38-fr-8254-march-30-1973" aria-label="Permalink to “38 FR 8254 (March 30, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-8254-march-30-1973" aria-label="Permalink to “38 FR 8254 (March 30, 1973)”">​</a></h3><p>There is presented here the complete listing of the schedules of controlled substances which had appeared only in part at 38 FR 953.</p><h3 id="_38-fr-9036-april-9-1973" tabindex="-1">38 FR 9036 (April 9, 1973) <a class="header-anchor" href="#_38-fr-9036-april-9-1973" aria-label="Permalink to “38 FR 9036 (April 9, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-9036-april-9-1973" aria-label="Permalink to “38 FR 9036 (April 9, 1973)”">​</a></h3><p>A 行政请愿申请, which had been filed requesting the withdrawal of the levo-isomer of Methamphetamine from 附表一 (Schedule I)I, has been withdrawn by the original 行政请愿申请er (Hexagon Laboratories). See July 7 FR 1972 for 行政请愿申请. 38 FR9170_ (April 11, 1973) This is the 初步拟定规则提案 for the placement of Methaqualone into 附表一 (Schedule I)I as a 中枢抑制剂. See 38 FR 10010 for a typographical correction to this proposal. See 38 FR 27516 for 最终行政裁决命令 on this proposal, and 49 FR 33870 for the Congressional action that forced its reclassification as a 附表一 (Schedule I) substance.</p><h3 id="_38-fr-10010-april-23-1973" tabindex="-1">38 FR 10010 (April 23, 1973) <a class="header-anchor" href="#_38-fr-10010-april-23-1973" aria-label="Permalink to “38 FR 10010 (April 23, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-10010-april-23-1973" aria-label="Permalink to “38 FR 10010 (April 23, 1973)”">​</a></h3><p>Thisisa typographical correction to the proposal for scheduling of Methaqualone presented in 38 FR 9170.</p><h3 id="_38-fr-11473-may-8-1973" tabindex="-1">38 FR 11473 (May 8, 1973) <a class="header-anchor" href="#_38-fr-11473-may-8-1973" aria-label="Permalink to “38 FR 11473 (May 8, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-11473-may-8-1973" aria-label="Permalink to “38 FR 11473 (May 8, 1973)”">​</a></h3><p>This isa 行政请愿申请 (from A. H. Robins, Co.) to reschedule Pholcodine from 附表一 (Schedule I) to 附表一 (Schedule I)J, III or V. It has been taken under advisement for review and evaluation.</p><h3 id="_38-fr-12119-may-9-1973" tabindex="-1">38 FR 12119 (May 9, 1973) <a class="header-anchor" href="#_38-fr-12119-may-9-1973" aria-label="Permalink to “38 FR 12119 (May 9, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-12119-may-9-1973" aria-label="Permalink to “38 FR 12119 (May 9, 1973)”">​</a></h3><p>This isa several page proposal for the scheduling of seven anorexics, Benzphetamine, Chlorphentermine, Chlortermine, Fenfluramine, Mazindol, Phendimetrazine, and Phentermine into Scheduies III or IV. Benzphetamine, Chlorphentermine, Clortermine, Mazindol, Phendimetrazine and Phentermine were proposed for 附表一 (Schedule I)II; Fenfluramine was recommended for placement in 附表一 (Schedule I)V. See 38 FR 13288 for an extension of time, and 38 FR 15719 and 38 FR 18013 for 最终行政裁决命令.</p><h3 id="_38-fr-12230-may-10-1973" tabindex="-1">38 FR 12230 (May 10, 1973) <a class="header-anchor" href="#_38-fr-12230-may-10-1973" aria-label="Permalink to “38 FR 12230 (May 10, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-12230-may-10-1973" aria-label="Permalink to “38 FR 12230 (May 10, 1973)”">​</a></h3><p>This isan announcement that proposes the placement of Diethylpropion into 附表一 (Schedule I)II. See 38 FR 14288 for an extension of time, 38 FR 15719 for arguments for a less severe scheduling, and 38 FR 10813 for its eventual placement into 附表一 (Schedule I)V.</p><h3 id="_38-fr-14288-may-31-1973" tabindex="-1">38 FR 14288 (May 31, 1973) <a class="header-anchor" href="#_38-fr-14288-may-31-1973" aria-label="Permalink to “38 FR 14288 (May 31, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-14288-may-31-1973" aria-label="Permalink to “38 FR 14288 (May 31, 1973)”">​</a></h3><p>An exten-sion of time is requested for consideration of the scheduling of seven anorexic drugs, proposed in 38 FR 12119 and 38 FR 12230. In this same entry there is the announcement of the proposal for the placement of 2,5-Dimethoxyamphetamine (2,5-DMA) into 附表一 (Schedule I). See 38 FR 26447 for 最终行政裁决命令. In this same entry there is the proposal for the transfer of nine derivatives of Barbituric Acid from 附表一 (Schedule I)II to 附表一 (Schedule I)I. These are Amobarbital, Butabarbital, Cyclobarbital, Heptabarbital, Pentobarbital, Probarbital, Secobarbital, Talbutal and Vinbarbital. See 38 FR 17733 for a typographical correction and for an extension of time for comment. See 38 FR 31310 for the final disposition of these drugs.</p><h3 id="_38-fr-15050-june-8-1973" tabindex="-1">38 FR 15050 (June 8, 1973) <a class="header-anchor" href="#_38-fr-15050-june-8-1973" aria-label="Permalink to “38 FR 15050 (June 8, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-15050-june-8-1973" aria-label="Permalink to “38 FR 15050 (June 8, 1973)”">​</a></h3><p>This is the FDA approval of the use of Etorphine Hydrochloride as an immobilization agent in the control of wild animals, and of Diprenorphine as an antagonist to Etorphine Hydrochloride. See 39 FR 11554 for the discussion of these drugs in the DEA regulation structure.</p><h3 id="_38-fr-15719-june-15-1973" tabindex="-1">38 FR 15719 (June 15, 1973) <a class="header-anchor" href="#_38-fr-15719-june-15-1973" aria-label="Permalink to “38 FR 15719 (June 15, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-15719-june-15-1973" aria-label="Permalink to “38 FR 15719 (June 15, 1973)”">​</a></h3><p>The announcement of the conclusions of the requests for comments concerning the proposed scheduling of several anorexic drugs. Benzphetamine, Chlorphentermine, Clortermine, Mazindol and Phendimetrazine (all proposed in 38 FR 12119) are placed in 附表一 (Schedule I)II. Fenfluramine (see 38 FR 12119) is placed in 附表一 (Schedule I)V. Phentermine (also from 38 FR 12119) and Diethylpropion (see 38 FR 12230) are not acted upon at this time. For these latter two, see 38 FR 18013.</p><h3 id="_38-fr-15932-june-19-1973" tabindex="-1">38 FR 15932 (June 19, 1973) <a class="header-anchor" href="#_38-fr-15932-june-19-1973" aria-label="Permalink to “38 FR 15932 (June 19, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-15932-june-19-1973" aria-label="Permalink to “38 FR 15932 (June 19, 1973)”">​</a></h3><p>The Presidential reorganization plan is presented, that abolishes the 麻醉品与危险药物管理局 (BNDD) (BNDD) and establishes the 美国缉毒局 (DEA) (DEA). The Presidential order is reported in 38 FR 18357.</p><h3 id="_38-fr-17499-july-2-1973" tabindex="-1">38 FR 17499 (July 2, 1973) <a class="header-anchor" href="#_38-fr-17499-july-2-1973" aria-label="Permalink to “38 FR 17499 (July 2, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-17499-july-2-1973" aria-label="Permalink to “38 FR 17499 (July 2, 1973)”">​</a></h3><p>A proposal is made for the placement of 4-Bromo2,5-dimethoxyamphetamine into 附表一 (Schedule I). In the same citation, the placement of 4Methoxyamphetamine into 附表一 (Schedule I) is also proposed. See 38 FR 26447 for 最终行政裁决命令 on both compounds.</p><h3 id="_38-fr17717-july-3-1973" tabindex="-1">38 FR17717 (July 3, 1973) <a class="header-anchor" href="#_38-fr17717-july-3-1973" aria-label="Permalink to “38 FR17717 (July 3, 1973)”">​</a> <a class="header-anchor" href="#_38-fr17717-july-3-1973" aria-label="Permalink to “38 FR17717 (July 3, 1973)”">​</a></h3><p>This report authorizes the listing of Drotebanol as a 附表一 (Schedule I) drug as of 8/6/73. The Commission on Narcotic Drugs of the UN recommended that this drug be 正式列入 ScheduleI, and as there was no accepted 医疗用途 for it currently in the United States, the 司法部长 deemed that 附表一 (Schedule I) was an appropriate schedule for domestic control.</p><h3 id="_38-fr-17733-july-3-1973" tabindex="-1">38 FR 17733 (July 3, 1973) <a class="header-anchor" href="#_38-fr-17733-july-3-1973" aria-label="Permalink to “38 FR 17733 (July 3, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-17733-july-3-1973" aria-label="Permalink to “38 FR 17733 (July 3, 1973)”">​</a></h3><p>An extension of time is 获得正式批准 for the receipt of comments regarding the proposed transfer of nine Barbituric Acid derivatives from 附表一 (Schedule I)II to 附表一 (Schedule I)I (see 38 FR 14288). For a second delay, see 38 FR 18469.</p><h3 id="_38-fr-18013-july-6-1973" tabindex="-1">38 FR 18013 (July 6, 1973) <a class="header-anchor" href="#_38-fr-18013-july-6-1973" aria-label="Permalink to “38 FR 18013 (July 6, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-18013-july-6-1973" aria-label="Permalink to “38 FR 18013 (July 6, 1973)”">​</a></h3><p>This is the announcement of the placing of Diethylpropion and of Phentermine into 附表一 (Schedule I)V. This placement is a temporary one, pending the outcome of 行政听证会s that have been agreed upon. See 38 FR 12230 and 38 FR 12119, resp., for the 初步拟定规则提案s that these two drugs be placed in 附表一 (Schedule I)II, and see 38 FR 15719 for the arguments put forward for a less severe scheduling category.</p><h3 id="_38-fr-18357-july-10-1973" tabindex="-1">38 FR 18357 (July 10, 1973) <a class="header-anchor" href="#_38-fr-18357-july-10-1973" aria-label="Permalink to “38 FR 18357 (July 10, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-18357-july-10-1973" aria-label="Permalink to “38 FR 18357 (July 10, 1973)”">​</a></h3><p>The Presidential Executive Order (President Nixon) confirming the formation of the DEA. See 38 FR 15932 for additional detail.</p><h3 id="_38-fr-18469-july-11-1973" tabindex="-1">38 FR 18469 (July 11, 1973) <a class="header-anchor" href="#_38-fr-18469-july-11-1973" aria-label="Permalink to “38 FR 18469 (July 11, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-18469-july-11-1973" aria-label="Permalink to “38 FR 18469 (July 11, 1973)”">​</a></h3><p>Asecond delay on the scheduling proposals for the nine Barbituric Acid derivatives. See 38 FR 17733 for earlier delays. See 38 FR 31310 for 最终行政裁决命令.</p><h3 id="_38-fr-26447-september-21-1973" tabindex="-1">38 FR 26447 (September 21, 1973) <a class="header-anchor" href="#_38-fr-26447-september-21-1973" aria-label="Permalink to “38 FR 26447 (September 21, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-26447-september-21-1973" aria-label="Permalink to “38 FR 26447 (September 21, 1973)”">​</a></h3><p>An announcement of the placing of 2,5-Dimethoxyamphetamine, 4-Bromo-2,5-dimethoxyamphetamine, and 4-Methoxyamphetamine in 附表一 (Schedule I). See 38 FR 14288 for the 初步拟定规则提案 for 2,5-Dimethoxyamphetamine, and 38 FR 17499 for the 初步拟定规则提案 for the other two drugs.</p><h3 id="_38-fr-27516-october-4-1973" tabindex="-1">38 FR 27516 (October 4, 1973) <a class="header-anchor" href="#_38-fr-27516-october-4-1973" aria-label="Permalink to “38 FR 27516 (October 4, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-27516-october-4-1973" aria-label="Permalink to “38 FR 27516 (October 4, 1973)”">​</a></h3><p>An announcement of the placement of Methaqualone into 附表一 (Schedule I)I. See 38 FR9170 for the original proposal, and 49 FR 33870 for the eventual placement of this drug in调整转移至附表 E</p><h3 id="_38-fr-31310-november-13-1973" tabindex="-1">38 FR 31310 (November 13, 1973) <a class="header-anchor" href="#_38-fr-31310-november-13-1973" aria-label="Permalink to “38 FR 31310 (November 13, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-31310-november-13-1973" aria-label="Permalink to “38 FR 31310 (November 13, 1973)”">​</a></h3><p>An announcement is published that proposes the relocation of Amobarbital, Pentobarbital, and Secobarbital from 附表一 (Schedule I)II to 附表一 (Schedule I)I. If they are admixed with other active ingredients which are themselves not scheduled, they remain in 附表一 (Schedule I)II. The remaining six named Barbituric Acid derivatives (see 38 FR 14288 for names and assigned Code numbers) presumably remain in 附表一 (Schedule I)II. However, a derivative of Barbituric Acid, to be included in 附表一 (Schedule I)II, must have a 中枢抑制剂 effect on the central nervous system , and a 中枢抑制剂 effect has been defined as an effect produced by a habit-forming drug. Seventeen examples are given, and chemical derivatives of these are included IF they in turn have been shown to be habit-forming. The six Barbituric Acid derivatives, vis., Butabarbital, Cyclobarbital, Heptabarbital, Probarbital, Talbutal, and Vinbarbital, are not mentioned in the Federal Code under drugs with 中枢抑制剂 effects. This seems to be a grey area, legally. Minor typographical corrections to this report have been made (see 38 FR32257 and 38 FR 32575).</p><h3 id="_38-fr-32257-november-23-1973" tabindex="-1">38 FR 32257 (November 23, 1973) <a class="header-anchor" href="#_38-fr-32257-november-23-1973" aria-label="Permalink to “38 FR 32257 (November 23, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-32257-november-23-1973" aria-label="Permalink to “38 FR 32257 (November 23, 1973)”">​</a></h3><p>Typographical corrections to 38 FR 31310.</p><h3 id="_38-fr-32262-november-23-1973" tabindex="-1">38 FR 32262 (November 23, 1973) <a class="header-anchor" href="#_38-fr-32262-november-23-1973" aria-label="Permalink to “38 FR 32262 (November 23, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-32262-november-23-1973" aria-label="Permalink to “38 FR 32262 (November 23, 1973)”">​</a></h3><p>An announcement concerning the rescheduling of Etorphine Hydrochloride into 附表一 (Schedule I)I while leaving Etorphine in 附表一 (Schedule I). See 39 FR 11535 for 最终行政裁决命令.</p><h3 id="_38-fr-32575-november-27-1973" tabindex="-1">38 FR 32575 (November 27, 1973) <a class="header-anchor" href="#_38-fr-32575-november-27-1973" aria-label="Permalink to “38 FR 32575 (November 27, 1973)”">​</a> <a class="header-anchor" href="#_38-fr-32575-november-27-1973" aria-label="Permalink to “38 FR 32575 (November 27, 1973)”">​</a></h3><p>Typographical corrections to 38 FR 31310. 39 FR 7800 _ = (February 28, 1974) The 初步拟定规则提案 to waive order form requirements for laboratories conducting anonymous analyses of drug samples. See 39 FR 15031 for 最终行政裁决命令.</p><h3 id="_39-fr11535-march-29-1974" tabindex="-1">39 FR11535 (March 29, 1974) <a class="header-anchor" href="#_39-fr11535-march-29-1974" aria-label="Permalink to “39 FR11535 (March 29, 1974)”">​</a> <a class="header-anchor" href="#_39-fr11535-march-29-1974" aria-label="Permalink to “39 FR11535 (March 29, 1974)”">​</a></h3><p>An announcement that Etorphine Hydrochloride has been rescheduled as a 附表一 (Schedule I)I controlled Substance, to be effective April 19, 1974. Also, Drotebanol (see 38 FR 17717) has been entered into the 附表一 (Schedule I) listings. See 39 FR 17832 for 最终行政裁决命令 on Diprenorphine.</p><h3 id="_39-fr-11554-march-29-1974" tabindex="-1">39 FR 11554 (March 29, 1974) <a class="header-anchor" href="#_39-fr-11554-march-29-1974" aria-label="Permalink to “39 FR 11554 (March 29, 1974)”">​</a> <a class="header-anchor" href="#_39-fr-11554-march-29-1974" aria-label="Permalink to “39 FR 11554 (March 29, 1974)”">​</a></h3><p>Thisis a codification of procedures and amendments that bear upon the regulations concerning Etorphine Hydrochloride and Diprenorphine control. This entry was alluded to in 39 FR 11535, wherein Etorphine Hydrochloride was entered into 附表一 (Schedule I)I. This is the only mention of Diprenorphine, and as it is an Opium derivative (it is made from Thebaine) it is in 附表一 (Schedule I)I. See 38 FR 15050 for the FDA approval of this substance as an antagonist to Etorphine Hydrochloride. See 39 FR 17832 for received comments and 最终行政裁决命令.</p><h3 id="_39-fr-15031-april-30-1974" tabindex="-1">39 FR 15031 (April 30, 1974) <a class="header-anchor" href="#_39-fr-15031-april-30-1974" aria-label="Permalink to “39 FR 15031 (April 30, 1974)”">​</a> <a class="header-anchor" href="#_39-fr-15031-april-30-1974" aria-label="Permalink to “39 FR 15031 (April 30, 1974)”">​</a></h3><p>Final action exempting laboratories conducting analyses of anonymous drug samples from having to abide by the official form regulations. See 39 FR 7800 for the 初步拟定规则提案.</p><h3 id="_39-fr-17832-may-21-1974" tabindex="-1">39 FR 17832 (May 21, 1974) <a class="header-anchor" href="#_39-fr-17832-may-21-1974" aria-label="Permalink to “39 FR 17832 (May 21, 1974)”">​</a> <a class="header-anchor" href="#_39-fr-17832-may-21-1974" aria-label="Permalink to “39 FR 17832 (May 21, 1974)”">​</a></h3><p>Final action on the placement of Etorphine Hydrochloride and Diprenorphine into 附表一 (Schedule I)I. There are many changes in registration, recording, reporting, and ordering procedures, as these materials may be obtained only by veterinarians associated with zoos and exotic animal manipulation. There is no explicit statement of a new law wording (with code numbers) and Diprenorphine has not been subsequently listed as a 附表一 (Schedule I)I drug in the Code of Federal Regulations. See 39 FR 11535 and 11554 for earlier comments and for the explicit listing of Etorphine Hydrochloride.</p><h3 id="_39-fr-22140-june-20-1974" tabindex="-1">39 FR 22140 (June 20, 1974) <a class="header-anchor" href="#_39-fr-22140-june-20-1974" aria-label="Permalink to “39 FR 22140 (June 20, 1974)”">​</a> <a class="header-anchor" href="#_39-fr-22140-june-20-1974" aria-label="Permalink to “39 FR 22140 (June 20, 1974)”">​</a></h3><p>This is the annual schedule listing for 1974. There is also a change in form made in the Scheduie III presentation of numbering codes for Amobarbital, Secobarbital and Pentobarbital when compounded in admixture with other active ingredients. Effective June 20, 1974.</p><h3 id="_39-fr-25327-july-10-1974" tabindex="-1">39 FR 25327 (July 10, 1974) <a class="header-anchor" href="#_39-fr-25327-july-10-1974" aria-label="Permalink to “39 FR 25327 (July 10, 1974)”">​</a> <a class="header-anchor" href="#_39-fr-25327-july-10-1974" aria-label="Permalink to “39 FR 25327 (July 10, 1974)”">​</a></h3><p>This is the 初步拟定规则提案 that Naloxone should be decontrolled. For 最终行政裁决命令, see 39 FR 44392.</p><h3 id="_39-fr-26424-july-19-1974" tabindex="-1">39 FR 26424 (July 19, 1974) <a class="header-anchor" href="#_39-fr-26424-july-19-1974" aria-label="Permalink to “39 FR 26424 (July 19, 1974)”">​</a> <a class="header-anchor" href="#_39-fr-26424-july-19-1974" aria-label="Permalink to “39 FR 26424 (July 19, 1974)”">​</a></h3><p>A request for comments concerning proposed regulatory controls associated with the Narcotic Addict Treatment Act of 1974. The purpose of the law was to provide for maintenance and detoxification programs for 麻醉药品 addicts. See 39 FR 37983 for comments received and 最终行政裁决命令.</p><h3 id="_39-fr-37983-october-25-1974" tabindex="-1">39 FR 37983 (October 25, 1974) <a class="header-anchor" href="#_39-fr-37983-october-25-1974" aria-label="Permalink to “39 FR 37983 (October 25, 1974)”">​</a> <a class="header-anchor" href="#_39-fr-37983-october-25-1974" aria-label="Permalink to “39 FR 37983 (October 25, 1974)”">​</a></h3><p>Final action following comments received on the proposal of regulatory changes associated with the Narcotic Addict Treatment Act of 1974. See 39 FR 26424 for the 初步拟定规则提案.</p><h3 id="_39-fr-39451-november-7-1974" tabindex="-1">39 FR 39451 (November 7, 1974) <a class="header-anchor" href="#_39-fr-39451-november-7-1974" aria-label="Permalink to “39 FR 39451 (November 7, 1974)”">​</a> <a class="header-anchor" href="#_39-fr-39451-november-7-1974" aria-label="Permalink to “39 FR 39451 (November 7, 1974)”">​</a></h3><p>This is the 初步拟定规则提案 that Pemoline should be placed in 附表一 (Schedule I)V as a中枢兴奋剂. See39FR 43228 for an extension of time allowed for comments, and 40 FR 4150 for 最终行政裁决命令.</p><h3 id="_39-fr-42918-december-9-1974" tabindex="-1">39 FR 42918 (December 9, 1974) <a class="header-anchor" href="#_39-fr-42918-december-9-1974" aria-label="Permalink to “39 FR 42918 (December 9, 1974)”">​</a> <a class="header-anchor" href="#_39-fr-42918-december-9-1974" aria-label="Permalink to “39 FR 42918 (December 9, 1974)”">​</a></h3><p>It is proposed that Naltrexone, which has currently accepted 医疗用途 and insufficient 滥用潜能 for scheduling, should be removed from 附表一 (Schedule I)I where it was located as an Opium derivative. See 40 FR 10455 for a correction to the 医疗用途 statement, and for 最终行政裁决命令.</p><h3 id="_39-fr-43228-december-11-1974" tabindex="-1">39 FR 43228 (December 11, 1974) <a class="header-anchor" href="#_39-fr-43228-december-11-1974" aria-label="Permalink to “39 FR 43228 (December 11, 1974)”">​</a> <a class="header-anchor" href="#_39-fr-43228-december-11-1974" aria-label="Permalink to “39 FR 43228 (December 11, 1974)”">​</a></h3><p>This is an extension of the proposal for the placement of Pemoline into 附表一 (Schedule I)V. See 39 FR 39451 for the 初步拟定规则提案.</p><h3 id="_39-fr-43408-december-13-1974" tabindex="-1">39 FR 43408 (December 13, 1974) <a class="header-anchor" href="#_39-fr-43408-december-13-1974" aria-label="Permalink to “39 FR 43408 (December 13, 1974)”">​</a> <a class="header-anchor" href="#_39-fr-43408-december-13-1974" aria-label="Permalink to “39 FR 43408 (December 13, 1974)”">​</a></h3><p>This is a proposal for the placement of Mebutamate into 附表一 (Schedule I)V as a 中枢抑制剂. See 40 FR 4418 for 最终行政裁决命令.</p><h3 id="_39-fr-44033-december-20-1974" tabindex="-1">39 FR 44033 (December 20, 1974. <a class="header-anchor" href="#_39-fr-44033-december-20-1974" aria-label="Permalink to “39 FR 44033 (December 20, 1974.”">​</a> <a class="header-anchor" href="#_39-fr-44033-december-20-1974" aria-label="Permalink to “39 FR 44033 (December 20, 1974.”">​</a></h3><p>This is the initial proposal that the Concentrate of Poppy Straw should be placed in Schedule II of the Controlled Substances. Act. See corrected date, 40 FR 787. See 40 FR6779 forfinal . action. 39 FR 44392 (Dec. 24, 1974)</p><p>The announcement that Naloxone and its salts have been decontrolled, effective this date. Note that the hydrochloride had been decontrolled 9/29/ 71. The initial notice of this action appeared in 39 FR 25327.</p><h2 id="_1975-—-1979-年-苯二氮䓬类全网罗与联合国公约国内落地" tabindex="-1">1975 — 1979 年：苯二氮䓬类全网罗与联合国公约国内落地 <a class="header-anchor" href="#_1975-—-1979-年-苯二氮䓬类全网罗与联合国公约国内落地" aria-label="Permalink to “1975 — 1979 年：苯二氮䓬类全网罗与联合国公约国内落地”">​</a> <a class="header-anchor" href="#_1975-—-1979-年-苯二氮䓬类全网罗与联合国公约国内落地" aria-label="Permalink to “1975 — 1979 年：苯二氮䓬类全网罗与联合国公约国内落地”">​</a></h2><h3 id="_40-fr-787-january-3-1975" tabindex="-1">40 FR 787 (January 3, 1975) <a class="header-anchor" href="#_40-fr-787-january-3-1975" aria-label="Permalink to “40 FR 787 (January 3, 1975)”">​</a> <a class="header-anchor" href="#_40-fr-787-january-3-1975" aria-label="Permalink to “40 FR 787 (January 3, 1975)”">​</a></h3><p>Correction to 39 FR 44033.</p><h3 id="_40-fr4016-january-27-1975" tabindex="-1">40 FR4016 (January 27, 1975) <a class="header-anchor" href="#_40-fr4016-january-27-1975" aria-label="Permalink to “40 FR4016 (January 27, 1975)”">​</a> <a class="header-anchor" href="#_40-fr4016-january-27-1975" aria-label="Permalink to “40 FR4016 (January 27, 1975)”">​</a></h3><p>This is a proposal to place six benzodiazepines into 附表一 (Schedule I)V. These are Chlordiazepoxide, Diazepam, Oxazepam, Chlorazepate, Fluorazepam, and Clonazepam. See 40 FR 23998 for the 最终行政裁决命令 on this proposal. See 40 FR 8108 for corrections to this text.</p><h3 id="_40fr4150-january-28-1975" tabindex="-1">40FR4150 (January 28, 1975) <a class="header-anchor" href="#_40fr4150-january-28-1975" aria-label="Permalink to “40FR4150 (January 28, 1975)”">​</a> <a class="header-anchor" href="#_40fr4150-january-28-1975" aria-label="Permalink to “40FR4150 (January 28, 1975)”">​</a></h3><p>The final announcement of the placement of Pemoline into 附表一 (Schedule I)V. See 39 FR 39451 for the 初步拟定规则提案.</p><h3 id="_40-fr4418-january-30-1975" tabindex="-1">40 FR4418 (January 30, 1975) <a class="header-anchor" href="#_40-fr4418-january-30-1975" aria-label="Permalink to “40 FR4418 (January 30, 1975)”">​</a> <a class="header-anchor" href="#_40-fr4418-january-30-1975" aria-label="Permalink to “40 FR4418 (January 30, 1975)”">​</a></h3><p>This is the final announcement of the placement of Mebutamate into 附表一 (Schedule I)V. See 39 FR 43408 for the 初步拟定规则提案.</p><h3 id="_40-fr6779-february-14-1975" tabindex="-1">40 FR6779 (February 14, 1975) <a class="header-anchor" href="#_40-fr6779-february-14-1975" aria-label="Permalink to “40 FR6779 (February 14, 1975)”">​</a> <a class="header-anchor" href="#_40-fr6779-february-14-1975" aria-label="Permalink to “40 FR6779 (February 14, 1975)”">​</a></h3><p>An announcement of the effective scheduling of the Concentrate of Poppy Straw as a 附表一 (Schedule I)I substance.</p><h3 id="_40-fr8108-february-25-1975" tabindex="-1">40 FR8108 (February 25, 1975) <a class="header-anchor" href="#_40-fr8108-february-25-1975" aria-label="Permalink to “40 FR8108 (February 25, 1975)”">​</a> <a class="header-anchor" href="#_40-fr8108-february-25-1975" aria-label="Permalink to “40 FR8108 (February 25, 1975)”">​</a></h3><p>A correction supplying text omitted from the original proposal (40 FR 4016) for the placement of six benzodiazepins into 附表一 (Schedule I)V.</p><h3 id="_40-fr-10455-march-6-1975" tabindex="-1">40 FR 10455 (March 6, 1975) <a class="header-anchor" href="#_40-fr-10455-march-6-1975" aria-label="Permalink to “40 FR 10455 (March 6, 1975)”">​</a> <a class="header-anchor" href="#_40-fr-10455-march-6-1975" aria-label="Permalink to “40 FR 10455 (March 6, 1975)”">​</a></h3><p>This announcement is the 最终行政裁决命令 for the decontrolling of Naltrexone and its salts from 附表一 (Schedule I)I. At the time of the 初步拟定规则提案, it was stated that Naltrexone had currently accepted 医疗用途, but thai statement is here stated to have been “inadvertent.” But even without any currently accepted 医疗用途, the absence of 滥用潜能 is sufficient to effectively deschedule this Opium derivative. Endo Laboratories is currently investigating its use as a 麻醉药品 antagonist (under the name EN1639A).</p><h3 id="_40-fr-18426-april-28-1975" tabindex="-1">40 FR 18426 (April 28, 1975) <a class="header-anchor" href="#_40-fr-18426-april-28-1975" aria-label="Permalink to “40 FR 18426 (April 28, 1975)”">​</a> <a class="header-anchor" href="#_40-fr-18426-april-28-1975" aria-label="Permalink to “40 FR 18426 (April 28, 1975)”">​</a></h3><p>The definition of Peyote is expanded upon, with an explicit statement that the name shall mean all parts of the plant growing or not, the seeds thereof, any extract from any part of such plant, and every compound, manufacture, salt, derivative, mixture, or preparation of the plant, its seeds, or its extracts. This is a more extended definition of the term Peyote than that used in 35 FR 14789, and a lisiing that had omitted this new definition (40 FR 28611) was subsequently corrected (41 FR 4015).</p><h3 id="_40-fr-19813-may-7-1975" tabindex="-1">40 FR 19813 (May 7, 1975) <a class="header-anchor" href="#_40-fr-19813-may-7-1975" aria-label="Permalink to “40 FR 19813 (May 7, 1975)”">​</a> <a class="header-anchor" href="#_40-fr-19813-may-7-1975" aria-label="Permalink to “40 FR 19813 (May 7, 1975)”">​</a></h3><p>It is announced that Difenoxin shall be effectively scheduled on June 1, 1975 as a 附表一 (Schedule I) drug, There was no 60 day notice for this act, as it was inspired by the placement of Difenoxin into 附表一 (Schedule I) of the 1961 Single Convention on Narcotic Drugs. Control within the US is required, and in a schedule deemed most appropriate. It was added to 附表一 (Schedule I) without opportunity for comment or objection.</p><h3 id="_40-fr-23071-may-28-1975" tabindex="-1">40 FR 23071 (May 28, 1975) <a class="header-anchor" href="#_40-fr-23071-may-28-1975" aria-label="Permalink to “40 FR 23071 (May 28, 1975)”">​</a> <a class="header-anchor" href="#_40-fr-23071-may-28-1975" aria-label="Permalink to “40 FR 23071 (May 28, 1975)”">​</a></h3><p>The industrial use of large quantities of Chloral make it unwieldy to be handled with the precautions felt due a 附表一 (Schedule I)V drug. Therefore, when packaged in a manner that is sealed, free from air and under nitrogen, it shall be considered an exempt preparation.</p><h3 id="_40-fr-23306-may-29-1975" tabindex="-1">40 FR 23306 (May 29, 1975) <a class="header-anchor" href="#_40-fr-23306-may-29-1975" aria-label="Permalink to “40 FR 23306 (May 29, 1975)”">​</a> <a class="header-anchor" href="#_40-fr-23306-may-29-1975" aria-label="Permalink to “40 FR 23306 (May 29, 1975)”">​</a></h3><p>A proposal made for the scheduling of Mecloqualone and of the Thiophene analog of Phencyclidine. See 40 FR 28611 for the 最终行政裁决命令 on these two drugs.</p><h3 id="_40-fr-23998-june-4-1975" tabindex="-1">40 FR 23998 (June 4, 1975) <a class="header-anchor" href="#_40-fr-23998-june-4-1975" aria-label="Permalink to “40 FR 23998 (June 4, 1975)”">​</a> <a class="header-anchor" href="#_40-fr-23998-june-4-1975" aria-label="Permalink to “40 FR 23998 (June 4, 1975)”">​</a></h3><p>A total of six benzodiazepines have been placed in 附表一 (Schedule I)V, effective July 2, 1975). These are Chlordiazepoxide, Clonazepam, Clorazepate, Diazepam, Flurazepam, and Oxazepam. Four pages of justification are presented. See 40 FR 4016 for the 初步拟定规则提案, and 40 FR8108 for several corrections. See 40 FR 26675 for a technical abeyance exception for combinations containing Chiordiazepoxide pending their consideration for exempt status.</p><h3 id="_40-fr-24216-june-5-1975" tabindex="-1">40 FR 24216 (June 5, 1975) <a class="header-anchor" href="#_40-fr-24216-june-5-1975" aria-label="Permalink to “40 FR 24216 (June 5, 1975)”">​</a> <a class="header-anchor" href="#_40-fr-24216-june-5-1975" aria-label="Permalink to “40 FR 24216 (June 5, 1975)”">​</a></h3><p>Thisisa proposal to exempt specific preparations containing the 附表一 (Schedule I)V drug Chlordiazepoxide from scheduling as they contain ingredients that vitiate the 滥用潜能. The combinations are Librax and Menrium. See 40 FR 52609 for 最终行政裁决命令.</p><h3 id="_40-fr-26675-june-25-1975" tabindex="-1">40 FR 26675 (June 25, 1975) <a class="header-anchor" href="#_40-fr-26675-june-25-1975" aria-label="Permalink to “40 FR 26675 (June 25, 1975)”">​</a> <a class="header-anchor" href="#_40-fr-26675-june-25-1975" aria-label="Permalink to “40 FR 26675 (June 25, 1975)”">​</a></h3><p>Two combinations containing Chlordiazepoxide that are being considered for exempt status (see 40 FR 24216) are held aside from the 附表一 (Schedule I)V placement of the parent drug (40 FR 23998).</p><h3 id="_40-fr-28611-july-8-1975" tabindex="-1">40 FR 28611 (July 8, 1975) <a class="header-anchor" href="#_40-fr-28611-july-8-1975" aria-label="Permalink to “40 FR 28611 (July 8, 1975)”">​</a> <a class="header-anchor" href="#_40-fr-28611-july-8-1975" aria-label="Permalink to “40 FR 28611 (July 8, 1975)”">​</a></h3><p>The final announcement of the scheduling of Mecloqualone and the Thiophene analog of Phencyclidine into 附表一 (Schedule I). The Mecloqualone was argued as being an immediate present danger and in the interests of public safety, its placement in 附表一 (Schedule I) was made 即日起立即生效 (July 10, 1975) without the usual thirty day period of waiting. The Thiophene analog of Phencyclidine scheduling became effective on August 11, 1975.</p><h3 id="_40-fr-42866-september-17-1975" tabindex="-1">40 FR 42866 (September 17, 1975) <a class="header-anchor" href="#_40-fr-42866-september-17-1975" aria-label="Permalink to “40 FR 42866 (September 17, 1975)”">​</a> <a class="header-anchor" href="#_40-fr-42866-september-17-1975" aria-label="Permalink to “40 FR 42866 (September 17, 1975)”">​</a></h3><p>Regulations are presented that concern the reporting requirements associated with the importation of Poppy Straw.</p><h3 id="_40-fr-44164-september-25-1975" tabindex="-1">40 FR 44164 (September 25, 1975) <a class="header-anchor" href="#_40-fr-44164-september-25-1975" aria-label="Permalink to “40 FR 44164 (September 25, 1975)”">​</a> <a class="header-anchor" href="#_40-fr-44164-september-25-1975" aria-label="Permalink to “40 FR 44164 (September 25, 1975)”">​</a></h3><p>A five page response by the DEA to NORML concerning the possible reevaluation of the scheduling status of Marihuana. This 行政请愿申请 is here 被依法驳回, but appeal action continued. See 44 FR 36123 for another denial of this 行政请愿申请.</p><h3 id="_40-fr-47525-october-9-1975" tabindex="-1">40 FR 47525 (October 9, 1975) <a class="header-anchor" href="#_40-fr-47525-october-9-1975" aria-label="Permalink to “40 FR 47525 (October 9, 1975)”">​</a> <a class="header-anchor" href="#_40-fr-47525-october-9-1975" aria-label="Permalink to “40 FR 47525 (October 9, 1975)”">​</a></h3><p>The DEA makes a request for comments concerning the possible placement of Phenylacetone under control. It has been used in the clandestine manufacture of Amphetamine, although there are several acknowledged legitimate uses of the chemical in a number of named manufacturing processes. See 44 FR 71822 for the placement of Phenylacetone into 附表一 (Schedule I)I.</p><h3 id="_40-fr-52609-november-11-1975" tabindex="-1">40 FR 52609 (November 11, 1975) <a class="header-anchor" href="#_40-fr-52609-november-11-1975" aria-label="Permalink to “40 FR 52609 (November 11, 1975)”">​</a> <a class="header-anchor" href="#_40-fr-52609-november-11-1975" aria-label="Permalink to “40 FR 52609 (November 11, 1975)”">​</a></h3><p>This is the final notification of the exemption of Librax and of Menrium from Scheduling. The 正式生效日期 is 11/28/75. See 40 FR242 16 for the 初步拟定规则提案. 40 FR 58132 (Dec. 15, 1975) A exemption has been 获得正式批准 for controlled substances, in small amounts and not intended for human use. Although it is stated that the form and concentration does not present any potential for abuse, Supelco was 获得正式批准 exemption for LSD in dosage units of 500 micrograms, which is considerably above the quantity that may be considered effective in man.</p><h3 id="_41-fr4015-january-28-1976" tabindex="-1">41 FR4015 (January 28, 1976) <a class="header-anchor" href="#_41-fr4015-january-28-1976" aria-label="Permalink to “41 FR4015 (January 28, 1976)”">​</a> <a class="header-anchor" href="#_41-fr4015-january-28-1976" aria-label="Permalink to “41 FR4015 (January 28, 1976)”">​</a></h3><p>A technical correction of some miswording regarding the classification of Peyote that appeared in 40 FR 18426.</p><h3 id="_41-fr6079-february-11-1976" tabindex="-1">41 FR6079 (February 11, 1976) <a class="header-anchor" href="#_41-fr6079-february-11-1976" aria-label="Permalink to “41 FR6079 (February 11, 1976)”">​</a> <a class="header-anchor" href="#_41-fr6079-february-11-1976" aria-label="Permalink to “41 FR6079 (February 11, 1976)”">​</a></h3><p>See 41 FR 21208.</p><h3 id="_41-fr-14885-april-8-1976" tabindex="-1">41 FR 14885 (April 8, 1976) <a class="header-anchor" href="#_41-fr-14885-april-8-1976" aria-label="Permalink to “41 FR 14885 (April 8, 1976)”">​</a> <a class="header-anchor" href="#_41-fr-14885-april-8-1976" aria-label="Permalink to “41 FR 14885 (April 8, 1976)”">​</a></h3><p>The proposal is presented for the removal of Apomorphine from 附表一 (Schedule I)I. See 41 FR 26568 for 最终行政裁决命令.</p><h3 id="_41-fr-15054-april-9-1976" tabindex="-1">41 FR 15054 (April 9, 1976) <a class="header-anchor" href="#_41-fr-15054-april-9-1976" aria-label="Permalink to “41 FR 15054 (April 9, 1976)”">​</a> <a class="header-anchor" href="#_41-fr-15054-april-9-1976" aria-label="Permalink to “41 FR 15054 (April 9, 1976)”">​</a></h3><p>An announcement of the formation of a liaison between the DEA and the FDA for the purpose of the exchange of documents, exchange of information on drug abuse and expert witnesses, the formation of a unified policy concerning publicity releases, and in general to avoid duplications of effort between the two groups.</p><h3 id="_41-fr-16487-april-19-1976" tabindex="-1">41 FR 16487 (April 19, 1976) <a class="header-anchor" href="#_41-fr-16487-april-19-1976" aria-label="Permalink to “41 FR 16487 (April 19, 1976)”">​</a> <a class="header-anchor" href="#_41-fr-16487-april-19-1976" aria-label="Permalink to “41 FR 16487 (April 19, 1976)”">​</a></h3><p>Proposal for the decontrol of Dextrorphan. It had been found not to have sufficient potential for either abuse or abuse liability to justify its continued control in any schedule under the act. See 41 FR 43401 for 最终行政裁决命令.</p><h3 id="_41-fr-19227-may-11-1976" tabindex="-1">41 FR 19227 (May 11, 1976) <a class="header-anchor" href="#_41-fr-19227-may-11-1976" aria-label="Permalink to “41 FR 19227 (May 11, 1976)”">​</a> <a class="header-anchor" href="#_41-fr-19227-may-11-1976" aria-label="Permalink to “41 FR 19227 (May 11, 1976)”">​</a></h3><p>Proposal for the decontrol of Nalbuphine. See 41 FR 43401 for the announcement of 最终行政裁决命令.</p><h3 id="_41-fr-21208-may-24-1976" tabindex="-1">41 FR 21208 (May 24, 1976) <a class="header-anchor" href="#_41-fr-21208-may-24-1976" aria-label="Permalink to “41 FR 21208 (May 24, 1976)”">​</a> <a class="header-anchor" href="#_41-fr-21208-may-24-1976" aria-label="Permalink to “41 FR 21208 (May 24, 1976)”">​</a></h3><p>The 受控物质法案 (CSA) (Section 306) requires that the 司法部长 establish aggregate production for all controlled substances listed in Schedules I and II. Most of the larger production quotas deal with commercial drugs and are thus 附表一 (Schedule I)I items, and the 附表一 (Schedule I) needs are limited to minor quantities required for research or analysis. 2,5-Dimethoxyamphetamine is, however, used in the photographic industry and this entry shows the magnitude of these needs; a proposed revised 1976 quota of 45,000,000 grams of the free base. The initial estimate was 30,000,000 grams in 41 FR 6079. The only 附表一 (Schedule I)I drugs which exceed this number in proposed . quotas, are Codeine and Morphine.</p><h3 id="_41-fr-26568-june-28-1976" tabindex="-1">41 FR 26568 (June 28, 1976) <a class="header-anchor" href="#_41-fr-26568-june-28-1976" aria-label="Permalink to “41 FR 26568 (June 28, 1976)”">​</a> <a class="header-anchor" href="#_41-fr-26568-june-28-1976" aria-label="Permalink to “41 FR 26568 (June 28, 1976)”">​</a></h3><p>Final announcement of the decontrolling of Apomorphine. See 41 FR 14885 for the 初步拟定规则提案.</p><h3 id="_41-fr-30376-july-23-1976" tabindex="-1">41 FR 30376 (July 23, 1976) <a class="header-anchor" href="#_41-fr-30376-july-23-1976" aria-label="Permalink to “41 FR 30376 (July 23, 1976)”">​</a> <a class="header-anchor" href="#_41-fr-30376-july-23-1976" aria-label="Permalink to “41 FR 30376 (July 23, 1976)”">​</a></h3><p>Several FDA reports with discussions concerning the efficacy of Meprobamate, of Chlordiazepoxide and of Meperidine.</p><h3 id="_41-fr31553-july-29-1976" tabindex="-1">41 FR31553 (July 29, 1976) <a class="header-anchor" href="#_41-fr31553-july-29-1976" aria-label="Permalink to “41 FR31553 (July 29, 1976)”">​</a> <a class="header-anchor" href="#_41-fr31553-july-29-1976" aria-label="Permalink to “41 FR31553 (July 29, 1976)”">​</a></h3><p>This is an 初步拟定规则提案 for the scheduling of Halazepam and Prazepam in 附表一 (Schedule I)V, and Loperamide in 附表五 (Schedule V). Halazepam was proposed again for 附表一 (Schedule I)V placement in 46 FR 23953; see 46 FR 53407 for 最终行政裁决命令. See 41 FR 55176 for the 最终行政裁决命令 on Prazepam. See 42 FR 25498 for the placement of Loperamide into 附表五 (Schedule V), and 47 FR 49840 for its eventual 取消管制/去列管.</p><h3 id="_41-fr-32756-august-5-1976" tabindex="-1">41 FR 32756 (August 5, 1976) <a class="header-anchor" href="#_41-fr-32756-august-5-1976" aria-label="Permalink to “41 FR 32756 (August 5, 1976)”">​</a> <a class="header-anchor" href="#_41-fr-32756-august-5-1976" aria-label="Permalink to “41 FR 32756 (August 5, 1976)”">​</a></h3><p>A proposed regulation to prohibit the distribution of complimentary samples of scheduled drugs from manufacturers to their customers. See 42 FR 35991 for 最终行政裁决命令.</p><h3 id="_41-fr42957-september-29-1976" tabindex="-1">41 FR42957 (September 29, 1976) <a class="header-anchor" href="#_41-fr42957-september-29-1976" aria-label="Permalink to “41 FR42957 (September 29, 1976)”">​</a> <a class="header-anchor" href="#_41-fr42957-september-29-1976" aria-label="Permalink to “41 FR42957 (September 29, 1976)”">​</a></h3><p>Proposal for the placement of Dextropropoxyphene into 附表一 (Schedule I)V. See 42 FR 8636 for 最终行政裁决命令.</p><h3 id="_41-fr-43401-october-1-1976" tabindex="-1">41 FR 43401 (October 1, 1976) <a class="header-anchor" href="#_41-fr-43401-october-1-1976" aria-label="Permalink to “41 FR 43401 (October 1, 1976)”">​</a> <a class="header-anchor" href="#_41-fr-43401-october-1-1976" aria-label="Permalink to “41 FR 43401 (October 1, 1976)”">​</a></h3><p>Final announcement for the decontrolling of Dextrorphan and Nalbuphine. See 42 FR 15679 for several corrections of errors in this entry. See 41 FR 16487 for the 初步拟定规则提案 for the 取消管制/去列管 of Dextrorphan, and 41 FR 19227 for the 初步拟定规则提案 for the 取消管制/去列管 of Nalbuphine. Also, there are several “changes in nomenclature, numbering, and non-substantive clarifyings” that are made here, changing the detail of the April 1, 1976 publication of Title 21 in the Code of Federal Regulations. Most of these corrections are simple typographical errors or omissions.</p><h3 id="_41-fr51036-november-19-1976" tabindex="-1">41 FR51036 (November 19, 1976) <a class="header-anchor" href="#_41-fr51036-november-19-1976" aria-label="Permalink to “41 FR51036 (November 19, 1976)”">​</a> <a class="header-anchor" href="#_41-fr51036-november-19-1976" aria-label="Permalink to “41 FR51036 (November 19, 1976)”">​</a></h3><p>This is the 初步拟定规则提案 for the growing of the poppy Papaver bracteatum in the United States. This plant, a relative of Papaver somniferum (or the Opium Poppy), is unusual in that it produces essentially a single alkaloid, Thebaine. Thebaine itself is a convulsant and thus devoid of 滥用潜能, but this compound could serve, through chemical conversion, aS a raw material for many of the Opium 麻醉药品s. This would make a domestic source of opium-derived 麻醉药品s available to the U.S. pharmaceuticalindustry. See 41 FR 55556, 42 FR 5370 and 42 FR 12889 for the schedules of 行政听证会s. See 42 FR 28560 for the reports of these 行政听证会s and for the final ruling.</p><h3 id="_41-fr55176-december-17-1976" tabindex="-1">41 FR55176 (December 17, 1976) <a class="header-anchor" href="#_41-fr55176-december-17-1976" aria-label="Permalink to “41 FR55176 (December 17, 1976)”">​</a> <a class="header-anchor" href="#_41-fr55176-december-17-1976" aria-label="Permalink to “41 FR55176 (December 17, 1976)”">​</a></h3><p>Final announcement for the placing of Prazepam into 附表一 (Schedule I)V. See 41 FR31553 for the 初步拟定规则提案.</p><h3 id="_42-fr5370-january-28-1977" tabindex="-1">42 FR5370 (January 28, 1977) <a class="header-anchor" href="#_42-fr5370-january-28-1977" aria-label="Permalink to “42 FR5370 (January 28, 1977)”">​</a> <a class="header-anchor" href="#_42-fr5370-january-28-1977" aria-label="Permalink to “42 FR5370 (January 28, 1977)”">​</a></h3><p>Another postponement of the Papaver bracteatum 行政听证会s. See 42 FR 28560 for the final report on these 行政听证会s.</p><h3 id="_42-fr-8636-february-11-1977" tabindex="-1">42 FR 8636 (February 11, 1977) <a class="header-anchor" href="#_42-fr-8636-february-11-1977" aria-label="Permalink to “42 FR 8636 (February 11, 1977)”">​</a> <a class="header-anchor" href="#_42-fr-8636-february-11-1977" aria-label="Permalink to “42 FR 8636 (February 11, 1977)”">​</a></h3><p>Final announcement for the placing of Dextropropoxyphene into 附表一 (Schedule I)V, effective March 14, 1977. 42 FR 12889 (March7, 1977) Anotice rescheduling the 行政听证会s concerning the internal production of the poppy, Papaver bracteatum. See 41 FR 51036 for the 初步拟定规则提案, and 41 FR 55558 for original 行政听证会 dates. See 42 FR 28560 for 最终行政裁决命令.</p><h3 id="_42-fr-15679-march-23-1977" tabindex="-1">42 FR 15679 (March 23, 1977) <a class="header-anchor" href="#_42-fr-15679-march-23-1977" aria-label="Permalink to “42 FR 15679 (March 23, 1977)”">​</a> <a class="header-anchor" href="#_42-fr-15679-march-23-1977" aria-label="Permalink to “42 FR 15679 (March 23, 1977)”">​</a></h3><p>Corrections in the entries of 41 FR 43401 concerning the 取消管制/去列管 of Dextrorphan and of Nalbuphine.</p><h3 id="_42-fr-25498-may-18-1977" tabindex="-1">42 FR 25498 (May 18, 1977) <a class="header-anchor" href="#_42-fr-25498-may-18-1977" aria-label="Permalink to “42 FR 25498 (May 18, 1977)”">​</a> <a class="header-anchor" href="#_42-fr-25498-may-18-1977" aria-label="Permalink to “42 FR 25498 (May 18, 1977)”">​</a></h3><p>Final notice for the placement of Loperamide in 附表五 (Schedule V), effective June 17, 1977. See41 FR 31553 for the 初步拟定规则提案.</p><h3 id="_42-fr-28560-june-3-1977" tabindex="-1">42 FR 28560 (June 3, 1977) <a class="header-anchor" href="#_42-fr-28560-june-3-1977" aria-label="Permalink to “42 FR 28560 (June 3, 1977)”">​</a> <a class="header-anchor" href="#_42-fr-28560-june-3-1977" aria-label="Permalink to “42 FR 28560 (June 3, 1977)”">​</a></h3><p>The proposal for the domestic growing of a Thebainerich Opium poppy Papaver bracteatum (see 41 FR 51036 for the 初步拟定规则提案) generated considerable controversy. The majority of written comments and oral statements favored domestic production, largely as a means to meet the anticipated demand for Thebaine for foreseeable pharmaceutical need. The voices of opposition (smaller in number, but including the State Department, the Department of Health, Education and Welfare, the United Nations Commission on Narcotic Drugs, and the Government of Canada) argued that a move such as this would weaken our constraints upon, and controls over foreign production. It was decided that the production of this poppy was not in the public interest, and the proposal was withdrawn.</p><h3 id="_42-fr-28877-june-6-1977" tabindex="-1">42 FR 28877 (June 6, 1977) <a class="header-anchor" href="#_42-fr-28877-june-6-1977" aria-label="Permalink to “42 FR 28877 (June 6, 1977)”">​</a> <a class="header-anchor" href="#_42-fr-28877-june-6-1977" aria-label="Permalink to “42 FR 28877 (June 6, 1977)”">​</a></h3><p>Instructions to pharmacists regarding the storing of prescription data. No drugs mentioned.</p><h3 id="_42-fr-31460-june-21-1977" tabindex="-1">42 FR 31460 (June 21, 1977) <a class="header-anchor" href="#_42-fr-31460-june-21-1977" aria-label="Permalink to “42 FR 31460 (June 21, 1977)”">​</a> <a class="header-anchor" href="#_42-fr-31460-june-21-1977" aria-label="Permalink to “42 FR 31460 (June 21, 1977)”">​</a></h3><p>Arulemaking proposal for the preservation of confidentiality of subjects in research.</p><h3 id="_42-fr-32805-june-28-1977" tabindex="-1">42 FR 32805 (June 28, 1977) <a class="header-anchor" href="#_42-fr-32805-june-28-1977" aria-label="Permalink to “42 FR 32805 (June 28, 1977)”">​</a> <a class="header-anchor" href="#_42-fr-32805-june-28-1977" aria-label="Permalink to “42 FR 32805 (June 28, 1977)”">​</a></h3><p>Proposal for the placernent of Lorazepam into 附表一 (Schedule I)V. See 42 FR 54546 for 最终行政裁决命令.</p><h3 id="_42-fr-35991-july-13-1977" tabindex="-1">42 FR 35991 (July 13, 1977) <a class="header-anchor" href="#_42-fr-35991-july-13-1977" aria-label="Permalink to “42 FR 35991 (July 13, 1977)”">​</a> <a class="header-anchor" href="#_42-fr-35991-july-13-1977" aria-label="Permalink to “42 FR 35991 (July 13, 1977)”">​</a></h3><p>An announcement of the withdrawal of the DEA proposal that would prohibit the manufacturers of Schedules II through V drugs to promote them through their free distribution to customers. Safer promotion methods are nevertheless encouraged.</p><h3 id="_42-fr-54546-october-7-1977" tabindex="-1">42 FR 54546 (October 7, 1977) <a class="header-anchor" href="#_42-fr-54546-october-7-1977" aria-label="Permalink to “42 FR 54546 (October 7, 1977)”">​</a> <a class="header-anchor" href="#_42-fr-54546-october-7-1977" aria-label="Permalink to “42 FR 54546 (October 7, 1977)”">​</a></h3><p>Final notice for the placing of Lorazepam in 附表一 (Schedule I)V, effective October 3, 1977. See 42 FR 32805 for the 初步拟定规则提案.</p><h3 id="_42-fr-54945-october-12-1977" tabindex="-1">42 FR 54945 (October 12, 1977) <a class="header-anchor" href="#_42-fr-54945-october-12-1977" aria-label="Permalink to “42 FR 54945 (October 12, 1977)”">​</a> <a class="header-anchor" href="#_42-fr-54945-october-12-1977" aria-label="Permalink to “42 FR 54945 (October 12, 1977)”">​</a></h3><p>This is a notice expressing concerning over the confidentiality of research subjects, and the exemption of researchers from prosecution.</p><h3 id="_42-fr-55374-october-14-1977" tabindex="-1">42 FR 55374 (October 14 1977) <a class="header-anchor" href="#_42-fr-55374-october-14-1977" aria-label="Permalink to “42 FR 55374 (October 14 1977)”">​</a> <a class="header-anchor" href="#_42-fr-55374-october-14-1977" aria-label="Permalink to “42 FR 55374 (October 14 1977)”">​</a></h3><p>An announcement of a public 行政听证会 concerning the broad abuse of amphetamines. There is presented here an extensive history of the efforts to control the availability of Amphetamine. This FDA notice defines the term “Amphetamine” to include both the racemate and the dextro-isomer, of both Amphetamine and Methamphetamine.</p><h3 id="_42-fr-57456-november-3-1977" tabindex="-1">42 FR 57456 (November 3, 1977) <a class="header-anchor" href="#_42-fr-57456-november-3-1977" aria-label="Permalink to “42 FR 57456 (November 3, 1977)”">​</a> <a class="header-anchor" href="#_42-fr-57456-november-3-1977" aria-label="Permalink to “42 FR 57456 (November 3, 1977)”">​</a></h3><p>Notification of a ruling that grants supoena powers to the Administrative Law Judge for the DEA, as a tool to facilitate administrative 行政听证会s.</p><h3 id="_42-fr-63647-december-17-1977" tabindex="-1">42 FR 63647 (December 17, 1977) <a class="header-anchor" href="#_42-fr-63647-december-17-1977" aria-label="Permalink to “42 FR 63647 (December 17, 1977)”">​</a> <a class="header-anchor" href="#_42-fr-63647-december-17-1977" aria-label="Permalink to “42 FR 63647 (December 17, 1977)”">​</a></h3><p>Notice is given for the proposed relocation of Phencyclidine from 附表一 (Schedule I)II to 附表一 (Schedule I)I. See 43 FR 3359.</p><h3 id="_43-fr-3359-january-25-1978" tabindex="-1">43 FR 3359 (January 25, 1978) <a class="header-anchor" href="#_43-fr-3359-january-25-1978" aria-label="Permalink to “43 FR 3359 (January 25, 1978)”">​</a> <a class="header-anchor" href="#_43-fr-3359-january-25-1978" aria-label="Permalink to “43 FR 3359 (January 25, 1978)”">​</a></h3><p>This is the final announcement of the transfer of Phencyclidine to 附表一 (Schedule I)I from 附表一 (Schedule I)II. The 正式生效日期 is February 24, 1978. See 42 FR 63647 for the 初步拟定规则提案.</p><h3 id="_43-fr-11588-march-20-1978" tabindex="-1">43 FR 11588 (March 20, 1978) <a class="header-anchor" href="#_43-fr-11588-march-20-1978" aria-label="Permalink to “43 FR 11588 (March 20, 1978)”">​</a> <a class="header-anchor" href="#_43-fr-11588-march-20-1978" aria-label="Permalink to “43 FR 11588 (March 20, 1978)”">​</a></h3><p>Notice for the proposed placement of 1Piperidinocyclohexanecarbonitrile (PCC) and 1- Phenylcyclohexylamine (PCH) into 附表一 (Schedule I)I, as immediate 化学前体s of Phencyclidine. See 43 FR 21324 for 最终行政裁决命令.</p><h3 id="_43-fr-21324-may-17-1978" tabindex="-1">43 FR 21324 (May 17, 1978) <a class="header-anchor" href="#_43-fr-21324-may-17-1978" aria-label="Permalink to “43 FR 21324 (May 17, 1978)”">​</a> <a class="header-anchor" href="#_43-fr-21324-may-17-1978" aria-label="Permalink to “43 FR 21324 (May 17, 1978)”">​</a></h3><p>This is the 最终行政裁决命令 for the listing of 1-Phenylcyclohexylamine and 1-Piperidinocyclo-hexanecarbonitrile as immediate 化学前体s to Phencyclidine, as 附表一 (Schedule I)I substances. See 43 FR 11588 for the 初步拟定规则提案. The 正式生效日期 is June 16, 1978.</p><h3 id="_43-fr-27560-june-26-1978" tabindex="-1">43 FR 27560 (June 26, 1978) <a class="header-anchor" href="#_43-fr-27560-june-26-1978" aria-label="Permalink to “43 FR 27560 (June 26, 1978)”">​</a> <a class="header-anchor" href="#_43-fr-27560-june-26-1978" aria-label="Permalink to “43 FR 27560 (June 26, 1978)”">​</a></h3><p>The is the 初步拟定规则提案 for the scheduling of preparations containing a mixture of Difenoxin and Atropine into either 附表一 (Schedule I)V or 附表五 (Schedule V), depending upon the amount of drug present. See 43 FR 38382 for 最终行政裁决命令.</p><h3 id="_43-fr-34503-august-4-1978" tabindex="-1">43 FR 34503 (August 4, 1978) <a class="header-anchor" href="#_43-fr-34503-august-4-1978" aria-label="Permalink to “43 FR 34503 (August 4, 1978)”">​</a> <a class="header-anchor" href="#_43-fr-34503-august-4-1978" aria-label="Permalink to “43 FR 34503 (August 4, 1978)”">​</a></h3><p>This is a response to a request that the product Medigesic (containing the 附表一 (Schedule I)II drug Butalbital) be exempt from controls in its sales in the OTC market. The request was 被依法驳回. See 43 FR 44839.</p><h3 id="_43-fr-35734-august-11-1978" tabindex="-1">43 FR 35734 (August 11, 1978) <a class="header-anchor" href="#_43-fr-35734-august-11-1978" aria-label="Permalink to “43 FR 35734 (August 11, 1978)”">​</a> <a class="header-anchor" href="#_43-fr-35734-august-11-1978" aria-label="Permalink to “43 FR 35734 (August 11, 1978)”">​</a></h3><p>This is the 初步拟定规则提案 for the placement of NEthyl-1-phenylcyclohexylamine and 1-(1Phenylcyclohexyl)pyrrolidine (PCE and PHP) into 附表一 (Schedule I) as hallucinogens. See 43 FR 43295 for 最终行政裁决命令.</p><h3 id="_43-fr-38382-august-28-1978" tabindex="-1">43 FR 38382 (August 28, 1978) <a class="header-anchor" href="#_43-fr-38382-august-28-1978" aria-label="Permalink to “43 FR 38382 (August 28, 1978)”">​</a> <a class="header-anchor" href="#_43-fr-38382-august-28-1978" aria-label="Permalink to “43 FR 38382 (August 28, 1978)”">​</a></h3><p>Final announcement for the placement of Difenoxin with Atropine in调整转移至附表s IV and V, depending upon the amount present. This becomes effective on September 27, 1978. The proposed. trade names are Motofen and Motofen HalfStrength. See 43 FR 27560 for the 初步拟定规则提案.</p><h3 id="_43-fr-40884-september-13-1978" tabindex="-1">43 FR 40884 (September 13, 1978) <a class="header-anchor" href="#_43-fr-40884-september-13-1978" aria-label="Permalink to “43 FR 40884 (September 13, 1978)”">​</a> <a class="header-anchor" href="#_43-fr-40884-september-13-1978" aria-label="Permalink to “43 FR 40884 (September 13, 1978)”">​</a></h3><p>This is a notice of the intended placement of Pentazocine into 附表一 (Schedule I)V. See 44 FR 2169 for 最终行政裁决命令.</p><h3 id="_43-fr-43295-september-25-1978" tabindex="-1">43 FR 43295 (September 25, 1978) <a class="header-anchor" href="#_43-fr-43295-september-25-1978" aria-label="Permalink to “43 FR 43295 (September 25, 1978)”">​</a> <a class="header-anchor" href="#_43-fr-43295-september-25-1978" aria-label="Permalink to “43 FR 43295 (September 25, 1978)”">​</a></h3><p>Final announcement for the placement of PCE and PHP into 附表一 (Schedule I), effective October 25, 1978. See 43 FR 35734 for the 初步拟定规则提案.</p><h3 id="_43-fr-44839-september-29-1978" tabindex="-1">43 FR 44839 (September 29, 1978) <a class="header-anchor" href="#_43-fr-44839-september-29-1978" aria-label="Permalink to “43 FR 44839 (September 29, 1978)”">​</a> <a class="header-anchor" href="#_43-fr-44839-september-29-1978" aria-label="Permalink to “43 FR 44839 (September 29, 1978)”">​</a></h3><p>This is the final ruling concerning the denial of exemption for the Butalbital-containing product, Medigesic. See 43 FR 34503 for initial statement of denial.</p><h3 id="_43-fr-57922-december-11-1978" tabindex="-1">43 FR 57922 (December 11, 1978) <a class="header-anchor" href="#_43-fr-57922-december-11-1978" aria-label="Permalink to “43 FR 57922 (December 11, 1978)”">​</a> <a class="header-anchor" href="#_43-fr-57922-december-11-1978" aria-label="Permalink to “43 FR 57922 (December 11, 1978)”">​</a></h3><p>This is a presentation of the regulations intended to regulate the reporting of sales and of customer identification, in connection with the transfer of Piperidine. This action was explicitly demanded by the Psychotropic Substance Act of 1978. See 44 FR 12993 for further action on these proposed regulations.</p><h3 id="_44fr2169-january-10-1979" tabindex="-1">44FR2169 (January 10, 1979) <a class="header-anchor" href="#_44fr2169-january-10-1979" aria-label="Permalink to “44FR2169 (January 10, 1979)”">​</a> <a class="header-anchor" href="#_44fr2169-january-10-1979" aria-label="Permalink to “44FR2169 (January 10, 1979)”">​</a></h3><p>Final announcement for the scheduling of Pentazocine, effective February 9, 1979. See 43 FR 40884 for the 初步拟定规则提案.</p><h3 id="_44-fr-12993-march-9-1979" tabindex="-1">44 FR 12993 (March 9, 1979) <a class="header-anchor" href="#_44-fr-12993-march-9-1979" aria-label="Permalink to “44 FR 12993 (March 9, 1979)”">​</a> <a class="header-anchor" href="#_44-fr-12993-march-9-1979" aria-label="Permalink to “44 FR 12993 (March 9, 1979)”">​</a></h3><p>A notification of regulatory proposals concerning the reporting of Piperidine sales, in conformity with the requirements of The Psychotropic Substances Act of 1978. See 45 FR 52397 for comments. See 43 FR 57922 for the 初步拟定规则提案 of these regulations.</p><h3 id="_44-fr-18968-march-30-1979" tabindex="-1">44 FR 18968 (March 30, 1979) <a class="header-anchor" href="#_44-fr-18968-march-30-1979" aria-label="Permalink to “44 FR 18968 (March 30, 1979)”">​</a> <a class="header-anchor" href="#_44-fr-18968-march-30-1979" aria-label="Permalink to “44 FR 18968 (March 30, 1979)”">​</a></h3><p>A change in regulations concerning exempted 中枢兴奋剂s and 中枢抑制剂s.</p><h3 id="_44-fr-24584-april-26-1979" tabindex="-1">44 FR 24584 (April 26, 1979) <a class="header-anchor" href="#_44-fr-24584-april-26-1979" aria-label="Permalink to “44 FR 24584 (April 26, 1979)”">​</a> <a class="header-anchor" href="#_44-fr-24584-april-26-1979" aria-label="Permalink to “44 FR 24584 (April 26, 1979)”">​</a></h3><p>A proposal for rule-making, to clarify the placement of 附表一 (Schedule I) and II 麻醉药品s in lower schedules, based upon the weight of the drug involved. All these weights shall be expressed as weight of free anhydrous base, and the law shall have this wording added. See 44 FR 40888 for the final notice.</p><h3 id="_44-fr-33695-june-12-1979" tabindex="-1">44 FR 33695 (June 12, 1979) <a class="header-anchor" href="#_44-fr-33695-june-12-1979" aria-label="Permalink to “44 FR 33695 (June 12, 1979)”">​</a> <a class="header-anchor" href="#_44-fr-33695-june-12-1979" aria-label="Permalink to “44 FR 33695 (June 12, 1979)”">​</a></h3><p>This is an advanced notice for proposed rule-making in the area of 麻醉药品s importation policy. For the notice for public 行政听证会s, see 45 FR 49255.</p><h3 id="_44-fr-36123-june-20-1979" tabindex="-1">44 FR 36123 (June 20, 1979) <a class="header-anchor" href="#_44-fr-36123-june-20-1979" aria-label="Permalink to “44 FR 36123 (June 20, 1979)”">​</a> <a class="header-anchor" href="#_44-fr-36123-june-20-1979" aria-label="Permalink to “44 FR 36123 (June 20, 1979)”">​</a></h3><p>This is the final denial of a 行政请愿申请 from NORML requesting the removal of Marihuana and synthetic THC from 附表一 (Schedule I). See 40 FR 44164 for an earlier denial, and for the leading citations to the early history of this 行政请愿申请.</p><h3 id="_44-fr-40888-july-13-1979" tabindex="-1">44 FR 40888 (July 13, 1979) <a class="header-anchor" href="#_44-fr-40888-july-13-1979" aria-label="Permalink to “44 FR 40888 (July 13, 1979)”">​</a> <a class="header-anchor" href="#_44-fr-40888-july-13-1979" aria-label="Permalink to “44 FR 40888 (July 13, 1979)”">​</a></h3><p>This is the final notice of the proposed specification of employing the free-base weight measure for 麻醉药品 exemption determination. See 44 FR 24584 for the 初步拟定规则提案.</p><h3 id="_44-fr-40899-july-13-1979" tabindex="-1">44 FR 40899 (July 13, 1979) <a class="header-anchor" href="#_44-fr-40899-july-13-1979" aria-label="Permalink to “44 FR 40899 (July 13, 1979)”">​</a> <a class="header-anchor" href="#_44-fr-40899-july-13-1979" aria-label="Permalink to “44 FR 40899 (July 13, 1979)”">​</a></h3><p>An extension of the period allowing comments to be made on the Narcotics Importation Policy. See 44 FR 33695.</p><h3 id="_44-fr42178-july-19-1979" tabindex="-1">44 FR42178 (July 19, 1979) <a class="header-anchor" href="#_44-fr42178-july-19-1979" aria-label="Permalink to “44 FR42178 (July 19, 1979)”">​</a> <a class="header-anchor" href="#_44-fr42178-july-19-1979" aria-label="Permalink to “44 FR42178 (July 19, 1979)”">​</a></h3><p>An amendment to the 行政听证会 procedures limiting the time periods involved in the exchange of comments and legal opinions. See 44 FR 55332 for the final notice.</p><h3 id="_44-fr-54312-september-19-1979" tabindex="-1">44 FR 54312 (September 19, 1979) <a class="header-anchor" href="#_44-fr-54312-september-19-1979" aria-label="Permalink to “44 FR 54312 (September 19, 1979)”">​</a> <a class="header-anchor" href="#_44-fr-54312-september-19-1979" aria-label="Permalink to “44 FR 54312 (September 19, 1979)”">​</a></h3><p>An announcement of the publication of a semiannual agenda of regulations being considered, in keeping with an Executive Order.</p><h3 id="_44-fr-55332-september-28-1979" tabindex="-1">44 FR 55332 (September 28, 1979) <a class="header-anchor" href="#_44-fr-55332-september-28-1979" aria-label="Permalink to “44 FR 55332 (September 28, 1979)”">​</a> <a class="header-anchor" href="#_44-fr-55332-september-28-1979" aria-label="Permalink to “44 FR 55332 (September 28, 1979)”">​</a></h3><p>The final notice on the amended 行政听证会s procedures. See 44 FR 42178 for details of the 初步拟定规则提案.</p><h3 id="_44-fr-56324-october-1-1979" tabindex="-1">44 FR 56324 (October 1, 1979) <a class="header-anchor" href="#_44-fr-56324-october-1-1979" aria-label="Permalink to “44 FR 56324 (October 1, 1979)”">​</a> <a class="header-anchor" href="#_44-fr-56324-october-1-1979" aria-label="Permalink to “44 FR 56324 (October 1, 1979)”">​</a></h3><p>An internal delegation of authority for the enforcement of forfeiture regulations.</p><h3 id="_44-fr71822-december-12-1979" tabindex="-1">44 FR71822 (December 12, 1979) <a class="header-anchor" href="#_44-fr71822-december-12-1979" aria-label="Permalink to “44 FR71822 (December 12, 1979)”">​</a> <a class="header-anchor" href="#_44-fr71822-december-12-1979" aria-label="Permalink to “44 FR71822 (December 12, 1979)”">​</a></h3><p>The legal provision for making immediate 化学前体s of scheduled substances themselves equivalently scheduled, is invoked here in the case of Phenylacetone. It is an immediate 化学前体 of both Amphetamine and Methamphetamine, through either of two synthetic procedures. One is that of reductive amination with methylamine (or ammonia) employing aluminum and mercuric chloride; the other is the Leuckart reaction employing formic acid and methylamine followed by acid hydrolysis. The Precursor Liaison Program is a cooperative effort with manufacturers and wholesalers to follow the sale of 化学前体s, but it is voluntary. This notice is an announcement of the placement of Phenylacetone (P2P) into 附表一 (Schedule I)I, effective February 11, 1980. Aprevious request for comments (40 FR 47525) produced 29 letters. The 正式生效日期 of this proposal has been put off until February 11, 1980 to give time for additional comments. See 45 FR 26696 for these additional comments and the responses of the DEA to them.</p><h2 id="_1980-—-1984-年-止痛药去列管博弈与甲喹酮国会强制撤市" tabindex="-1">1980 — 1984 年：止痛药去列管博弈与甲喹酮国会强制撤市 <a class="header-anchor" href="#_1980-—-1984-年-止痛药去列管博弈与甲喹酮国会强制撤市" aria-label="Permalink to “1980 — 1984 年：止痛药去列管博弈与甲喹酮国会强制撤市”">​</a> <a class="header-anchor" href="#_1980-—-1984-年-止痛药去列管博弈与甲喹酮国会强制撤市" aria-label="Permalink to “1980 — 1984 年：止痛药去列管博弈与甲喹酮国会强制撤市”">​</a></h2><h3 id="_45-fr-3923-january-21-1980" tabindex="-1">45 FR 3923 (January 21, 1980) <a class="header-anchor" href="#_45-fr-3923-january-21-1980" aria-label="Permalink to “45 FR 3923 (January 21, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-3923-january-21-1980" aria-label="Permalink to “45 FR 3923 (January 21, 1980)”">​</a></h3><p>Two 行政请愿申请s were received by the DEA recommending that Dextropropoxyphene be reclassified as a 附表一 (Schedule I)I drug, due to reports of overdose, toxicity, and deaths that had been reported following its use. These 行政请愿申请s were 被依法驳回, but a proposal was officially made to classify Dextropropoxyphene as a 麻醉药品 drug, even though it will remain within 附表一 (Schedule I)V. See 45 FR 42264 for 最终行政裁决命令 on this matter.</p><h3 id="_45-fr-9289-february-12-1980" tabindex="-1">45 FR 9289 (February 12, 1980) <a class="header-anchor" href="#_45-fr-9289-february-12-1980" aria-label="Permalink to “45 FR 9289 (February 12, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-9289-february-12-1980" aria-label="Permalink to “45 FR 9289 (February 12, 1980)”">​</a></h3><p>A notification of proposed rulemaking concerning the importation of 麻醉药品 raw material. See 45 FR 49255 for 行政听证会 announcement.</p><h3 id="_45-fr-20096-march-27-1980" tabindex="-1">45 FR 20096 (March 27, 1980) <a class="header-anchor" href="#_45-fr-20096-march-27-1980" aria-label="Permalink to “45 FR 20096 (March 27, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-20096-march-27-1980" aria-label="Permalink to “45 FR 20096 (March 27, 1980)”">​</a></h3><p>An amendment of the definition of property (in regard to seizure and forfeiture) to include the term moneys and other assets.</p><h3 id="_45-fr-21652-april-2-1980" tabindex="-1">45 FR 21652 (April 2, 1980) <a class="header-anchor" href="#_45-fr-21652-april-2-1980" aria-label="Permalink to “45 FR 21652 (April 2, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-21652-april-2-1980" aria-label="Permalink to “45 FR 21652 (April 2, 1980)”">​</a></h3><p>A procedural amendment is proposed that permits exchange of prescription information. No drugs mentioned. See 46 FR 48918 for 最终行政裁决命令.</p><h3 id="_45-fr-24128-april-9-1980" tabindex="-1">45 FR 24128 (April 9, 1980) <a class="header-anchor" href="#_45-fr-24128-april-9-1980" aria-label="Permalink to “45 FR 24128 (April 9, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-24128-april-9-1980" aria-label="Permalink to “45 FR 24128 (April 9, 1980)”">​</a></h3><p>This isa statement of policy concerning the inclusion of controlled substances in emergency kits. See 45 FR 40576 for a related notice.</p><h3 id="_45-fr-24198-april-9-1980" tabindex="-1">45 FR 24198 (April 9, 1980) <a class="header-anchor" href="#_45-fr-24198-april-9-1980" aria-label="Permalink to “45 FR 24198 (April 9, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-24198-april-9-1980" aria-label="Permalink to “45 FR 24198 (April 9, 1980)”">​</a></h3><p>A proposed rule-making notification concerning record keeping, records and reports.</p><h3 id="_45-fr-24199-april-9-1980" tabindex="-1">45 FR 24199 (April 9, 1980) <a class="header-anchor" href="#_45-fr-24199-april-9-1980" aria-label="Permalink to “45 FR 24199 (April 9, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-24199-april-9-1980" aria-label="Permalink to “45 FR 24199 (April 9, 1980)”">​</a></h3><p>A proposal for the modification of procedures for filling of prescriptions for 附表一 (Schedule I)I substances. See 45 FR 54329 for 最终行政裁决命令.</p><h3 id="_45-fr-26696-april-21-1980" tabindex="-1">45 FR 26696 (April 21, 1980) <a class="header-anchor" href="#_45-fr-26696-april-21-1980" aria-label="Permalink to “45 FR 26696 (April 21, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-26696-april-21-1980" aria-label="Permalink to “45 FR 26696 (April 21, 1980)”">​</a></h3><p>Phenylacetone was placed in 附表一 (Schedule I)I on December 12, 1979 to become effective February 11, 1980 (see 44 FR 71822). In the intervening period, nine additional comments had been received by the DEA, none of them raising issues of significance sufficient to justify a reconsideration of this 最终命令. These comments may be viewed at the DEA office, but will not be published.</p><h3 id="_45-fr-40576-june-16-1980" tabindex="-1">45 FR 40576 (June 16, 1980) <a class="header-anchor" href="#_45-fr-40576-june-16-1980" aria-label="Permalink to “45 FR 40576 (June 16, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-40576-june-16-1980" aria-label="Permalink to “45 FR 40576 (June 16, 1980)”">​</a></h3><p>Astatement of policy regarding the handling of drugs in long-term storage. No specific drugs are mentioned.</p><h3 id="_45-fr-42264-june-24-1980" tabindex="-1">45 FR 42264 (June 24, 1980) <a class="header-anchor" href="#_45-fr-42264-june-24-1980" aria-label="Permalink to “45 FR 42264 (June 24, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-42264-june-24-1980" aria-label="Permalink to “45 FR 42264 (June 24, 1980)”">​</a></h3><p>This is the final announcement for the placement of Dextropropoxyphene (Darvon) in 附表一 (Schedule I)V and for the classification of it (it is an Opiate), as a 麻醉药品 substance. This brings this drug under the provisions of the Narcotics Treatment Act of 1974, invoking additional regulations for its use in drug-dependent patients. The only drug allowed for such treatment, as of that time, was Methadone. These rules became effective on July 24, 1980.</p><h3 id="_45-fr-44266-july-1-1980" tabindex="-1">45 FR 44266 (July 1, 1980) <a class="header-anchor" href="#_45-fr-44266-july-1-1980" aria-label="Permalink to “45 FR 44266 (July 1, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-44266-july-1-1980" aria-label="Permalink to “45 FR 44266 (July 1, 1980)”">​</a></h3><p>A final statement of a regulation concerning recordkeeping. No drugs mentioned.</p><h3 id="_45-fr-48881-july-22-1980" tabindex="-1">45 FR 48881 (July 22, 1980) <a class="header-anchor" href="#_45-fr-48881-july-22-1980" aria-label="Permalink to “45 FR 48881 (July 22, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-48881-july-22-1980" aria-label="Permalink to “45 FR 48881 (July 22, 1980)”">​</a></h3><p>Bulk amounts of Dextropropoxyphene, when in nondosage amounts, are to be classified as 附表一 (Schedule I)I 麻醉药品 substance. This move is a response to the proposal made by the Commission on Narcotic Substances, speaking for the Single Convention, that Dextropropoxyphene should be classified as a 附表一 (Schedule I)I drug. The DEA had originally placed Dextropropoxyphene in 附表一 (Schedule I)V, where it still remains.</p><h3 id="_45-fr-49255-july-24-1980" tabindex="-1">45 FR 49255 (July 24, 1980) <a class="header-anchor" href="#_45-fr-49255-july-24-1980" aria-label="Permalink to “45 FR 49255 (July 24, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-49255-july-24-1980" aria-label="Permalink to “45 FR 49255 (July 24, 1980)”">​</a></h3><p>Thisisa notification of a public 行政听证会 concerning rulemaking on 麻醉药品s importation. (See 44 FR 33695 and 45 FR 9289 for prior notices).</p><h3 id="_45-fr-51832-august-5-1980" tabindex="-1">45 FR 51832 (August 5, 1980) <a class="header-anchor" href="#_45-fr-51832-august-5-1980" aria-label="Permalink to “45 FR 51832 (August 5, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-51832-august-5-1980" aria-label="Permalink to “45 FR 51832 (August 5, 1980)”">​</a></h3><p>An announcement from the DEA and three other divisions of the Justice Department deferring the publication of regulation agenda. No drugs: mentioned.</p><h3 id="_45-fr-52397-august-7-1980" tabindex="-1">45 FR 52397 (August 7, 1980) <a class="header-anchor" href="#_45-fr-52397-august-7-1980" aria-label="Permalink to “45 FR 52397 (August 7, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-52397-august-7-1980" aria-label="Permalink to “45 FR 52397 (August 7, 1980)”">​</a></h3><p>This is a semi-annual publication of the active agenda of regulations under consideration. There is a considerable discussion of the regulation proposals concerning Piperidine sale reporting (see 44 FR 12993).</p><h3 id="_45-fr-54329-august-15-1980" tabindex="-1">45 FR 54329 (August 15, 1980) <a class="header-anchor" href="#_45-fr-54329-august-15-1980" aria-label="Permalink to “45 FR 54329 (August 15, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-54329-august-15-1980" aria-label="Permalink to “45 FR 54329 (August 15, 1980)”">​</a></h3><p>This is the 最终行政裁决命令 on the proposed rule-making (see 45 FR 24199) concerning procedures for filling prescriptions for 附表一 (Schedule I)I substances.</p><h3 id="_45-fr-64570-september-30-1980" tabindex="-1">45 FR 64570 (September 30, 1980) <a class="header-anchor" href="#_45-fr-64570-september-30-1980" aria-label="Permalink to “45 FR 64570 (September 30, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-64570-september-30-1980" aria-label="Permalink to “45 FR 64570 (September 30, 1980)”">​</a></h3><p>This is the final notice placing Pipradrol and SPA into 附表一 (Schedule I)V in keeping with the obligations incurred by becoming, on April 15, 1980, a party to the Convention on Psychotropic Substances of 1971. The 正式生效日期 is December 1, 1980.</p><h3 id="_45-fr-64571-september-30-1980" tabindex="-1">45 FR 64571 (September 30, 1980) <a class="header-anchor" href="#_45-fr-64571-september-30-1980" aria-label="Permalink to “45 FR 64571 (September 30, 1980)”">​</a> <a class="header-anchor" href="#_45-fr-64571-september-30-1980" aria-label="Permalink to “45 FR 64571 (September 30, 1980)”">​</a></h3><p>This is the final notice for the placement of Sufentanil and Tilidine into 附表一 (Schedule I), in response to obligations incurred by being party to the Single Convention on Narcotic Drugs of 1961. As neither of these two drugs has currently accepted 医疗用途 in the United States, they are placed in 附表一 (Schedule I). The 正式生效日期 is December 1, 1980.</p><h3 id="_46-fr-943-january-5-1981" tabindex="-1">46 FR 943 (January 5, 1981) <a class="header-anchor" href="#_46-fr-943-january-5-1981" aria-label="Permalink to “46 FR 943 (January 5, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-943-january-5-1981" aria-label="Permalink to “46 FR 943 (January 5, 1981)”">​</a></h3><p>A proposal is made to place Temazepam within 附表一 (Schedule I)V. See 46 FR 20671 for 最终行政裁决命令.</p><h3 id="_46-fr-10105-january-30-1981" tabindex="-1">46 FR 10105 (January 30, 1981) <a class="header-anchor" href="#_46-fr-10105-january-30-1981" aria-label="Permalink to “46 FR 10105 (January 30, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-10105-january-30-1981" aria-label="Permalink to “46 FR 10105 (January 30, 1981)”">​</a></h3><p>A semi-annual listing of regulations under development or review.</p><h3 id="_46-fr-20671-april-7-1981" tabindex="-1">46 FR 20671 (April 7, 1981) <a class="header-anchor" href="#_46-fr-20671-april-7-1981" aria-label="Permalink to “46 FR 20671 (April 7, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-20671-april-7-1981" aria-label="Permalink to “46 FR 20671 (April 7, 1981)”">​</a></h3><p>This is the final notice of the placement of Temazepam into 附表一 (Schedule I)V. See 46 FR 943 for the 初步拟定规则提案.</p><h3 id="_46-fr-22393-april-17-1981" tabindex="-1">46 FR 22393 (April 17, 1981) <a class="header-anchor" href="#_46-fr-22393-april-17-1981" aria-label="Permalink to “46 FR 22393 (April 17, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-22393-april-17-1981" aria-label="Permalink to “46 FR 22393 (April 17, 1981)”">​</a></h3><p>A request that Mazindol be removed from scheduling control has been 被依法驳回 by the DEA, However, a proposal for the relocation of Mazindol from 附表一 (Schedule I)II to 附表一 (Schedule I)V is made here. See 46 FR 52333 for 最终行政裁决命令.</p><h3 id="_46-fr-23953-april-29-1981" tabindex="-1">46 FR 23953 (April 29, 1981) <a class="header-anchor" href="#_46-fr-23953-april-29-1981" aria-label="Permalink to “46 FR 23953 (April 29, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-23953-april-29-1981" aria-label="Permalink to “46 FR 23953 (April 29, 1981)”">​</a></h3><p>A proposal for the placement of Halazepam, Alprazolam, and Triazolam into 附表一 (Schedule I)V. The proposal for the scheduling of Halazopam was first made in 1976 (41 FR 31553) but never acted upon. See 46 FR 53407 for the 最终行政裁决命令 on Halazepam, 46 FR 55688 for the 最终行政裁决命令 on Alprazolam, and 47 FR 57693 for the 最终行政裁决命令 on Triazolam.</p><h3 id="_46-fr-24129-april-29-1981" tabindex="-1">46 FR 24129 (April 29, 1981) <a class="header-anchor" href="#_46-fr-24129-april-29-1981" aria-label="Permalink to “46 FR 24129 (April 29, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-24129-april-29-1981" aria-label="Permalink to “46 FR 24129 (April 29, 1981)”">​</a></h3><p>Thisisa semiannual summation of regulation proposals that are in process or being considered. The frequency of appearance of these summations is uneven; no more have been published from here to mid-1986.</p><h3 id="_46-fr-24593-may-1-1981" tabindex="-1">46 FR 24593 (May 1, 1981) <a class="header-anchor" href="#_46-fr-24593-may-1-1981" aria-label="Permalink to “46 FR 24593 (May 1, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-24593-may-1-1981" aria-label="Permalink to “46 FR 24593 (May 1, 1981)”">​</a></h3><p>A proposal is made to place Fenethylline into 附表一 (Schedule I). See 46 FR 37503 for 最终行政裁决命令.</p><h3 id="_46-fr-28840-may-29-1981" tabindex="-1">46 FR 28840 (May 29, 1981) <a class="header-anchor" href="#_46-fr-28840-may-29-1981" aria-label="Permalink to “46 FR 28840 (May 29, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-28840-may-29-1981" aria-label="Permalink to “46 FR 28840 (May 29, 1981)”">​</a></h3><p>Anumber of internal title changes within the Administration required rewording of several regulations. No drugs are mentioned.</p><h3 id="_46-fr-29484-june-2-1981" tabindex="-1">46 FR 29484 (June 2, 1981) <a class="header-anchor" href="#_46-fr-29484-june-2-1981" aria-label="Permalink to “46 FR 29484 (June 2, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-29484-june-2-1981" aria-label="Permalink to “46 FR 29484 (June 2, 1981)”">​</a></h3><p>A proposal is made recommending the placement of Ketamine into 附表一 (Schedule I)II. It is interesting that the department of Human Health Services has identified Ketamine as a 致幻性 drug, and has recommended that it be scheduled. In this notice, the DEA acknowledges that the misuse of it can result in amnesia, excitement, bizarre behavior, hallucinations and delirium. But for the purposes of this recommendation, Ketamine is classified as a 中枢抑制剂. This may be a reflection of the consistent pattern of classifying hallucinogens as 附表一 (Schedule I) substances. See 46 FR 60008 for the dropping of the scheduling proposal for Tiletamine, also a hallucinogen. This proposal for the scheduling of Ketamine has never been followed up, and presumably rests unacted upon as of April 1, 1988</p><h3 id="_46-fr-35529-july-9-1981" tabindex="-1">46 FR 35529 (July 9, 1981) <a class="header-anchor" href="#_46-fr-35529-july-9-1981" aria-label="Permalink to “46 FR 35529 (July 9, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-35529-july-9-1981" aria-label="Permalink to “46 FR 35529 (July 9, 1981)”">​</a></h3><p>This is a proposal for the placement of Tiletamine and Zolazepam into 附表一 (Schedule I) of the CSA, and mixtures containing equal amounts of these two drugs into 附表一 (Schedule I)II. This combination is known as Telazol, and is intended to be used in veterinary medicine. Tiletamine, as an analog of Phencyclidine (PCP) has properties similar to it, so it is deemed to have a high 滥用潜能, no currently accepted 医疗用途, and the lack of accepted safety; hence it is to be placed in 附表一 (Schedule I). Zolazepam is chemically related to Chlordiazepoxide and Diazepam, but being more toxic, and lacking human trials, is felt to meet the above criteria presented for Tiletamine, and hence be appropriately placed in 附表一 (Schedule I) as well. The mixture, Telazol, was found to have positive reinforcing properties in monkey studies followed by mild to moderate withdrawal symptoms. These properties suggested that there might be the generation of psychological dependence in man. Nonetheless it was decided that the potential for abuse was less than that requiring 附表一 (Schedule I) or II placement, and recommended 附表一 (Schedule I)II placement. This proposal was withdrawn, see 46 FR 60008.</p><h3 id="_46-fr-37503-july-21-1981" tabindex="-1">46 FR 37503 (July 21, 1981) <a class="header-anchor" href="#_46-fr-37503-july-21-1981" aria-label="Permalink to “46 FR 37503 (July 21, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-37503-july-21-1981" aria-label="Permalink to “46 FR 37503 (July 21, 1981)”">​</a></h3><p>Final notice of Fenethylline being 正式列入 附表一 (Schedule I), effective August 20, 1981. See 46 FR 24593 for the original proposal.</p><h3 id="_46-fr-39848-august-5-1981" tabindex="-1">46 FR 39848 (August 5, 1981) <a class="header-anchor" href="#_46-fr-39848-august-5-1981" aria-label="Permalink to “46 FR 39848 (August 5, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-39848-august-5-1981" aria-label="Permalink to “46 FR 39848 (August 5, 1981)”">​</a></h3><p>A proposal is presented to place alpha-Methy] Fentanyl into 附表一 (Schedule I). For the 最终行政裁决命令 see 46 FR 46799.</p><h3 id="_46-fr-41775-august-18-1981" tabindex="-1">46 FR 41775 (August 18, 1981) <a class="header-anchor" href="#_46-fr-41775-august-18-1981" aria-label="Permalink to “46 FR 41775 (August 18, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-41775-august-18-1981" aria-label="Permalink to “46 FR 41775 (August 18, 1981)”">​</a></h3><p>An amendment to internal regulations concerning the importation of 麻醉药品 raw material. At least 80% of the allowed importation of Opium and related material must come from Turkey and India.</p><h3 id="_46-fr-42285-august-20-1981" tabindex="-1">46 FR 42285 (August 20, 1981) <a class="header-anchor" href="#_46-fr-42285-august-20-1981" aria-label="Permalink to “46 FR 42285 (August 20, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-42285-august-20-1981" aria-label="Permalink to “46 FR 42285 (August 20, 1981)”">​</a></h3><p>A typographical correction to be made in 46 FR 39848.</p><h3 id="_46-fr-45156-september-10-1981" tabindex="-1">46 FR 45156 (September 10, 1981) <a class="header-anchor" href="#_46-fr-45156-september-10-1981" aria-label="Permalink to “46 FR 45156 (September 10, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-45156-september-10-1981" aria-label="Permalink to “46 FR 45156 (September 10, 1981)”">​</a></h3><p>A proposal for placing N- Ethyl Amphetamine into 附表一 (Schedule I). For 最终行政裁决命令, see 46 FR 59969.</p><h3 id="_46-fr-46799-september-22-1981" tabindex="-1">46 FR 46799 (September 22, 1981) <a class="header-anchor" href="#_46-fr-46799-september-22-1981" aria-label="Permalink to “46 FR 46799 (September 22, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-46799-september-22-1981" aria-label="Permalink to “46 FR 46799 (September 22, 1981)”">​</a></h3><p>This is the final notice for the placement of alpha-Methyl Fentanyl in 附表一 (Schedule I). Several comments had been received concerning this proposed scheduling, largely directed to the nomenclature that had been used and as to the reasons that this particular analog was selected for scheduling. No 行政听证会s were requested, and this notice is the 最终行政裁决命令. See 46 FR 39848 for the 初步拟定规则提案.</p><h3 id="_46-fr-48918-october-5-1981" tabindex="-1">46 FR 48918 (October 5, 1981) <a class="header-anchor" href="#_46-fr-48918-october-5-1981" aria-label="Permalink to “46 FR 48918 (October 5, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-48918-october-5-1981" aria-label="Permalink to “46 FR 48918 (October 5, 1981)”">​</a></h3><p>The 最终行政裁决命令 on the prescription information exchange (see 45 FR 21652).</p><h3 id="_46-fr-50063-october-9-1981" tabindex="-1">46 FR 50063 (October 9, 1981) <a class="header-anchor" href="#_46-fr-50063-october-9-1981" aria-label="Permalink to “46 FR 50063 (October 9, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-50063-october-9-1981" aria-label="Permalink to “46 FR 50063 (October 9, 1981)”">​</a></h3><p>A minor typographical change in the Code of Federal Regulations.</p><h3 id="_46-fr-52333-october-27-1981" tabindex="-1">46 FR 52333 (October 27, 1981) <a class="header-anchor" href="#_46-fr-52333-october-27-1981" aria-label="Permalink to “46 FR 52333 (October 27, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-52333-october-27-1981" aria-label="Permalink to “46 FR 52333 (October 27, 1981)”">​</a></h3><p>This is the final notice for the rescheduling of Mazindol into 附表一 (Schedule I)V from 附表一 (Schedule I)II, effective November 27, 1981. For the 初步拟定规则提案 and the rejection of the requested 取消管制/去列管, see 46 FR 22393.</p><h3 id="_46-fr-53407-october-29-1981" tabindex="-1">46 FR 53407 (October 29, 1981) <a class="header-anchor" href="#_46-fr-53407-october-29-1981" aria-label="Permalink to “46 FR 53407 (October 29, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-53407-october-29-1981" aria-label="Permalink to “46 FR 53407 (October 29, 1981)”">​</a></h3><p>Final notice for the placement of Halazepam into 附表一 (Schedule I)V. For the 初步拟定规则提案, see 46 FR 23953.</p><h3 id="_46-fr-55688-november-12-1981" tabindex="-1">46 FR 55688 (November 12, 1981) <a class="header-anchor" href="#_46-fr-55688-november-12-1981" aria-label="Permalink to “46 FR 55688 (November 12, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-55688-november-12-1981" aria-label="Permalink to “46 FR 55688 (November 12, 1981)”">​</a></h3><p>Final notice for the placement of Alprazolam into 附表一 (Schedule I)V. See 46 FR 23953 for the original proposal.</p><h3 id="_46-fr-59969-december-8-1981" tabindex="-1">46 FR 59969 (December 8, 1981) <a class="header-anchor" href="#_46-fr-59969-december-8-1981" aria-label="Permalink to “46 FR 59969 (December 8, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-59969-december-8-1981" aria-label="Permalink to “46 FR 59969 (December 8, 1981)”">​</a></h3><p>Final action on the placement of N-Ethylamphetamine into schedule I. See 46 FR 45156 for the 初步拟定规则提案.</p><h3 id="_46-fr-60008-december-8-1981" tabindex="-1">46 FR 60008 (December 8, 1981) <a class="header-anchor" href="#_46-fr-60008-december-8-1981" aria-label="Permalink to “46 FR 60008 (December 8, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-60008-december-8-1981" aria-label="Permalink to “46 FR 60008 (December 8, 1981)”">​</a></h3><p>Comments were received from the manufacturer of Telazol concerning objections to the proposed scheduling of Tiletamine and Zolazepam in 附表一 (Schedule I) and the combination (Telazol) in 附表一 (Schedule I)II (see 46 FR 35529). The components of the mixture were claimed to be 化学前体s, and as such should not be placed in a schedule any more restrictive than the combination. And it was felt that the combination product warranted a 附表一 (Schedule I)V placement. The DEA accepted the component-化学前体 discussion and withdrew the request for 附表一 (Schedule I) placement for Tiletamine and for Zolazepam. They reaffirmed the correctness of 附表一 (Schedule I)II for the mixture, however, and apparently no further objections were voiced. However, the proposal to place the mixture, under the name Telazol, as well as the component “化学前体s” into 附表一 (Schedule I)II was reasserted.</p><h3 id="_46-fr-60572-december-11-1981" tabindex="-1">46 FR 60572 (December 11, 1981) <a class="header-anchor" href="#_46-fr-60572-december-11-1981" aria-label="Permalink to “46 FR 60572 (December 11, 1981)”">​</a> <a class="header-anchor" href="#_46-fr-60572-december-11-1981" aria-label="Permalink to “46 FR 60572 (December 11, 1981)”">​</a></h3><p>A typographical correction to 46 FR 60008. The 正式生效日期 for the scheduling of N-Ethylamphetamine is January 7, 1982.</p><h3 id="_47-fr6888-february-17-1982" tabindex="-1">47 FR6888 (February 17, 1982) <a class="header-anchor" href="#_47-fr6888-february-17-1982" aria-label="Permalink to “47 FR6888 (February 17, 1982)”">​</a> <a class="header-anchor" href="#_47-fr6888-february-17-1982" aria-label="Permalink to “47 FR6888 (February 17, 1982)”">​</a></h3><p>A listing is made of exempted 中枢兴奋剂 and 中枢抑制剂 controlled drugs which are marketed in combinations that lessens the potential for abuse.</p><h3 id="_47-fr-10080-march-9-1982" tabindex="-1">47 FR 10080 (March 9, 1982) <a class="header-anchor" href="#_47-fr-10080-march-9-1982" aria-label="Permalink to “47 FR 10080 (March 9, 1982)”">​</a> <a class="header-anchor" href="#_47-fr-10080-march-9-1982" aria-label="Permalink to “47 FR 10080 (March 9, 1982)”">​</a></h3><p>A lengthy notice from the FDA concerning their proposed recommendations to the DEA about the rescheduling of THC to 附表一 (Schedule I)I for use in cancer treatment. Included is a discussion of its 滥用潜能 (including current patterns of abuse and risks to public health), evidence for its pharmacological effects, the state ofcurrent scientific knowledge, and its dependence liability.</p><h3 id="_47-fr-26616-june-21-1982" tabindex="-1">47 FR 26616 (June 21, 1982) <a class="header-anchor" href="#_47-fr-26616-june-21-1982" aria-label="Permalink to “47 FR 26616 (June 21, 1982)”">​</a> <a class="header-anchor" href="#_47-fr-26616-june-21-1982" aria-label="Permalink to “47 FR 26616 (June 21, 1982)”">​</a></h3><p>Thisisa notification that corrects a typographic error (in 46 FR 52333) in the transferring of Mazindol from 附表一 (Schedule I)II to 附表一 (Schedule I)V. Pipradrol and SPA were inadvertently deleted.</p><h3 id="_47-fr-32549-july-28-1982" tabindex="-1">47 FR 32549 (July 28, 1982) <a class="header-anchor" href="#_47-fr-32549-july-28-1982" aria-label="Permalink to “47 FR 32549 (July 28, 1982)”">​</a> <a class="header-anchor" href="#_47-fr-32549-july-28-1982" aria-label="Permalink to “47 FR 32549 (July 28, 1982)”">​</a></h3><p>A proposal is presented for the decontrolling of Loperamide (currently 附表五 (Schedule V), by action of 41 FR 31551). This was initialed by the Ortho Pharmaceutical Corporation in a letter to the HHS who evaluated the 行政请愿申请 and found that there were insufficient indicators of abuse to justify continued scheduling. It will remain a prescription drug, and there will be continued monitoring of potential abuse by the DEA for three years.</p><h3 id="_47-fr-33986-august-5-1982" tabindex="-1">47 FR 33986 (August 5, 1982) <a class="header-anchor" href="#_47-fr-33986-august-5-1982" aria-label="Permalink to “47 FR 33986 (August 5, 1982)”">​</a> <a class="header-anchor" href="#_47-fr-33986-august-5-1982" aria-label="Permalink to “47 FR 33986 (August 5, 1982)”">​</a></h3><p>A proposal is made, soliciting comments, for the placement of Parahexyl into 附表一 (Schedule I). This follows a recommendation from the Secretary of Health so that the United States will stay in compliance with its obligations under the Convention on Psychotropic Substances 1971. The three criteria for the justification of 附表一 (Schedule I) (high 滥用潜能, no medical utility, and absence of accepted safety in use) are included in this letter, and are deemed sufficient for scheduling. As this action effectively brings back to public attention a drug that has been effectively unknown in the United States since 1947, the summary of the FDA finding, that was contained in the letter, can be instructive: A: The drug_or other substance has a high potential for abuse. — Parahexyl has a potential for abuse similar to trans- delta-9Tetrahydrocannibinol. Therefore, Parahexyl has a high potential for abuse. B: The drug or substance has no current] 医疗用途 in treatment in th United States, — There are no approved or pending NDAs, NADAs or active INDs for Parahexyl. Therefore the FDA does not recognize an accepted 医疗用途 for this substance. C: There is a lack of for he u f rug or other substance under medical supervision. — Human exposure to Parahexyl has been too limited to demonstrate safety for this substance. The letter then goes on to say that Parahexyl meets the criteria for control under 附表一 (Schedule I) of the CSA. These are the criteria that are to be applied to all of the drugs proposed for scheduling in compliance with this international treaty. For 最终行政裁决命令, see 47 FR 52432.</p><h3 id="_47-fr-41140-september-17-1982" tabindex="-1">47 FR 41140 (September 17 1982) <a class="header-anchor" href="#_47-fr-41140-september-17-1982" aria-label="Permalink to “47 FR 41140 (September 17 1982)”">​</a> <a class="header-anchor" href="#_47-fr-41140-september-17-1982" aria-label="Permalink to “47 FR 41140 (September 17 1982)”">​</a></h3><p>A proposal is made for the relaxation of the dispensing of controlled substances under certain emergency room situations. The period allowed for receiving comments was extended (see 47 FR 53038). This proposal was withdrawn, see 48 FR 29713.</p><h3 id="_47-fr-41401-september-20-1982" tabindex="-1">47 FR 41401 (September 20, 1982) <a class="header-anchor" href="#_47-fr-41401-september-20-1982" aria-label="Permalink to “47 FR 41401 (September 20, 1982)”">​</a> <a class="header-anchor" href="#_47-fr-41401-september-20-1982" aria-label="Permalink to “47 FR 41401 (September 20, 1982)”">​</a></h3><p>This is a proposal for the relocation of Buprenorphine to 附表五 (Schedule V) from 附表一 (Schedule I)I. It was never explicitly listed in II, but as it is a derivative of Thebaine (a 附表一 (Schedule I)I drug) it falls automatically in that category. Hearings were held (see 48 FR 19037) and 最终行政裁决命令 taken (see 50 FR 8104).</p><h3 id="_47-fr-41735-september-22-1982" tabindex="-1">47 FR 41735 (September 22, 1982) <a class="header-anchor" href="#_47-fr-41735-september-22-1982" aria-label="Permalink to “47 FR 41735 (September 22, 1982)”">​</a> <a class="header-anchor" href="#_47-fr-41735-september-22-1982" aria-label="Permalink to “47 FR 41735 (September 22, 1982)”">​</a></h3><p>An internal reassignment of titles (of officials) has been listed for eventual changes in the printing of Title 21 of the CFR. No drugs are mentioned.</p><h3 id="_47-fr-43370-october-1-1982" tabindex="-1">47 FR 43370 (October 1, 1982) <a class="header-anchor" href="#_47-fr-43370-october-1-1982" aria-label="Permalink to “47 FR 43370 (October 1, 1982)”">​</a> <a class="header-anchor" href="#_47-fr-43370-october-1-1982" aria-label="Permalink to “47 FR 43370 (October 1, 1982)”">​</a></h3><p>This is an amendment coauthored by the DEA and the FBI. There is a statement of several internal regulations that delegates authority in certain questions of seizure and taking custody of property in connections with drug offences.</p><h3 id="_47-fr-49840-november-3-1982" tabindex="-1">47 FR 49840 (November 3, 1982) <a class="header-anchor" href="#_47-fr-49840-november-3-1982" aria-label="Permalink to “47 FR 49840 (November 3, 1982)”">​</a> <a class="header-anchor" href="#_47-fr-49840-november-3-1982" aria-label="Permalink to “47 FR 49840 (November 3, 1982)”">​</a></h3><p>Final announcement and 正式生效日期 for the decontrolling of Loperamide. See 47 FR 32549 for the 初步拟定规则提案 and arguments.</p><h3 id="_47-fr-52432-november-22-1982" tabindex="-1">47 FR 52432 (November 22, 1982) <a class="header-anchor" href="#_47-fr-52432-november-22-1982" aria-label="Permalink to “47 FR 52432 (November 22, 1982)”">​</a> <a class="header-anchor" href="#_47-fr-52432-november-22-1982" aria-label="Permalink to “47 FR 52432 (November 22, 1982)”">​</a></h3><p>This is the final announcement for the placement of Parahexyl into 附表一 (Schedule I), effective December 22, 1982. See 47 FR 33986 for the 初步拟定规则提案, and details concerning this action.</p><h3 id="_47-fr-53038-november-24-1982" tabindex="-1">47 FR 53038 (November 24, 1982) <a class="header-anchor" href="#_47-fr-53038-november-24-1982" aria-label="Permalink to “47 FR 53038 (November 24, 1982)”">​</a> <a class="header-anchor" href="#_47-fr-53038-november-24-1982" aria-label="Permalink to “47 FR 53038 (November 24, 1982)”">​</a></h3><p>An extension of time is allowed for the receipt of comments concerning the dispensing of controlled substances under certain medical emergency situations. See 47 FR 41140 for the original proposal.</p><h3 id="_47-fr-57693-december-28-1982" tabindex="-1">47 FR 57693 (December 28, 1982) <a class="header-anchor" href="#_47-fr-57693-december-28-1982" aria-label="Permalink to “47 FR 57693 (December 28, 1982)”">​</a> <a class="header-anchor" href="#_47-fr-57693-december-28-1982" aria-label="Permalink to “47 FR 57693 (December 28, 1982)”">​</a></h3><p>Final announcement and 正式生效日期 for the placement of Triazolam into 附表一 (Schedule I)V. See 46 FR 23953 for the 初步拟定规则提案.</p><h3 id="_48-fr-14640-april-5-1983" tabindex="-1">48 FR 14640 (April 5, 1983) <a class="header-anchor" href="#_48-fr-14640-april-5-1983" aria-label="Permalink to “48 FR 14640 (April 5, 1983)”">​</a> <a class="header-anchor" href="#_48-fr-14640-april-5-1983" aria-label="Permalink to “48 FR 14640 (April 5, 1983)”">​</a></h3><p>Proposal for the increase of the annual fees for several licences issued by the DEA. See 48 FR 56043 for final notice.</p><h3 id="_48-fr-19037-april-27-1983" tabindex="-1">48 FR 19037 (April 27, 1983) <a class="header-anchor" href="#_48-fr-19037-april-27-1983" aria-label="Permalink to “48 FR 19037 (April 27, 1983)”">​</a> <a class="header-anchor" href="#_48-fr-19037-april-27-1983" aria-label="Permalink to “48 FR 19037 (April 27, 1983)”">​</a></h3><p>The proposal for transferring Buprenorphine from 附表一 (Schedule I)I to 附表五 (Schedule V) (see 47 FR 41401). Comments were received, and 行政听证会s are to be held. See 50 FR 8104 for 最终行政裁决命令.</p><h3 id="_48-fr-29713-june-28-1983" tabindex="-1">48 FR 29713 (June 28, 1983) <a class="header-anchor" href="#_48-fr-29713-june-28-1983" aria-label="Permalink to “48 FR 29713 (June 28, 1983)”">​</a> <a class="header-anchor" href="#_48-fr-29713-june-28-1983" aria-label="Permalink to “48 FR 29713 (June 28, 1983)”">​</a></h3><p>A proposal (see 47 FR 41140) to allow emergency room personnel to dispense controlled drugs when alternate services are unavailable, has been withdrawn.</p><h3 id="_48-fr-35087-august-3-1983" tabindex="-1">48 FR 35087 (August 3, 1983) <a class="header-anchor" href="#_48-fr-35087-august-3-1983" aria-label="Permalink to “48 FR 35087 (August 3, 1983)”">​</a> <a class="header-anchor" href="#_48-fr-35087-august-3-1983" aria-label="Permalink to “48 FR 35087 (August 3, 1983)”">​</a></h3><p>This is a joint notification from the DEA and the FBI concerning the delegation of authority on material forfeited. No specific drugs are mentioned.</p><h3 id="_48-fr-41096-september-13-1983" tabindex="-1">48 FR 41096 (September 13, 1983) <a class="header-anchor" href="#_48-fr-41096-september-13-1983" aria-label="Permalink to “48 FR 41096 (September 13, 1983)”">​</a> <a class="header-anchor" href="#_48-fr-41096-september-13-1983" aria-label="Permalink to “48 FR 41096 (September 13, 1983)”">​</a></h3><p>A notice soliciting information on some 30 drugs has been received from the World Health Organization, and this has been presented by the FDA.</p><h3 id="_48-fr-51329-november-8-1983" tabindex="-1">48 FR 51329 (November 8, 1983) <a class="header-anchor" href="#_48-fr-51329-november-8-1983" aria-label="Permalink to “48 FR 51329 (November 8, 1983)”">​</a> <a class="header-anchor" href="#_48-fr-51329-november-8-1983" aria-label="Permalink to “48 FR 51329 (November 8, 1983)”">​</a></h3><p>This is a proposal for modification of the reporting procedures for manufacturers of drugs that are controlled substances under the Single Convention on Narcotic Drugs of 1961, the Psychotropic Convention of 1971, and the Psychotropic Substances Act of 1978. All 麻醉药品 controlled substances in Schedules III, IV and V, and the psychotropic controlled substances in Schedules III and IV, that are to be reported upon, are specifically listed. Cyclobarbital (II) is specifically listed, although it may or may not be controlled under the CSA (see the discussion under Barbituric Acid, in the section on definitions).</p><h3 id="_48-fr-56043-december-19-1983" tabindex="-1">48 FR 56043 (December 19, 1983) <a class="header-anchor" href="#_48-fr-56043-december-19-1983" aria-label="Permalink to “48 FR 56043 (December 19, 1983)”">​</a> <a class="header-anchor" href="#_48-fr-56043-december-19-1983" aria-label="Permalink to “48 FR 56043 (December 19, 1983)”">​</a></h3><p>The announcement of a new fee schedule for various registration licences. See 48 FR 14640 for the 初步拟定规则提案.</p><h3 id="_49fr1178-january-10-1984" tabindex="-1">49FR1178 (January 10, 1984) <a class="header-anchor" href="#_49fr1178-january-10-1984" aria-label="Permalink to “49FR1178 (January 10, 1984)”">​</a> <a class="header-anchor" href="#_49fr1178-january-10-1984" aria-label="Permalink to “49FR1178 (January 10, 1984)”">​</a></h3><p>The approval of an Asset Forfeiture Unit within the DEA to facilitate the processing of various aspects of forfeiture that come under the authority of the DEA.</p><h3 id="_49-fr-10274-march-20-1984" tabindex="-1">49 FR 10274 (March 20, 1984) <a class="header-anchor" href="#_49-fr-10274-march-20-1984" aria-label="Permalink to “49 FR 10274 (March 20, 1984)”">​</a> <a class="header-anchor" href="#_49-fr-10274-march-20-1984" aria-label="Permalink to “49 FR 10274 (March 20, 1984)”">​</a></h3><p>A proposal for the relocation of Sufentalin from 附表一 (Schedule I) to 附表一 (Schedule I)I in anticipation of the issuance of a NDA from the FDA.</p><h3 id="_49-fr-22074-may-25-1984" tabindex="-1">49 FR 22074 (May 25, 1984) <a class="header-anchor" href="#_49-fr-22074-may-25-1984" aria-label="Permalink to “49 FR 22074 (May 25, 1984)”">​</a> <a class="header-anchor" href="#_49-fr-22074-may-25-1984" aria-label="Permalink to “49 FR 22074 (May 25, 1984)”">​</a></h3><p>Final announcement and 正式生效日期 for the reclassification of Sufentanil from 附表一 (Schedule I) to 附表一 (Schedule I)I.</p><h3 id="_49-fr-25849-june-25-1984" tabindex="-1">49 FR 25849 (June 25, 1984) <a class="header-anchor" href="#_49-fr-25849-june-25-1984" aria-label="Permalink to “49 FR 25849 (June 25, 1984)”">​</a> <a class="header-anchor" href="#_49-fr-25849-june-25-1984" aria-label="Permalink to “49 FR 25849 (June 25, 1984)”">​</a></h3><p>Final notification for the placement of Alfentanil into 附表一 (Schedule I), effective 8/24/84. This action was taken in response to the advice to the U.S. Secretary of State from the Commission on Narcotics of the United Nations. The U.S. obligations (it is here stated), as a party to the Single Convention on Narcotics Drugs of 1961, require it to control a drug so recommended, and in a schedule that it deems most appropriate. This decision has been delegated to the Administrator of the DEA by regulations of the Department of Justice (see 28 CFR 0.100). There is no currently accepted 医疗用途 of Alfentanil, and no other findings apparently need be made. There is no mention of abuse’ potential of any degree in this notice. The 正式生效日期 is August 24, 1984. See 49 FR 32064 for a correction of a technical omission.</p><h3 id="_49-fr-28700-july-16-1984" tabindex="-1">49 FR 28700 (July 16, 1984) <a class="header-anchor" href="#_49-fr-28700-july-16-1984" aria-label="Permalink to “49 FR 28700 (July 16, 1984)”">​</a> <a class="header-anchor" href="#_49-fr-28700-july-16-1984" aria-label="Permalink to “49 FR 28700 (July 16, 1984)”">​</a></h3><p>Thisisa regulatory delegation of authority to the resident DEA agents to have custody of properties seized and to declare it adminisiratively forfeited. See 49 FR 32174 for regulations that permit official use of such property.</p><h3 id="_49-fr-29273-july-19-1984" tabindex="-1">49 FR 29273 (July 19, 1984) <a class="header-anchor" href="#_49-fr-29273-july-19-1984" aria-label="Permalink to “49 FR 29273 (July 19, 1984)”">​</a> <a class="header-anchor" href="#_49-fr-29273-july-19-1984" aria-label="Permalink to “49 FR 29273 (July 19, 1984)”">​</a></h3><p>A request made by the FDA for information concerning 医疗用途 or 滥用潜能 of some 28 中枢兴奋剂s and/or hallucinogens. The WHO is considering them for eventual international restriction. Some of these are already scheduled substances in the United States. There had been an earlier request for 30 drugs (48 FR 41096) which contains these specific drugs and two in addition; vis., Methoxymethylenedioxyamphetamine and para-Oxyamphetamine. 49 FR 30210 (July, 27, 1984) This is the 初步拟定规则提案 for the placement of MDMA into 附表一 (Schedule I). Several requests for 行政听证会s were received, and the actual act of scheduling was deferred. It was subsequently placed in 附表一 (Schedule I) as a temporary measure by the invocation of the Emergency Scheduling Powers act.</p><h3 id="_49-fr-30748-august-1-1984" tabindex="-1">49 FR 30748 (August 1, 1984) <a class="header-anchor" href="#_49-fr-30748-august-1-1984" aria-label="Permalink to “49 FR 30748 (August 1, 1984)”">​</a> <a class="header-anchor" href="#_49-fr-30748-august-1-1984" aria-label="Permalink to “49 FR 30748 (August 1, 1984)”">​</a></h3><p>This is a proposal for the introduction of some 21 Benzodiazepine derivatives into 附表一 (Schedule I)V. This was in accord with the obligations of the United States under the Convention on Psychotropic Substances of 1971. None of these has any legitimate 医疗用途 in the United States, but no mention has been made as to their 滥用潜能. See 49 FR 39307 for 最终行政裁决命令.</p><h3 id="_49-fr-32064-august-10-1984" tabindex="-1">49 FR 32064 (August 10, 1984) <a class="header-anchor" href="#_49-fr-32064-august-10-1984" aria-label="Permalink to “49 FR 32064 (August 10, 1984)”">​</a> <a class="header-anchor" href="#_49-fr-32064-august-10-1984" aria-label="Permalink to “49 FR 32064 (August 10, 1984)”">​</a></h3><p>This is the correction of a technical omission in the notice for the placement of Alfentanil in 附表一 (Schedule I), see 49 FR 25849.</p><h3 id="_49-fr-32174-augusi-13-1984" tabindex="-1">49 FR 32174 (Augusi 13, 1984) <a class="header-anchor" href="#_49-fr-32174-augusi-13-1984" aria-label="Permalink to “49 FR 32174 (Augusi 13, 1984)”">​</a> <a class="header-anchor" href="#_49-fr-32174-augusi-13-1984" aria-label="Permalink to “49 FR 32174 (Augusi 13, 1984)”">​</a></h3><p>This is an administrative regulation allowing the DEA to make official use of property seized in connection with court-ordered forfeiture. See 49 FR 28700 for the delegation of authority to DEA officials for the custodial aspects of this regulation.</p><h3 id="_49-fr-33870-august-27-1984" tabindex="-1">49 FR 33870 (August 27, 1984) <a class="header-anchor" href="#_49-fr-33870-august-27-1984" aria-label="Permalink to “49 FR 33870 (August 27, 1984)”">​</a> <a class="header-anchor" href="#_49-fr-33870-august-27-1984" aria-label="Permalink to “49 FR 33870 (August 27, 1984)”">​</a></h3><p>The final notice and 正式生效日期 for the rescheduling of Methaqualone from 附表一 (Schedule I)I to 附表一 (Schedule I). This action was required in order to comply with Public Law 98-329, an Act which called for this rescheduling as well as the withdrawal of the approved NDA forms that had been issued for Methaqualone. For a typographical correction to this notice, see 49 FR 34451.</p><h3 id="_49-fr-34451-august-31-1984" tabindex="-1">49 FR 34451 (August 31, 1984) <a class="header-anchor" href="#_49-fr-34451-august-31-1984" aria-label="Permalink to “49 FR 34451 (August 31, 1984)”">​</a> <a class="header-anchor" href="#_49-fr-34451-august-31-1984" aria-label="Permalink to “49 FR 34451 (August 31, 1984)”">​</a></h3><p>This is a typographical correction to the notice for the relocation of Methaqualone from 附表一 (Schedule I)I to 附表一 (Schedule I), see 49 FR 33870.</p><h3 id="_49-fr-37059-september-21-1984" tabindex="-1">49 FR 37059 (September 21, 1984) <a class="header-anchor" href="#_49-fr-37059-september-21-1984" aria-label="Permalink to “49 FR 37059 (September 21, 1984)”">​</a> <a class="header-anchor" href="#_49-fr-37059-september-21-1984" aria-label="Permalink to “49 FR 37059 (September 21, 1984)”">​</a></h3><p>A change in registrant requirements for the reporting of drugs in various schedules in various legal systems, including the Psychotropic Convention of 1971 and the Single Convention on Narcotic Drugs of 1961.</p><h3 id="_49-fr-39307-october-5-1984" tabindex="-1">49 FR 39307 (October 5, 1984) <a class="header-anchor" href="#_49-fr-39307-october-5-1984" aria-label="Permalink to “49 FR 39307 (October 5, 1984)”">​</a> <a class="header-anchor" href="#_49-fr-39307-october-5-1984" aria-label="Permalink to “49 FR 39307 (October 5, 1984)”">​</a></h3><p>Atotal of 21 substituted Benzodiazepines were entered into 附表一 (Schedule I)V, effective November 5, 1984. This is a 临时暂行管制 which shall “remain in effect until the process of permanent scheduling — is completed.” Each drug has been entered into the alphabetical listing section of this manual under its own name. See 49 FR30748 for the 初步拟定规则提案.</p><h3 id="_49-fr-41246-october-22-1984" tabindex="-1">49 FR 41246 (October 22, 1984) <a class="header-anchor" href="#_49-fr-41246-october-22-1984" aria-label="Permalink to “49 FR 41246 (October 22, 1984)”">​</a> <a class="header-anchor" href="#_49-fr-41246-october-22-1984" aria-label="Permalink to “49 FR 41246 (October 22, 1984)”">​</a></h3><p>This is an internal regulation concerning the legal aspects of employee claims. No drugs are mentioned.</p><h3 id="_49-fr-43530-october-29-1984" tabindex="-1">49 FR 43530 (October 29, 1984) <a class="header-anchor" href="#_49-fr-43530-october-29-1984" aria-label="Permalink to “49 FR 43530 (October 29, 1984)”">​</a> <a class="header-anchor" href="#_49-fr-43530-october-29-1984" aria-label="Permalink to “49 FR 43530 (October 29, 1984)”">​</a></h3><p>An announcement from the FDA as to modification of rules pertaining to “good laboratory” practices (GLPs) for non-clinical studies. No mention of scheduled drugs.</p><h3 id="_49-fr-50642-december-31-1984" tabindex="-1">49 FR 50642 (December 31, 1984) <a class="header-anchor" href="#_49-fr-50642-december-31-1984" aria-label="Permalink to “49 FR 50642 (December 31, 1984)”">​</a> <a class="header-anchor" href="#_49-fr-50642-december-31-1984" aria-label="Permalink to “49 FR 50642 (December 31, 1984)”">​</a></h3><p>This is a joint DEA and FBI statement of regulatory amendments concerning forfeiture procedures.</p><h3 id="_49-fr-50732-december-31-1984" tabindex="-1">49 FR 50732 (December 31, 1984) <a class="header-anchor" href="#_49-fr-50732-december-31-1984" aria-label="Permalink to “49 FR 50732 (December 31, 1984)”">​</a> <a class="header-anchor" href="#_49-fr-50732-december-31-1984" aria-label="Permalink to “49 FR 50732 (December 31, 1984)”">​</a></h3><p>The proposed scheduling of MDMA as a 附表一 (Schedule I) drug (see 49 FR 30210) resulted in the receipt of sixteen comments and seven requests for 行政听证会s. This notice is an announcement that there will be 行政听证会s held to help determine the appropriate schedule for MDMA.</p><h2 id="_1985-—-1989-年-紧急列管权行使、设计药物狂潮与-mdma-听证" tabindex="-1">1985 — 1989 年：紧急列管权行使、设计药物狂潮与 MDMA 听证 <a class="header-anchor" href="#_1985-—-1989-年-紧急列管权行使、设计药物狂潮与-mdma-听证" aria-label="Permalink to “1985 — 1989 年：紧急列管权行使、设计药物狂潮与 MDMA 听证”">​</a> <a class="header-anchor" href="#_1985-—-1989-年-紧急列管权行使、设计药物狂潮与-mdma-听证" aria-label="Permalink to “1985 — 1989 年：紧急列管权行使、设计药物狂潮与 MDMA 听证”">​</a></h2><h3 id="_50-fr-2046-january-15-1985" tabindex="-1">50 FR 2046 (January 15, 1985) <a class="header-anchor" href="#_50-fr-2046-january-15-1985" aria-label="Permalink to “50 FR 2046 (January 15, 1985)”">​</a> <a class="header-anchor" href="#_50-fr-2046-january-15-1985" aria-label="Permalink to “50 FR 2046 (January 15, 1985)”">​</a></h3><p>A change in administrative procedure now relieves the administration of the obligation of making copies of all 行政听证会s available at cost, due to the large volumes involved. No drugs are mentioned.</p><h3 id="_50-fr8104-february-28-1985" tabindex="-1">50 FR8104 (February 28, 1985) <a class="header-anchor" href="#_50-fr8104-february-28-1985" aria-label="Permalink to “50 FR8104 (February 28, 1985)”">​</a> <a class="header-anchor" href="#_50-fr8104-february-28-1985" aria-label="Permalink to “50 FR8104 (February 28, 1985)”">​</a></h3><p>Final ruling for the transferring of Buprenorphine from 附表一 (Schedule I)I to 附表五 (Schedule V) as a prerequisite to its being marketed with an NDA (New Drug Application) from the FDA. It will remain classified as a 麻醉药品 controlled substance. It was implicitly listed as a 附表一 (Schedule I)I drug as it is an Opium Derivative, specifically a derivative of Thebaine. The 初步拟定规则提案 for making Buprenorphine 附表五 (Schedule V) (see 47 FR 41401) was objected to by several manufacturers, and 行政听证会s were requested and 获得正式批准. The Administrative Law Judge recommended that Buprenorphine not be scheduled, and not be called a 麻醉药品. These suggestions were not followed. This entry is interesting as it addresses the question of a definition of the term derivative.</p><h3 id="_50-fr-11690-march-25-1985" tabindex="-1">50 FR 11690 (March 25, 1985) <a class="header-anchor" href="#_50-fr-11690-march-25-1985" aria-label="Permalink to “50 FR 11690 (March 25, 1985)”">​</a> <a class="header-anchor" href="#_50-fr-11690-march-25-1985" aria-label="Permalink to “50 FR 11690 (March 25, 1985)”">​</a></h3><p>The announcement of the invocation of the Emergency Scheduling powers of the CSA to place 3Methylfentanyl into 附表一 (Schedule I) effective April 25, 1985.</p><h3 id="_50-fr-11902-march-26-1985" tabindex="-1">50 FR 11902 (March 26, 1985) <a class="header-anchor" href="#_50-fr-11902-march-26-1985" aria-label="Permalink to “50 FR 11902 (March 26, 1985)”">​</a> <a class="header-anchor" href="#_50-fr-11902-march-26-1985" aria-label="Permalink to “50 FR 11902 (March 26, 1985)”">​</a></h3><p>A proposal for changes in regulations concerning record keeping by practitioners in connection with the distribution of scheduled drugs. See 50 FR 40522 for 最终行政裁决命令.</p><h3 id="_50-fr-23118-may-31-1985" tabindex="-1">50 FR 23118 (May 31, 1985) <a class="header-anchor" href="#_50-fr-23118-may-31-1985" aria-label="Permalink to “50 FR 23118 (May 31, 1985)”">​</a> <a class="header-anchor" href="#_50-fr-23118-may-31-1985" aria-label="Permalink to “50 FR 23118 (May 31, 1985)”">​</a></h3><p>The announcement of the invocation of the Emergency Scheduling powers to place MDMA into 附表一 (Schedule I) effective July 1, 1985, despite the 行政听证会s that have been agreed upon and which are forthcoming. See 50 FR 28395 for a typographical correction.</p><h3 id="_50-fr-23144-may-31-1985" tabindex="-1">50 FR 23144 (May 31, 1985) <a class="header-anchor" href="#_50-fr-23144-may-31-1985" aria-label="Permalink to “50 FR 23144 (May 31, 1985)”">​</a> <a class="header-anchor" href="#_50-fr-23144-may-31-1985" aria-label="Permalink to “50 FR 23144 (May 31, 1985)”">​</a></h3><p>A proposal to remove Nalmefene from control in 附表一 (Schedule I)I, where it was implicitly contained as a derivative of Thebaine. See 50 FR 45815.</p><h3 id="_50-fr-23451-june-4-1985" tabindex="-1">50 FR 23451 (June 4, 1985) <a class="header-anchor" href="#_50-fr-23451-june-4-1985" aria-label="Permalink to “50 FR 23451 (June 4, 1985)”">​</a> <a class="header-anchor" href="#_50-fr-23451-june-4-1985" aria-label="Permalink to “50 FR 23451 (June 4, 1985)”">​</a></h3><p>A proposal to change regulations involving the distribution and dispensing of controlled drugs in a maritime environment due to the closing of the US Public Health Service hospitals. See 50 FR 31588 for 最终行政裁决命令.</p><h3 id="_50-fr-28098-july-10-1985" tabindex="-1">50 FR 28098 (July 10, 1985) <a class="header-anchor" href="#_50-fr-28098-july-10-1985" aria-label="Permalink to “50 FR 28098 (July 10, 1985)”">​</a> <a class="header-anchor" href="#_50-fr-28098-july-10-1985" aria-label="Permalink to “50 FR 28098 (July 10, 1985)”">​</a></h3><p>The 紧急列管程序 provisions of the CSA have been invoked (to be effective August 12, 1985) to place MPPP (1-Methyl-4-phenyl-4propionoxy- piperidine) and PEPAP [1-(2-Phenethyl)-4-phenyl-4-acetyloxy- piperidine) in 附表一 (Schedule I) for a one year period, extendable for an additional 6-month period. This is necessary to avoid an imminent hazard to the public safety.</p><h3 id="_50-fr-28395-july-12-1985" tabindex="-1">50 FR 28395 (July 12, 1985) <a class="header-anchor" href="#_50-fr-28395-july-12-1985" aria-label="Permalink to “50 FR 28395 (July 12, 1985)”">​</a> <a class="header-anchor" href="#_50-fr-28395-july-12-1985" aria-label="Permalink to “50 FR 28395 (July 12, 1985)”">​</a></h3><p>A typographic error in 50 FR 23118 (the 紧急列管程序 of MDMA) has been corrected.</p><h3 id="_50-fr-28769-july-16-1985" tabindex="-1">50 FR 28769 (July 16, 1985) <a class="header-anchor" href="#_50-fr-28769-july-16-1985" aria-label="Permalink to “50 FR 28769 (July 16, 1985)”">​</a> <a class="header-anchor" href="#_50-fr-28769-july-16-1985" aria-label="Permalink to “50 FR 28769 (July 16, 1985)”">​</a></h3><p>A final ruling delegating authority to the DEA for settling employee claims. No drugs mentioned.</p><h3 id="_50-fr-31588-august-5-1985" tabindex="-1">50 FR 31588 (August 5, 1985) <a class="header-anchor" href="#_50-fr-31588-august-5-1985" aria-label="Permalink to “50 FR 31588 (August 5, 1985)”">​</a> <a class="header-anchor" href="#_50-fr-31588-august-5-1985" aria-label="Permalink to “50 FR 31588 (August 5, 1985)”">​</a></h3><p>The 最终行政裁决命令 changing regulations involving the distribution and dispensing of controlled drugs in a maritime environment due to the closing of the USPHS hospitals. See 50 FR 23451 for the 初步拟定规则提案. No drugs are specifically mentioned.</p><h3 id="_50-fr-40522-october-4-1985" tabindex="-1">50 FR 40522 (October 4, 1985) <a class="header-anchor" href="#_50-fr-40522-october-4-1985" aria-label="Permalink to “50 FR 40522 (October 4, 1985)”">​</a> <a class="header-anchor" href="#_50-fr-40522-october-4-1985" aria-label="Permalink to “50 FR 40522 (October 4, 1985)”">​</a></h3><p>The 最终行政裁决命令 changing the regulations concerning record keeping by practitioners in connection with the distribution of scheduled drugs. See 50 FR 11902 for the 初步拟定规则提案. There is no mention of specific drugs.</p><h3 id="_50-fr-42184-october-18-1985" tabindex="-1">50 FR 42184 (October 18, 1985) <a class="header-anchor" href="#_50-fr-42184-october-18-1985" aria-label="Permalink to “50 FR 42184 (October 18, 1985)”">​</a> <a class="header-anchor" href="#_50-fr-42184-october-18-1985" aria-label="Permalink to “50 FR 42184 (October 18, 1985)”">​</a></h3><p>; and</p><h3 id="_50-fr-42186-october-18-1985" tabindex="-1">50 FR 42186 (October 18, 1985) <a class="header-anchor" href="#_50-fr-42186-october-18-1985" aria-label="Permalink to “50 FR 42186 (October 18, 1985)”">​</a> <a class="header-anchor" href="#_50-fr-42186-october-18-1985" aria-label="Permalink to “50 FR 42186 (October 18, 1985)”">​</a></h3><p>Two notices dealing with the transfer of delta-9 THC from 附表一 (Schedule I) to 附表一 (Schedule I)I. Proposal for the reclassification of delta-9-THC from 附表一 (Schedule I) to 附表一 (Schedule I)I when it is mixed with sesame oil and encased in a gelatin capsule (the drug is now called Dronabinol). Unformulated, THC remains in 附表一 (Schedule I). There is also an extensive section called “changes in protocol” which deals with the prescription requirements for practitioners. Dronabinol may only be prescribed for FDA approved applications.</p><h3 id="_50-fr-43698-october-29-1985" tabindex="-1">50 FR 43698 (October 29, 1985) <a class="header-anchor" href="#_50-fr-43698-october-29-1985" aria-label="Permalink to “50 FR 43698 (October 29, 1985)”">​</a> <a class="header-anchor" href="#_50-fr-43698-october-29-1985" aria-label="Permalink to “50 FR 43698 (October 29, 1985)”">​</a></h3><p>The powers of the Emergency Scheduling Act have been employed to place eight fentanyl analogs into 附表一 (Schedule I) with the allowed 30 day notice. The compounds are, specifically: Acetyl-alphamethylfentanyl (9815), alpha-Methyl-thiofentanyl (9832), Benzylfentanyl (9818), beta-Hydroxy- fentanyl (9830), beta-Hydroxy-3-methylfentanyl (9831), 3-Methyl- thiofentanyl (9833), Thenylfentanyl (9834), and Thiofentanyl (9835). This emergency expires on November 29, 1986.</p><h3 id="_50-fr-45815-november-4-1985" tabindex="-1">50 FR 45815 (November 4, 1985) <a class="header-anchor" href="#_50-fr-45815-november-4-1985" aria-label="Permalink to “50 FR 45815 (November 4, 1985)”">​</a> <a class="header-anchor" href="#_50-fr-45815-november-4-1985" aria-label="Permalink to “50 FR 45815 (November 4, 1985)”">​</a></h3><p>This is the final notice for the removal of Nalmefene from 附表一 (Schedule I)I control where it had been implicitly listed by the virtue of its being a derivative of the 附表一 (Schedule I)I opioid, Thebaine. See 50 FR 23144 for the 初步拟定规则提案 for this 取消管制/去列管.</p><h3 id="_51-fr4722-february-7-1986" tabindex="-1">51 FR4722 (February 7, 1986) <a class="header-anchor" href="#_51-fr4722-february-7-1986" aria-label="Permalink to “51 FR4722 (February 7, 1986)”">​</a> <a class="header-anchor" href="#_51-fr4722-february-7-1986" aria-label="Permalink to “51 FR4722 (February 7, 1986)”">​</a></h3><p>A notice that the Emergency Scheduling Act is being invoked to list p-Fuorofentanyl as a 附表一 (Schedule I) substance, to avoid an imminent hazard to public safety. This placement which involves para-Fuorofentanyl and its optical isomers, and its salts, and the salts of optical isomers, will become effective March 10, 1986.</p><h3 id="_51-fr4763-february-7-1986" tabindex="-1">51 FR4763 (February 7, 1986) <a class="header-anchor" href="#_51-fr4763-february-7-1986" aria-label="Permalink to “51 FR4763 (February 7, 1986)”">​</a> <a class="header-anchor" href="#_51-fr4763-february-7-1986" aria-label="Permalink to “51 FR4763 (February 7, 1986)”">​</a></h3><p>This is a notice for proposed rule-making, soliciting comments concerning the placement of Quazepam and Midazolam into 附表一 (Schedule I)V, as the NDA’s for these two drugs have been approved by the FDA. See 51 FR 10190 for the 最终行政裁决命令.</p><h3 id="_51fr5319-february-13-1986" tabindex="-1">51FR5319 (February 13, 1986) <a class="header-anchor" href="#_51fr5319-february-13-1986" aria-label="Permalink to “51FR5319 (February 13, 1986)”">​</a> <a class="header-anchor" href="#_51fr5319-february-13-1986" aria-label="Permalink to “51FR5319 (February 13, 1986)”">​</a></h3><p>A series of nomenclature changes in the Title 21 of the Code of Federal Regulations is made.</p><h3 id="_51fr5370-february-13-1986" tabindex="-1">51FR5370 (February 13, 1986) <a class="header-anchor" href="#_51fr5370-february-13-1986" aria-label="Permalink to “51FR5370 (February 13, 1986)”">​</a> <a class="header-anchor" href="#_51fr5370-february-13-1986" aria-label="Permalink to “51FR5370 (February 13, 1986)”">​</a></h3><p>This is a presentation of proposed regulations to establish the DEA procedures for enforcing that portion of the Comprehensive Crime Control Act of 1984 which is known as the Dangerous Drug Diversion Control Act of 1984. These regulations include changes of definitions of both isomers and of 麻醉药品 drugs, the explicit listing of Cocaine and Ecgonine outside of the term “Coca leaves”, additional official use of the DEA Code Numbers, and the inclusion of the new Emergency Scheduling regulations. See final notice 51 FR 15317.</p><h3 id="_51-fr9440-march-19-1986" tabindex="-1">51 FR9440 (March 19, 1986) <a class="header-anchor" href="#_51-fr9440-march-19-1986" aria-label="Permalink to “51 FR9440 (March 19, 1986)”">​</a> <a class="header-anchor" href="#_51-fr9440-march-19-1986" aria-label="Permalink to “51 FR9440 (March 19, 1986)”">​</a></h3><p>The correction of a typographical error in 51 FR 5319 concerning Title 21 of the Code of Federal Regulations.</p><h3 id="_51-fr10190-march-25-1986" tabindex="-1">51 FR10190 (March 25, 1986) <a class="header-anchor" href="#_51-fr10190-march-25-1986" aria-label="Permalink to “51 FR10190 (March 25, 1986)”">​</a> <a class="header-anchor" href="#_51-fr10190-march-25-1986" aria-label="Permalink to “51 FR10190 (March 25, 1986)”">​</a></h3><p>The final notice for the inclusion of Midazolam and Quazepam into 附表一 (Schedule I)V as 中枢抑制剂 drugs. See 51 FR 4763 for the 初步拟定规则提案.</p><h3 id="_51-fr-13025-april-17-1986" tabindex="-1">51 FR 13025 (April 17, 1986) <a class="header-anchor" href="#_51-fr-13025-april-17-1986" aria-label="Permalink to “51 FR 13025 (April 17, 1986)”">​</a> <a class="header-anchor" href="#_51-fr-13025-april-17-1986" aria-label="Permalink to “51 FR 13025 (April 17, 1986)”">​</a></h3><p>The relocation of Alfentanil from Schedule J to 附表一 (Schedule I)I is proposed, as the FDA is about to issue a NDA for it</p><h3 id="_51fr15317-april-23-1986" tabindex="-1">51FR15317 (April 23, 1986) <a class="header-anchor" href="#_51fr15317-april-23-1986" aria-label="Permalink to “51FR15317 (April 23, 1986)”">​</a> <a class="header-anchor" href="#_51fr15317-april-23-1986" aria-label="Permalink to “51FR15317 (April 23, 1986)”">​</a></h3><p>The final ruling of the proposed regulations in 51 FR 5370, concerning definitions, uses of code numbers, and regulations concerning Emergency Scheduling.</p><h3 id="_51-fr-15474-april-24-1986" tabindex="-1">51 FR 15474 (April 24, 1986) <a class="header-anchor" href="#_51-fr-15474-april-24-1986" aria-label="Permalink to “51 FR 15474 (April 24, 1986)”">​</a> <a class="header-anchor" href="#_51-fr-15474-april-24-1986" aria-label="Permalink to “51 FR 15474 (April 24, 1986)”">​</a></h3><p>This is an extension of the Emergency Scheduling of 3Methylfentanyl (see 50 FR 11690) for up to an additional 6 months</p><h3 id="_51-fr-15501-april-24-1986" tabindex="-1">51 FR 15501 (April 24, 1986) <a class="header-anchor" href="#_51-fr-15501-april-24-1986" aria-label="Permalink to “51 FR 15501 (April 24, 1986)”">​</a> <a class="header-anchor" href="#_51-fr-15501-april-24-1986" aria-label="Permalink to “51 FR 15501 (April 24, 1986)”">​</a></h3><p>Thisisa notice proposing the permanent placement of 3-Methylfentanyl into 附表一 (Schedule I) of the CSA. There had been a temporary 附表一 (Schedule I) status under the Emergency Scheduling Law (50 FR 11690) which had been extended for up to an additional six months (51 FR 15474).</p><h3 id="_51fr17476-may-13-1986" tabindex="-1">51FR17476 (May 13, 1986) <a class="header-anchor" href="#_51fr17476-may-13-1986" aria-label="Permalink to “51FR17476 (May 13, 1986)”">​</a> <a class="header-anchor" href="#_51fr17476-may-13-1986" aria-label="Permalink to “51FR17476 (May 13, 1986)”">​</a></h3><p>This is the notice of 最终行政裁决命令 on the rescheduling of THC from 附表一 (Schedule I) to 附表一 (Schedule I)I, when admixed with sesame oil in a soft gelatin capsule. Two unique aspects of this situation are: this is the first entry of a 致幻性 drug outside of a 附表一 (Schedule I) category, and; this is the first instance where the prescriptive use of a drug is explicitly dictated by a Federal Agency (approved for use only in association with cancer treatment).</p><h3 id="_51-fr-17494-may-13-1986" tabindex="-1">51 FR 17494 (May 13, 1986) <a class="header-anchor" href="#_51-fr-17494-may-13-1986" aria-label="Permalink to “51 FR 17494 (May 13, 1986)”">​</a> <a class="header-anchor" href="#_51-fr-17494-may-13-1986" aria-label="Permalink to “51 FR 17494 (May 13, 1986)”">​</a></h3><p>The proposed rule-making (50 FR 42184, concerning restrictions to be applied to the prescription limitations that must be applied to the use of Dronabinol), has been withdrawn. Only modest restriction on the use of the drug remain (see 51 FR 17476).</p><h3 id="_51fr21911-june-17-1986" tabindex="-1">51FR21911 (June 17, 1986) <a class="header-anchor" href="#_51fr21911-june-17-1986" aria-label="Permalink to “51FR21911 (June 17, 1986)”">​</a> <a class="header-anchor" href="#_51fr21911-june-17-1986" aria-label="Permalink to “51FR21911 (June 17, 1986)”">​</a></h3><p>Thisisa notice of the invocation of the six month extension provision of the Emergency Scheduling process that had been applied to MDMA. The 临时暂行管制 of MDMA in 附表一 (Schedule I) has been extended to January 1, 1987 or until the conclusion of the rulemaking procedure, whichever occurs first.</p><h3 id="_51-fr-22085-june-18-1986" tabindex="-1">51 FR 22085 (June 18, 1986) <a class="header-anchor" href="#_51-fr-22085-june-18-1986" aria-label="Permalink to “51 FR 22085 (June 18, 1986)”">​</a> <a class="header-anchor" href="#_51-fr-22085-june-18-1986" aria-label="Permalink to “51 FR 22085 (June 18, 1986)”">​</a></h3><p>This is an 初步拟定规则提案 for the placement of Nabilone into 附表一 (Schedule I)I.</p><h3 id="_51-fr22946-june-24-1986" tabindex="-1">51 FR22946 (June 24, 1986) <a class="header-anchor" href="#_51-fr22946-june-24-1986" aria-label="Permalink to “51 FR22946 (June 24, 1986)”">​</a> <a class="header-anchor" href="#_51-fr22946-june-24-1986" aria-label="Permalink to “51 FR22946 (June 24, 1986)”">​</a></h3><p>Thisisa notice of a 行政听证会 that will be held on the matter of rescheduling Marihuana and its components.</p><h3 id="_51-fr-28695-august-11-1986" tabindex="-1">51 FR 28695 (August 11, 1986) <a class="header-anchor" href="#_51-fr-28695-august-11-1986" aria-label="Permalink to “51 FR 28695 (August 11, 1986)”">​</a> <a class="header-anchor" href="#_51-fr-28695-august-11-1986" aria-label="Permalink to “51 FR 28695 (August 11, 1986)”">​</a></h3><p>The Emergency scheduling of MPPP (9661) and PEPAP (9663) were due to expire on August 12, and they have been extended for up to six months.</p><h3 id="_51-fr-28725-august-11-1986" tabindex="-1">51 FR 28725 (August 11, 1986) <a class="header-anchor" href="#_51-fr-28725-august-11-1986" aria-label="Permalink to “51 FR 28725 (August 11, 1986)”">​</a> <a class="header-anchor" href="#_51-fr-28725-august-11-1986" aria-label="Permalink to “51 FR 28725 (August 11, 1986)”">​</a></h3><p>A formal proposal is made for 行政听证会s and comments associated with the suggested placement of MPPP and PEPAP into a permanent classification of 附表一 (Schedule I).</p><h3 id="_51-fr-28727-august-11-1986" tabindex="-1">51 FR 28727 (August 11, 1986) <a class="header-anchor" href="#_51-fr-28727-august-11-1986" aria-label="Permalink to “51 FR 28727 (August 11, 1986)”">​</a> <a class="header-anchor" href="#_51-fr-28727-august-11-1986" aria-label="Permalink to “51 FR 28727 (August 11, 1986)”">​</a></h3><p>Proposals had been made (46 FR 35529) and withdrawn (46 FR 60008) for the placement of Tiletamine (7290) and Zolazepam (2930) into 附表一 (Schedule I), and a mixture of them (as Telazol) into 附表一 (Schedule I)II. These proposals are reinitiated.</p><h3 id="_51-fr-33592-september-22-1986" tabindex="-1">51 FR 33592 (September 22, 1986) <a class="header-anchor" href="#_51-fr-33592-september-22-1986" aria-label="Permalink to “51 FR 33592 (September 22, 1986)”">​</a> <a class="header-anchor" href="#_51-fr-33592-september-22-1986" aria-label="Permalink to “51 FR 33592 (September 22, 1986)”">​</a></h3><p>This announces the 最终行政裁决命令 placing 3Methylfentanyl into 附表一 (Schedule I).</p><h3 id="_51-fr-36552-october-14-1986" tabindex="-1">51 FR 36552 (October 14, 1986) <a class="header-anchor" href="#_51-fr-36552-october-14-1986" aria-label="Permalink to “51 FR 36552 (October 14, 1986)”">​</a> <a class="header-anchor" href="#_51-fr-36552-october-14-1986" aria-label="Permalink to “51 FR 36552 (October 14, 1986)”">​</a></h3><p>This announcesthe permanent placement of MDMA into 附表一 (Schedule I). A series of 92 specific statements are listed to accompany the decision not to accept the Administrative Law Judge’s suggestions to place MDMA in a lower Schedule.</p><h3 id="_51-fr-42834-november-26-1986" tabindex="-1">51 FR 42834 (November 26, 1986) <a class="header-anchor" href="#_51-fr-42834-november-26-1986" aria-label="Permalink to “51 FR 42834 (November 26, 1986)”">​</a> <a class="header-anchor" href="#_51-fr-42834-november-26-1986" aria-label="Permalink to “51 FR 42834 (November 26, 1986)”">​</a></h3><p>The extension of the emergency placement of six Fentanyl analogs (see 50 FR 43698) into 附表一 (Schedule I) for an additional six months. However, in 50 FR 43698 there were eight compounds, thus two have been allowed to escape from emergency control. Remaining under emergency control are Acetyl-alphamethylfentany] (9815), alpha-Methylthiofentanyl (9832), beta-Hydroxyfentanyl] (9830), betaHydroxy-3- methylfentanyl (9831), 3-Methy]lthiofentanyl (9833), and Thiofentanyl (9835). The two that have been dropped from the proposal for 紧急列管程序 are Benzylfentanyl (9818) and Thenylfentany] (9834). They are both potential 化学前体s to Norfentanyl (or Desmethylfentanyl), a potentially valuable chemical intermediate.</p><h3 id="_51-fr-43025-november-28-1986" tabindex="-1">51 FR 43025 (November 28, 1986) <a class="header-anchor" href="#_51-fr-43025-november-28-1986" aria-label="Permalink to “51 FR 43025 (November 28, 1986)”">​</a> <a class="header-anchor" href="#_51-fr-43025-november-28-1986" aria-label="Permalink to “51 FR 43025 (November 28, 1986)”">​</a></h3><p>The is the official proposal for making permanent the classification of the six Fentanyl analogs that are in 附表一 (Schedule I) on a temporary 紧急列管程序 basis. The six-month extension of their temporary 附表一 (Schedule I) status is due to expire on May 29, 1987.</p><h3 id="_52-fr2221-january-21-1987" tabindex="-1">52 FR2221 (January 21, 1987) <a class="header-anchor" href="#_52-fr2221-january-21-1987" aria-label="Permalink to “52 FR2221 (January 21, 1987)”">​</a> <a class="header-anchor" href="#_52-fr2221-january-21-1987" aria-label="Permalink to “52 FR2221 (January 21, 1987)”">​</a></h3><p>This is the official announcement of the placement of the Tiletamine-Zolazepam mixture (known as Telazol) into 附表一 (Schedule I)II, effective February 20, 1987. No action has been taken as to the scheduling of the components, although Tiletamine is stated to be pharmacologically substantially similar to a 附表一 (Schedule I)I drug, and Zolazepam can be added to 附表一 (Schedule I)under the Emergency Scheduling law if it is encountered in the illicit trade.</p><h3 id="_52fr2515-january-23-1987" tabindex="-1">52FR2515 (January 23, 1987) <a class="header-anchor" href="#_52fr2515-january-23-1987" aria-label="Permalink to “52FR2515 (January 23, 1987)”">​</a> <a class="header-anchor" href="#_52fr2515-january-23-1987" aria-label="Permalink to “52FR2515 (January 23, 1987)”">​</a></h3><p>This announces the 最终命令 that places MPPP and PEPAP permanently into 附表一 (Schedule I).</p><h3 id="_52-fr2516-january-23-1987" tabindex="-1">52 FR2516 (January 23, 1987) <a class="header-anchor" href="#_52-fr2516-january-23-1987" aria-label="Permalink to “52 FR2516 (January 23, 1987)”">​</a> <a class="header-anchor" href="#_52-fr2516-january-23-1987" aria-label="Permalink to “52 FR2516 (January 23, 1987)”">​</a></h3><p>The official announcement that relocates Alfentanil from 附表一 (Schedule I) to 附表一 (Schedule I)I.</p><h3 id="_52-fr5951-february-27-1987" tabindex="-1">52 FR5951 (February 27, 1987) <a class="header-anchor" href="#_52-fr5951-february-27-1987" aria-label="Permalink to “52 FR5951 (February 27, 1987)”">​</a> <a class="header-anchor" href="#_52-fr5951-february-27-1987" aria-label="Permalink to “52 FR5951 (February 27, 1987)”">​</a></h3><p>A rule is given by the DEA allowing the assignment of additional DEA code numbers to a given drug as it appears in different drug schedules.</p><h3 id="_52-fr6546-march-4-1987" tabindex="-1">52 FR6546 (March 4, 1987) <a class="header-anchor" href="#_52-fr6546-march-4-1987" aria-label="Permalink to “52 FR6546 (March 4, 1987)”">​</a> <a class="header-anchor" href="#_52-fr6546-march-4-1987" aria-label="Permalink to “52 FR6546 (March 4, 1987)”">​</a></h3><p>A correction to the wording of the changes recorded in 52 FR 2515 which removes MPPP and PEPAP from 紧急列管程序 status and places them permanently into 附表一 (Schedule I).</p><h3 id="_52-fr7270-march-10-1987" tabindex="-1">52 FR7270 (March 10, 1987) <a class="header-anchor" href="#_52-fr7270-march-10-1987" aria-label="Permalink to “52 FR7270 (March 10, 1987)”">​</a> <a class="header-anchor" href="#_52-fr7270-march-10-1987" aria-label="Permalink to “52 FR7270 (March 10, 1987)”">​</a></h3><p>The temporary status of p-Fluorofentanyl as a 附表一 (Schedule I) drug under the Emergency scheduling Act regulations has been extended for an additional six months.</p><h3 id="_52-fr-7280-march-10-1987" tabindex="-1">52 FR 7280 (March 10, 1987) <a class="header-anchor" href="#_52-fr-7280-march-10-1987" aria-label="Permalink to “52 FR 7280 (March 10, 1987)”">​</a> <a class="header-anchor" href="#_52-fr-7280-march-10-1987" aria-label="Permalink to “52 FR 7280 (March 10, 1987)”">​</a></h3><p>The official proposal is made to place p-Fluorofentanyl into 附表一 (Schedule I) status. It is currently in 附表一 (Schedule I) as a temporary, emergency classification. 52 FR 9802 and 9806 _ (April, 1987) This is an extensive listing of the many exceptions and exemptions to the legal restrictions on scheduled drugs, made for small quantities used in scientific analysis and research.</p><h3 id="_52-fr-11042-april-7-1987" tabindex="-1">52 FR 11042 (April 7, 1987) <a class="header-anchor" href="#_52-fr-11042-april-7-1987" aria-label="Permalink to “52 FR 11042 (April 7, 1987)”">​</a> <a class="header-anchor" href="#_52-fr-11042-april-7-1987" aria-label="Permalink to “52 FR 11042 (April 7, 1987)”">​</a></h3><p>A 最终命令 placing Nabilone (a chemical relative of THC) into 附表一 (Schedule I)I of the CSA. Some minor typographical errors are corrected, see 52 FR 12285.</p><h3 id="_52-fr-12285-april-15-1987" tabindex="-1">52 FR 12285 (April 15, 1987) <a class="header-anchor" href="#_52-fr-12285-april-15-1987" aria-label="Permalink to “52 FR 12285 (April 15, 1987)”">​</a> <a class="header-anchor" href="#_52-fr-12285-april-15-1987" aria-label="Permalink to “52 FR 12285 (April 15, 1987)”">​</a></h3><p>Some minor typographical corrections made to the entry 52 FR 11042.</p><h3 id="_52-fr-20070-may-29-1987" tabindex="-1">52 FR 20070 (May 29, 1987) <a class="header-anchor" href="#_52-fr-20070-may-29-1987" aria-label="Permalink to “52 FR 20070 (May 29, 1987)”">​</a> <a class="header-anchor" href="#_52-fr-20070-may-29-1987" aria-label="Permalink to “52 FR 20070 (May 29, 1987)”">​</a></h3><p>The 最终行政裁决命令 placing six Fentanyl analogs into 附表一 (Schedule I) on a permanent basis rather than under the Emergency Scheduling Act. These six are not the six that were proposed for this action in 51 FR43025. Five of these were from an initial emergency action (50 FR 43698) which had been extended (51 FR 42834) and proposed for permanent status (51 FR 43025). The sixth, para—Fluorofentanyl was acted on separately (proposal, 51 FR 4722; extension, 52 FR 7270; proposal for permanent status, 52 FR 7280). Missing is beta-Hydroxy-3- methylfentany] (9831), and its emergency status as a 附表一 (Schedule I) drug expired on this date (see 51 FR 42834). A minor typographical error in 52 FR 27198 is corrected.</p><h3 id="_52-fr-27198-july-20-1987" tabindex="-1">52 FR 27198 (July 20, 1987) <a class="header-anchor" href="#_52-fr-27198-july-20-1987" aria-label="Permalink to “52 FR 27198 (July 20, 1987)”">​</a> <a class="header-anchor" href="#_52-fr-27198-july-20-1987" aria-label="Permalink to “52 FR 27198 (July 20, 1987)”">​</a></h3><p>A minor correction is made in 52 FR 20070 wherein the adjective “high” had been omitted from the phrase “high potential for abuse.”</p><h3 id="_52-fr-30174-august-13-1987" tabindex="-1">52 FR 30174 (August 13, 1987) <a class="header-anchor" href="#_52-fr-30174-august-13-1987" aria-label="Permalink to “52 FR 30174 (August 13, 1987)”">​</a> <a class="header-anchor" href="#_52-fr-30174-august-13-1987" aria-label="Permalink to “52 FR 30174 (August 13, 1987)”">​</a></h3><p>This announces the intent to place 2-Amino-4methyl-5-phenyl-2-oxazoline (4-Methylaminorex) in调整转移至附表 i by the invocation of the Emergency Scheduling Act.</p><h3 id="_52-fr-30175-august-13-1987" tabindex="-1">52 FR 30175 (August 13, 1987) <a class="header-anchor" href="#_52-fr-30175-august-13-1987" aria-label="Permalink to “52 FR 30175 (August 13, 1987)”">​</a> <a class="header-anchor" href="#_52-fr-30175-august-13-1987" aria-label="Permalink to “52 FR 30175 (August 13, 1987)”">​</a></h3><p>This announces the intent to place 3,4-Methyilenedioxy-N-ethylamphetamine (N-Ethyl-MDA) and N-Hydroxy-3,4-methylenedioxyamphetamine (N-Hydroxy-MDA) into 附表一 (Schedule I) by the invocation of the Emergency Scheduling Act.</p><h3 id="_52-fr-38225-october-15-1987" tabindex="-1">52 FR 38225 (October 15, 1987) <a class="header-anchor" href="#_52-fr-38225-october-15-1987" aria-label="Permalink to “52 FR 38225 (October 15, 1987)”">​</a> <a class="header-anchor" href="#_52-fr-38225-october-15-1987" aria-label="Permalink to “52 FR 38225 (October 15, 1987)”">​</a></h3><p>The three drugs, N-Ethyl-3,4-methylenedioxyamhetamine, N-Hydroxy-3,4-methylenedioxyamphetamine (see 52 FR 30175) and 4-Methylaminorex (see 52 FR 30174) have been officially entered into 附表一 (Schedule I) for a period of one year through the evocation of the Emergency Scheduling procedure. The 正式生效日期 is October 15, 1987.</p><h3 id="_52-fr-41736-october-30-1987" tabindex="-1">52 FR 41736 (October 30, 1987) <a class="header-anchor" href="#_52-fr-41736-october-30-1987" aria-label="Permalink to “52 FR 41736 (October 30, 1987)”">​</a> <a class="header-anchor" href="#_52-fr-41736-october-30-1987" aria-label="Permalink to “52 FR 41736 (October 30, 1987)”">​</a></h3><p>Six drugs are proposed for scheduling, in response to the suggestions of the United Nations Commission on Narcotic Drugs. These are Cathenone and 2,5-Dimethoxy-4-ethylamphetamine (DOET) proposed for 附表一 (Schedule I), and Cathine, Fencamfamine, Fenproporex and Mefenorex proposed for 附表一 (Schedule I)V.</p><h3 id="_52-fr-41737-october-30-1987" tabindex="-1">52 FR 41737 (October 30, 1987) <a class="header-anchor" href="#_52-fr-41737-october-30-1987" aria-label="Permalink to “52 FR 41737 (October 30, 1987)”">​</a> <a class="header-anchor" href="#_52-fr-41737-october-30-1987" aria-label="Permalink to “52 FR 41737 (October 30, 1987)”">​</a></h3><p>Two drugs, Propylhexedrine and Pyrovalerone, are proposed for inclusion into 附表五 (Schedule V) in response to the suggestions of the United Nations Commission on Narcotic Drugs. Propylhexedrine is sold in the U.S. as an OTC nonprescription drug. See 53 FR 110869 for 最终行政裁决命令.</p><h3 id="_53-fr-500-january-8-1988" tabindex="-1">53 FR 500 (January 8, 1988) <a class="header-anchor" href="#_53-fr-500-january-8-1988" aria-label="Permalink to “53 FR 500 (January 8, 1988)”">​</a> <a class="header-anchor" href="#_53-fr-500-january-8-1988" aria-label="Permalink to “53 FR 500 (January 8, 1988)”">​</a></h3><p>This is an announcement of 最终行政裁决命令 on the placement of beta-Hydroxy-3-methylfentany] into 附表一 (Schedule I). Since the Emergency Scheduling status of this drug expired on May 29, 1987, there is a period of over 7 months during which there was no legal control explicitly applying to this drug.</p><h3 id="_53-fr-743-january-12-1988" tabindex="-1">53 FR 743 (January 12, 1988) <a class="header-anchor" href="#_53-fr-743-january-12-1988" aria-label="Permalink to “53 FR 743 (January 12, 1988)”">​</a> <a class="header-anchor" href="#_53-fr-743-january-12-1988" aria-label="Permalink to “53 FR 743 (January 12, 1988)”">​</a></h3><p>This is the announcement for the placement of Carfentanil into 附表一 (Schedule I)I, upon its final approval by the FDA as a veternary medicine</p><h3 id="_53-fr2225-january-27-1988" tabindex="-1">53 FR2225 (January 27, 1988) <a class="header-anchor" href="#_53-fr2225-january-27-1988" aria-label="Permalink to “53 FR2225 (January 27, 1988)”">​</a> <a class="header-anchor" href="#_53-fr2225-january-27-1988" aria-label="Permalink to “53 FR2225 (January 27, 1988)”">​</a></h3><p>In response to the action of the court decision, requiring that MDMA has been removed from Ibeing listed in 附表一 (Schedule I). It is now controlled by the Analogue Drug Bill. See 53 FR 5156.</p><h3 id="_53-fr-3744-february-9-1988" tabindex="-1">53 FR 3744 (February 9, 1988) <a class="header-anchor" href="#_53-fr-3744-february-9-1988" aria-label="Permalink to “53 FR 3744 (February 9, 1988)”">​</a> <a class="header-anchor" href="#_53-fr-3744-february-9-1988" aria-label="Permalink to “53 FR 3744 (February 9, 1988)”">​</a></h3><p>The Drug Code Number for beta-Hydroxy-3-methylfentanyl is corrected to read 9831.</p><h3 id="_53-fr5156-february-22-1988" tabindex="-1">53 FR5156 (February 22, 1988) <a class="header-anchor" href="#_53-fr5156-february-22-1988" aria-label="Permalink to “53 FR5156 (February 22, 1988)”">​</a> <a class="header-anchor" href="#_53-fr5156-february-22-1988" aria-label="Permalink to “53 FR5156 (February 22, 1988)”">​</a></h3><p>A final ruling is made, replacing MDMA into 附表一 (Schedule I), effective March 23, 1988.</p><h3 id="_53-fr-10869-april-4-1988" tabindex="-1">53 FR 10869 (April 4, 1988) <a class="header-anchor" href="#_53-fr-10869-april-4-1988" aria-label="Permalink to “53 FR 10869 (April 4, 1988)”">​</a> <a class="header-anchor" href="#_53-fr-10869-april-4-1988" aria-label="Permalink to “53 FR 10869 (April 4, 1988)”">​</a></h3><p>This is the 最终行政裁决命令 placing Propylhexedrine and Pyrovalerone into 附表五 (Schedule V), effective May 4, 1988.</p><h3 id="_53-fr-17459-may-17-1988" tabindex="-1">53 FR 17459 (May 17, 1988) <a class="header-anchor" href="#_53-fr-17459-may-17-1988" aria-label="Permalink to “53 FR 17459 (May 17, 1988)”">​</a> <a class="header-anchor" href="#_53-fr-17459-may-17-1988" aria-label="Permalink to “53 FR 17459 (May 17, 1988)”">​</a></h3><p>The 临时暂行管制 of four drugs, cathine ((+)- norpseudoephedrine), fencamfamin, fenproporex and mefenorex, into 附表一 (Schedule I)V has been announced, in order to fulfill United States international treaty obligations. All existing regulations will apply to these four drugs as of June 16, 1988.</p><h3 id="_53-fr-21492-june-8-1988" tabindex="-1">53 FR 21492 (June 8, 1988) <a class="header-anchor" href="#_53-fr-21492-june-8-1988" aria-label="Permalink to “53 FR 21492 (June 8, 1988)”">​</a> <a class="header-anchor" href="#_53-fr-21492-june-8-1988" aria-label="Permalink to “53 FR 21492 (June 8, 1988)”">​</a></h3><p>The employment of the Emergency Scheduling procedure is proposed for the placement of N,N-dimethylamphetamine into 附表一 (Schedule I). This is based on its appearance in several clandestine laboratories and laboratory animal assays that show it to have a 中枢兴奋剂 action. This action is felt to be neccessary to avoid an imminent hazard to public safety.</p><h3 id="_53-fr-29232-august-3-1988" tabindex="-1">53 FR 29232 (August 3, 1988) <a class="header-anchor" href="#_53-fr-29232-august-3-1988" aria-label="Permalink to “53 FR 29232 (August 3, 1988)”">​</a> <a class="header-anchor" href="#_53-fr-29232-august-3-1988" aria-label="Permalink to “53 FR 29232 (August 3, 1988)”">​</a></h3><p>Effective this date, N,N-dimethylamphetamine has been officially 正式列入 附表一 (Schedule I), on a temporary basis, using the Emergency Scheduling Act.</p><h3 id="_53-fr-31837-august-22-1988" tabindex="-1">53 FR 31837 (August 22, 1988) <a class="header-anchor" href="#_53-fr-31837-august-22-1988" aria-label="Permalink to “53 FR 31837 (August 22, 1988)”">​</a> <a class="header-anchor" href="#_53-fr-31837-august-22-1988" aria-label="Permalink to “53 FR 31837 (August 22, 1988)”">​</a></h3><p>A technical correction of the spelling of Nabilone in the April 1988 revision of the Code of Federal Regulations,</p><h3 id="_53-fr-40061-october-13-1988" tabindex="-1">53 FR 40061 (October 13, 1988) <a class="header-anchor" href="#_53-fr-40061-october-13-1988" aria-label="Permalink to “53 FR 40061 (October 13, 1988)”">​</a> <a class="header-anchor" href="#_53-fr-40061-october-13-1988" aria-label="Permalink to “53 FR 40061 (October 13, 1988)”">​</a></h3><p>The one year 紧急列管程序 period for 3,4Methylenedioxy-N-ethylamphetamine, N-hydroxy-3,4-methylenedioxyamphetamine, and 4-methylaminorex, has been extended for six months.</p><h3 id="_53-fr-40390-october-14-1988" tabindex="-1">53 FR 40390 (October 14, 1988) <a class="header-anchor" href="#_53-fr-40390-october-14-1988" aria-label="Permalink to “53 FR 40390 (October 14, 1988)”">​</a> <a class="header-anchor" href="#_53-fr-40390-october-14-1988" aria-label="Permalink to “53 FR 40390 (October 14, 1988)”">​</a></h3><p>The required 60 day waiting period has been established for the consideration of the permanent placement of 3,4-methylenediox-N-ethylamphetamine and N-hydroxy-3,4-methylenedoxyamphetamine in 附表一 (Schedule I). They have been located there under the Emergency Scheduling Act for about one year.</p><h3 id="_53-fr-40391-october-14-1988" tabindex="-1">53 FR 40391 (October 14, 1988) <a class="header-anchor" href="#_53-fr-40391-october-14-1988" aria-label="Permalink to “53 FR 40391 (October 14, 1988)”">​</a> <a class="header-anchor" href="#_53-fr-40391-october-14-1988" aria-label="Permalink to “53 FR 40391 (October 14, 1988)”">​</a></h3><p>The one year 紧急列管程序 of 4-methy]laminorex had been extended for six months (to April 15, 1989) and the required period for comments concerning permanent placement into 附表一 (Schedule I) has been initiated.</p><h3 id="_53-fr-43684-october-28-1988" tabindex="-1">53 FR 43684 (October 28, 1988) <a class="header-anchor" href="#_53-fr-43684-october-28-1988" aria-label="Permalink to “53 FR 43684 (October 28, 1988)”">​</a> <a class="header-anchor" href="#_53-fr-43684-october-28-1988" aria-label="Permalink to “53 FR 43684 (October 28, 1988)”">​</a></h3><p>Carfentanil has been placed in 附表一 (Schedule I)I respecting its use in veternary medicine.</p><h3 id="_54-fr2100-january-19-1989" tabindex="-1">54 FR2100 (January 19, 1989) <a class="header-anchor" href="#_54-fr2100-january-19-1989" aria-label="Permalink to “54 FR2100 (January 19, 1989)”">​</a> <a class="header-anchor" href="#_54-fr2100-january-19-1989" aria-label="Permalink to “54 FR2100 (January 19, 1989)”">​</a></h3><p>Arequest has been made to exclude propylhexedrine from a controlled status under its 附表五 (Schedule V) classification if it is part of an OTC preparation (as a Benzedrex Inhaler). A 250 mg dosage is considered as exempt.</p><h3 id="_54-fr6144-february-8-1989" tabindex="-1">54 FR6144 (February 8, 1989) <a class="header-anchor" href="#_54-fr6144-february-8-1989" aria-label="Permalink to “54 FR6144 (February 8, 1989)”">​</a> <a class="header-anchor" href="#_54-fr6144-february-8-1989" aria-label="Permalink to “54 FR6144 (February 8, 1989)”">​</a></h3><p>This is a proposal of terms of possible regulations to address record keeping of 化学前体s and 关键化学品s, including tableting and encaspulating machines, as required by the 1988 law on Chemical Diversion and Trafficking Act. Many ideas are extended, and they are formallized in the response, see 54 FR 31657.</p><h3 id="_54-fr-11387-march-20-1989" tabindex="-1">54 FR 11387 (March 20, 1989) <a class="header-anchor" href="#_54-fr-11387-march-20-1989" aria-label="Permalink to “54 FR 11387 (March 20, 1989)”">​</a> <a class="header-anchor" href="#_54-fr-11387-march-20-1989" aria-label="Permalink to “54 FR 11387 (March 20, 1989)”">​</a></h3><p>The PCP analogue 1-[1-(2-Thienyl)cyclohexyl]- pyrrolidine has been identified in drug submissions to forensic laboratories and has been sold as PCP in the street. This notice initiates a sixty day period for comment and potential 行政听证会s concerning its inclusion in 附表一 (Schedule I) of the CSA as a hallucinogen.</p><h3 id="_54-fr-14797-april-13-1989" tabindex="-1">54 FR 14797 (April 13, 1989) <a class="header-anchor" href="#_54-fr-14797-april-13-1989" aria-label="Permalink to “54 FR 14797 (April 13, 1989)”">​</a> <a class="header-anchor" href="#_54-fr-14797-april-13-1989" aria-label="Permalink to “54 FR 14797 (April 13, 1989)”">​</a></h3><p>This is the final permanent placement of 3,4-methylenedioxy-N-ethylamphetamine and N-hydroxy-3,4-methylenedioxyamphetamine into 附表一 (Schedule I)</p><h3 id="_54-fr-14799-april-13-1989" tabindex="-1">54 FR 14799 (April 13, 1989) <a class="header-anchor" href="#_54-fr-14799-april-13-1989" aria-label="Permalink to “54 FR 14799 (April 13, 1989)”">​</a> <a class="header-anchor" href="#_54-fr-14799-april-13-1989" aria-label="Permalink to “54 FR 14799 (April 13, 1989)”">​</a></h3><p>This is the final ruling that places 4-methylaminorex into 附表一 (Schedule I). It was only within this final announcement that the specific name for this drug was changed from 4-methylaminorex to (+/-) cis-4-methylaminorex, with neither comment nor explanation.</p><h3 id="_54-fr-22498-may-24-1989" tabindex="-1">54 FR 22498 (May 24, 1989) <a class="header-anchor" href="#_54-fr-22498-may-24-1989" aria-label="Permalink to “54 FR 22498 (May 24, 1989)”">​</a> <a class="header-anchor" href="#_54-fr-22498-may-24-1989" aria-label="Permalink to “54 FR 22498 (May 24, 1989)”">​</a></h3><p>In accord with the Anti-drug Abuse Act of 1988, the DEA and the USEPA have drafted a set of guidelines for the cleanup procedures to be followed in the disposal of clandestine laboratories. This is a request for comments from interested parties.</p><h3 id="_54-fr-28414-july-6-1989" tabindex="-1">54 FR 28414 (July 6, 1989) <a class="header-anchor" href="#_54-fr-28414-july-6-1989" aria-label="Permalink to “54 FR 28414 (July 6, 1989)”">​</a> <a class="header-anchor" href="#_54-fr-28414-july-6-1989" aria-label="Permalink to “54 FR 28414 (July 6, 1989)”">​</a></h3><p>This is the final placement of 1-[1-(2-thienyl)-cyclohexyl)pyrrolidine into schedule I as a 致幻性 substance.</p><h3 id="_54-fr-31657-august-1-1989" tabindex="-1">54 FR 31657 (August 1,1989) <a class="header-anchor" href="#_54-fr-31657-august-1-1989" aria-label="Permalink to “54 FR 31657 (August 1,1989)”">​</a> <a class="header-anchor" href="#_54-fr-31657-august-1-1989" aria-label="Permalink to “54 FR 31657 (August 1,1989)”">​</a></h3><p>The proposed regulations addressing record-keeping of 化学前体s and 关键化学品s that were distributed for comment in 54 FR 6144 have been formalized, with all comments received having been discussed. There is presented the actual wording of the new regulations, organized in several sections. These are titled: definitions, substances covered, persons required to keep records and file reports, maintenance of records, reports, content of records and reports, and proof of identy.</p><h3 id="_54-fr-31815-august-2-1989" tabindex="-1">54 FR 31815 (August 2, 1989) <a class="header-anchor" href="#_54-fr-31815-august-2-1989" aria-label="Permalink to “54 FR 31815 (August 2, 1989)”">​</a> <a class="header-anchor" href="#_54-fr-31815-august-2-1989" aria-label="Permalink to “54 FR 31815 (August 2, 1989)”">​</a></h3><p>This is an extension of the temperary scheduling status of N,N-dimethylamphetamine for an additional six months.</p><h3 id="_54-fr-31855-august-2-1989" tabindex="-1">54 FR 31855 (August 2, 1989) <a class="header-anchor" href="#_54-fr-31855-august-2-1989" aria-label="Permalink to “54 FR 31855 (August 2, 1989)”">​</a> <a class="header-anchor" href="#_54-fr-31855-august-2-1989" aria-label="Permalink to “54 FR 31855 (August 2, 1989)”">​</a></h3><p>A sixty day notice is given for the receipt of comments on the proposal for the permanent placement of N,N-dimethylamphetamine in调整转移至附表l asa 中枢兴奋剂.</p><h3 id="_54-fr-37605-september-11-1989" tabindex="-1">54 FR 37605 (September 11, 1989) <a class="header-anchor" href="#_54-fr-37605-september-11-1989" aria-label="Permalink to “54 FR 37605 (September 11, 1989)”">​</a> <a class="header-anchor" href="#_54-fr-37605-september-11-1989" aria-label="Permalink to “54 FR 37605 (September 11, 1989)”">​</a></h3><p>This is an analysis of comments received concerning the writing of a body of regulation that concerns the procedures that shall apply to the admionistrative seizure of property in connection with certain violations of the CSA laws. Of special interest are the arguments that concern the role of the claimant in the establishment of innocense, and a discussion of what shall be considered (within the text of these regulations) as an amount of drug that is a quantity for personal use.</p><h3 id="_54-fr-53767-december-29-1989" tabindex="-1">54 FR 53767 (December 29, 1989) <a class="header-anchor" href="#_54-fr-53767-december-29-1989" aria-label="Permalink to “54 FR 53767 (December 29, 1989)”">​</a> <a class="header-anchor" href="#_54-fr-53767-december-29-1989" aria-label="Permalink to “54 FR 53767 (December 29, 1989)”">​</a></h3><p>This is a point by point discusion of the 行政请愿申请 that had been filed for the rescheduling of marihuana from 附表一 (Schedule I) to 附表一 (Schedule I)I. The 行政请愿申请 was 被依法驳回. 55 FR 3586 = (February 2, 1990) This is the final placement of N,N-dimethylamphetamine into 附表一 (Schedule I), as a 中枢兴奋剂, on a permanent basis.</p><h2 id="_1990-—-1991-年-合成代谢类固醇法案与国际前体监控升级" tabindex="-1">1990 — 1991 年：合成代谢类固醇法案与国际前体监控升级 <a class="header-anchor" href="#_1990-—-1991-年-合成代谢类固醇法案与国际前体监控升级" aria-label="Permalink to “1990 — 1991 年：合成代谢类固醇法案与国际前体监控升级”">​</a> <a class="header-anchor" href="#_1990-—-1991-年-合成代谢类固醇法案与国际前体监控升级" aria-label="Permalink to “1990 — 1991 年：合成代谢类固醇法案与国际前体监控升级”">​</a></h2><h3 id="_55-fr9117-march-12-1990" tabindex="-1">55 FR9117 (March 12, 1990) <a class="header-anchor" href="#_55-fr9117-march-12-1990" aria-label="Permalink to “55 FR9117 (March 12, 1990)”">​</a> <a class="header-anchor" href="#_55-fr9117-march-12-1990" aria-label="Permalink to “55 FR9117 (March 12, 1990)”">​</a></h3><p>The location of N,N-dimethylamphetamine in the schedules of drugs was inadvertently chosen at a position that was already occupied. This error is corrected.</p><h3 id="_55-fr-30472-july-2-1990" tabindex="-1">55 FR 30472 (July 2, 1990) <a class="header-anchor" href="#_55-fr-30472-july-2-1990" aria-label="Permalink to “55 FR 30472 (July 2, 1990)”">​</a> <a class="header-anchor" href="#_55-fr-30472-july-2-1990" aria-label="Permalink to “55 FR 30472 (July 2, 1990)”">​</a></h3><p>A proposal is made for the relocation of Glutethimide from 附表一 (Schedule I)II to 附表一 (Schedule I)I. 55 FR 33181 (August 14. 1990) A notice has been published announcing the availability of guidelines for the cleanup of clandestine drug laboratories. It may be obtained from Joseph Boykeirch, Office of Forensic Sciences, Hazardous Waste Disposal Unit, 美国缉毒局 (DEA), Washington, D.C. 20537.</p><h3 id="_55-fr-35323-august-29-1990" tabindex="-1">55 FR 35323 (August 29, 1990) <a class="header-anchor" href="#_55-fr-35323-august-29-1990" aria-label="Permalink to “55 FR 35323 (August 29, 1990)”">​</a> <a class="header-anchor" href="#_55-fr-35323-august-29-1990" aria-label="Permalink to “55 FR 35323 (August 29, 1990)”">​</a></h3><p>In keeping with the Chemical Diversion and Trafficking Act of 1988 which prohibits the exportation of listed chemicals to any country where their receipt would be in violation of their laws, this proposed amendment to the DEA regulations lists these foreign restrictions, by country and by chemical. 56 FR 5753 = (February 3, 1991) An amendment to the DEA regulations is established, placing the 合成代谢类固醇 in 附表一 (Schedule I)II in accord with the text of PL 101-647. A number of spelling corrections have been made. Chlorotestosterone has been named 4chlorotestosterone; dihydrotestosterone has been named 4-dihydrotestosterone; and formebulone has been named formebolone. A generic drug code number of 4000 has been assigned to these steroids.</p><h3 id="_56-fr-8685-march-1-1991" tabindex="-1">56 FR 8685 (March 1, 1991) <a class="header-anchor" href="#_56-fr-8685-march-1-1991" aria-label="Permalink to “56 FR 8685 (March 1, 1991)”">​</a> <a class="header-anchor" href="#_56-fr-8685-march-1-1991" aria-label="Permalink to “56 FR 8685 (March 1, 1991)”">​</a></h3><p>The AG is amending certain regulations regarding jurisdictional limits of civil forfeiture in order to achieve conformity with recent changes in law (see PL 101-382 (August 20, 1990). These amendments reflect the redesignation of the DEA Asset Forfeiture Unit as the DEA Asset Forfeiture Section and to conform to the INS procedure for the handling of cost bonds to the frocedures of the DEA and the FBI. It is anticipated that this rule will result in more efficient handling of civil forfeiture cases to the extent that more cases will be eligible to be handled administratively.</p><h3 id="_56-fr-10845-march-14-1991" tabindex="-1">56 FR 10845 (March 14, 1991) <a class="header-anchor" href="#_56-fr-10845-march-14-1991" aria-label="Permalink to “56 FR 10845 (March 14, 1991)”">​</a> <a class="header-anchor" href="#_56-fr-10845-march-14-1991" aria-label="Permalink to “56 FR 10845 (March 14, 1991)”">​</a></h3><p>Proposals are made for procedures that would allow exemptions to be made for 合成代谢类固醇 that are to be implanted in animals, and for those which may, due to their concentration, preparation, mixture, or delivery systems, present no significant potential for abuse. The due date for comments is April 15, 1991.</p><h3 id="_56-fr-11931-march-21-1991" tabindex="-1">56 FR 11931 (March 21, 1991) <a class="header-anchor" href="#_56-fr-11931-march-21-1991" aria-label="Permalink to “56 FR 11931 (March 21, 1991)”">​</a> <a class="header-anchor" href="#_56-fr-11931-march-21-1991" aria-label="Permalink to “56 FR 11931 (March 21, 1991)”">​</a></h3><p>Effective this date, the proposal of July 26, 1990 (55 FR 30472) has been made effective, and glutethimide has, as of this date, been 从...移出 附表一 (Schedule I)I to 附表一 (Schedule I)I.</p><h3 id="_56-fr-13854-april-4-1991" tabindex="-1">56 FR 13854 (April 4, 1991) <a class="header-anchor" href="#_56-fr-13854-april-4-1991" aria-label="Permalink to “56 FR 13854 (April 4, 1991)”">​</a> <a class="header-anchor" href="#_56-fr-13854-april-4-1991" aria-label="Permalink to “56 FR 13854 (April 4, 1991)”">​</a></h3><p>A typographical error in 56 FR 11931 has been corrected. 364 THE CONTROLLED SUBSTANCES ACT</p>`,706),n(m),n(h)])}var d=e(l,[[`render`,u]]);export{c as __pageData,d as default};